class Solution {
    func modifyFactorize(_ n: Int) -> [Int] {
        var factors: [Int] = []
        var remaining = n
        var i = 2

        while i <= remaining {
            while remaining % i == 0 {
                factors.append(i)
                remaining /= i
            }
            i += 1
        }

        let sum = factors.reduce(0, +)
        factors.append(sum)
        factors.sort()

        return factors
    }
}
```

