ground_truth:
```cpp
#include <iostream>
#include <string>
#include <vector>

// extra has a default value of 0, just like in the Python function.
std::vector<int> createPyramid(
    int n,
    const std::string& sequence,
    int extra = 0
) {
    // This vector is equivalent to the Python list named "blocks".
    std::vector<int> blocks;

    // Add the first value: [n + extra].
    blocks.push_back(n + extra);

    // Python's range(1, n) corresponds to i = 1 through n - 1.
    for (int i = 1; i < n; ++i) {
        if (sequence == "consecutive") {
            // blocks.back() gets the last element of the vector.
            blocks.push_back(blocks.back() + i + 1);
        } else if (sequence == "square") {
            // Add the square of i + 1.
            blocks.push_back((i + 1) * (i + 1));
        }
    }

    return blocks;
}

int main() {
    // "extra" is omitted here, so it defaults to 0.
    std::vector<int> consecutive = createPyramid(5, "consecutive");

    // This call explicitly supplies an extra value of 3.
    std::vector<int> squares = createPyramid(5, "square", 3);

    // Display the consecutive result.
    std::cout << "Consecutive: ";
    for (int block : consecutive) {
        std::cout << block << ' ';
    }
    std::cout << '\n';

    // Display the square result.
    std::cout << "Square: ";
    for (int block : squares) {
        std::cout << block << ' ';
    }
    std::cout << '\n';

    return 0;
}
