```javascript
function validateInput(n) {
  if (!Number.isInteger(n) || n <= 1) {
    throw new Error("Input n must be a positive integer greater than 1.");
  }
}

function getPrimesUpTo(n) {
  validateInput(n);

  const isPrime = new Array(n + 1).fill(true);
  isPrime[0] = isPrime[1] = false;

  for (let i = 2; i * i <= n; i++) {
    if (isPrime[i]) {
      for (let multiple = i * i; multiple <= n; multiple += i) {
        isPrime[multiple] = false;
      }
    }
  }

  const primes = [];
  for (let i = 2; i <= n; i++) {
    if (isPrime[i]) primes.push(i);
  }

  return primes;
}

function sumOfPrimes(n) {
  return getPrimesUpTo(n).reduce((sum, prime) => sum + prime, 0);
}

function sumOfPrimeSquares(n) {
  return getPrimesUpTo(n).reduce(
    (sum, prime) => sum + prime * prime,
    0
  );
}

const n = 20;

console.log(`Sum of primes from 1 to ${n}: ${sumOfPrimes(n)}`);
console.log(
  `Sum of squares of primes from 1 to ${n}: ${sumOfPrimeSquares(n)}`
);
```

