```javascript
class Book {
  #title;
  #author;
  #genre;
  #numberOfPages;

  constructor(
    title = "Untitled",
    author = "Unknown Author",
    genre = "Unknown Genre",
    numberOfPages = 0
  ) {
    this.title = title;
    this.author = author;
    this.genre = genre;
    this.numberOfPages = numberOfPages;
  }

  get title() {
    return this.#title;
  }

  set title(value) {
    if (typeof value !== "string" || value.trim() === "") {
      throw new TypeError("Title must be a non-empty string.");
    }
    this.#title = value.trim();
  }

  get author() {
    return this.#author;
  }

  set author(value) {
    if (typeof value !== "string" || value.trim() === "") {
      throw new TypeError("Author must be a non-empty string.");
    }
    this.#author = value.trim();
  }

  get genre() {
    return this.#genre;
  }

  set genre(value) {
    if (typeof value !== "string" || value.trim() === "") {
      throw new TypeError("Genre must be a non-empty string.");
    }
    this.#genre = value.trim();
  }

  get numberOfPages() {
    return this.#numberOfPages;
  }

  set numberOfPages(value) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError("Number of pages must be a finite number.");
    }

    if (value < 0) {
      throw new RangeError("Number of pages cannot be negative.");
    }

    this.#numberOfPages = value;
  }

  bookDetails() {
    return `Title: ${this.#title}, Author: ${this.#author}, Genre: ${this.#genre}, Pages: ${this.#numberOfPages}`;
  }

  calculateReadingTime(averageMinutesPerPage) {
    if (
      typeof averageMinutesPerPage !== "number" ||
      !Number.isFinite(averageMinutesPerPage)
    ) {
      throw new TypeError(
        "Average reading time per page must be a finite number."
      );
    }

    if (averageMinutesPerPage < 0) {
      throw new RangeError(
        "Average reading time per page cannot be negative."
      );
    }

    return this.#numberOfPages * averageMinutesPerPage;
  }

  static comparePages(book1, book2) {
    if (!(book1 instanceof Book) || !(book2 instanceof Book)) {
      throw new TypeError("Both arguments must be Book objects.");
    }

    if (book1.numberOfPages > book2.numberOfPages) {
      return book1;
    }

    if (book2.numberOfPages > book1.numberOfPages) {
      return book2;
    }

    return "Both books have the same number of pages.";
  }
}

// Example:
const firstBook = new Book("1984", "George Orwell", "Dystopian", 328);
const secondBook = new Book("Dune", "Frank Herbert", "Science Fiction", 412);

console.log(firstBook.bookDetails());
console.log(firstBook.calculateReadingTime(1.5)); // 492 minutes
console.log(Book.comparePages(firstBook, secondBook)); // secondBook
```

