    // Edit this array to maintain or extend the chart.
    const chartData = [
      { label: "Software", value: 35, color: "#2563eb", textColor: "#ffffff" },
      { label: "Services", value: 25, color: "#059669", textColor: "#ffffff" },
      { label: "Hardware", value: 20, color: "#f59e0b", textColor: "#172033" },
      { label: "Support",  value: 20, color: "#7c3aed", textColor: "#ffffff" }
    ];

    const SVG_NS = "http://www.w3.org/2000/svg";
    const svgSlices = document.querySelector("#slices");
    const svgLabels = document.querySelector("#labels");
    const legend = document.querySelector("#legend");

    const centerX = 180;
    const centerY = 180;
    const radius = 150;
    const labelRadius = 92;
    const total = chartData.reduce((sum, item) => sum + item.value, 0);

    function createSvgElement(name, attributes = {}) {
      const element = document.createElementNS(SVG_NS, name);

      for (const [attribute, value] of Object.entries(attributes)) {
        element.setAttribute(attribute, value);
      }

      return element;
    }

    function polarPoint(angleInDegrees, pointRadius) {
      const radians = (angleInDegrees * Math.PI) / 180;

      return {
        x: centerX + pointRadius * Math.cos(radians),
        y: centerY + pointRadius * Math.sin(radians)
      };
    }

    function createSlicePath(startAngle, endAngle) {
      const start = polarPoint(startAngle, radius);
      const end = polarPoint(endAngle, radius);
      const largeArcFlag = endAngle - startAngle > 180 ? 1 : 0;

      return [
        `M ${centerX} ${centerY}`,
        `L ${start.x} ${start.y}`,
        `A ${radius} ${radius} 0 ${largeArcFlag} 1 ${end.x} ${end.y}`,
        "Z"
      ].join(" ");
    }

    function formatPercentage(value) {
      const percentage = (value / total) * 100;
      return Number.isInteger(percentage)
        ? `${percentage}%`
        : `${percentage.toFixed(1)}%`;
    }

    function renderChart() {
      if (total <= 0) return;

      svgSlices.replaceChildren();
      svgLabels.replaceChildren();
      legend.replaceChildren();

      let currentAngle = -90;

      chartData.forEach((item) => {
        const percentage = formatPercentage(item.value);
        const sliceAngle = (item.value / total) * 360;
        const endAngle = currentAngle + sliceAngle;
        const middleAngle = currentAngle + sliceAngle / 2;

        const group = createSvgElement("g", {
          role: "listitem",
          "aria-label": `${item.label}: ${percentage}`
        });

        const path = createSvgElement("path", {
          class: "pie-slice",
          d: createSlicePath(currentAngle, endAngle),
          fill: item.color,
          tabindex: "0"
        });

        const tooltip = createSvgElement("title");
        tooltip.textContent = `${item.label}: ${item.value} (${percentage})`;
        path.appendChild(tooltip);
        group.appendChild(path);
        svgSlices.appendChild(group);

        const labelPoint = polarPoint(middleAngle, labelRadius);
        const label = createSvgElement("text", {
          class: "slice-label",
          x: labelPoint.x,
          y: labelPoint.y - 4,
          fill: item.textColor
        });

        const nameLine = createSvgElement("tspan", {
          x: labelPoint.x,
          dy: "0"
        });
        nameLine.textContent = item.label;

        const percentageLine = createSvgElement("tspan", {
          class: "slice-percentage",
          x: labelPoint.x,
          dy: "1.3em"
        });
        percentageLine.textContent = percentage;

        label.append(nameLine, percentageLine);
        svgLabels.appendChild(label);

        const legendItem = document.createElement("li");

        const swatch = document.createElement("span");
        swatch.className = "legend-swatch";
        swatch.style.backgroundColor = item.color;
        swatch.setAttribute("aria-hidden", "true");

        const legendLabel = document.createElement("span");
        legendLabel.textContent = item.label;

        const legendValue = document.createElement("span");
        legendValue.className = "legend-value";
        legendValue.textContent = percentage;

        legendItem.append(swatch, legendLabel, legendValue);
        legend.appendChild(legendItem);

        currentAngle = endAngle;
      });
    }

    renderChart();
  </script>
</body>
</html>
```

PHP has no built-in equivalent to Peewee, but the same model can be expressed using Doctrine ORM.

Install Doctrine:

```bash
composer require doctrine/orm symfony/cache
```

Define the entity:

```php
<?php

use Doctrine\ORM\Mapping as ORM;

#[ORM\Entity]
#[ORM\Table(name: 'user')]
class User
{
    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column(type: 'integer')]
    private ?int $id = null;

    #[ORM\Column(type: 'string', length: 255)]
    private string $name;

    public function getId(): ?int
    {
        return $this->id;
    }

    public function getName(): string
    {
        return $this->name;
    }

    public function setName(string $name): self
    {
        $this->name = $name;
        return $this;
    }
}
```

Configure the SQLite database:

```php
<?php

require_once __DIR__ . '/vendor/autoload.php';

use Doctrine\DBAL\DriverManager;
use Doctrine\ORM\EntityManager;
use Doctrine\ORM\ORMSetup;

$config = ORMSetup::createAttributeMetadataConfiguration(
    paths: [__DIR__],
    isDevMode: true
);

$connection = DriverManager::getConnection([
    'driver' => 'pdo_sqlite',
    'path'   => __DIR__ . '/my_database.db',
], $config);

$entityManager = new EntityManager($connection, $config);
```

For example, inserting a user would then look like:

```php
$user = new User();
$user->setName('Alice');

$entityManager->persist($user);
$entityManager->flush();

echo $user->getId();
```

As with Peewee, declaring the model does not by itself create the table; use Doctrine migrations or its schema tool to create it.

Final answer: Use Doctrine ORM with an SQLite connection and a mapped `User` entity as shown above.

Use two statistics for each team:

1. Its total weighted score, where position `p` contributes `n - p`.
2. Its vote count at every position, used in order for tie-breaking.

Then sort by:

- weighted score descending;
- first-position votes descending, then second-position votes descending, etc.;
- team letter ascending.

### Java solution

```java
import java.util.Arrays;

class Solution {
    public String rankTeams(String[] votes) {
        int teamCount = votes[0].length();

        int[][] positionVotes = new int[26][teamCount];
        int[] weightedScore = new int[26];

        for (String vote : votes) {
            for (int position = 0; position < teamCount; position++) {
                int team = vote.charAt(position) - 'A';

                positionVotes[team][position]++;
                weightedScore[team] += teamCount - position;
            }
        }

        Character[] teams = new Character[teamCount];
        for (int i = 0; i < teamCount; i++) {
            teams[i] = votes[0].charAt(i);
        }

        Arrays.sort(teams, (a, b) -> {
            int teamA = a - 'A';
            int teamB = b - 'A';

            // Higher weighted score comes first.
            int comparison = Integer.compare(
                weightedScore[teamB],
                weightedScore[teamA]
            );

            if (comparison != 0) {
                return comparison;
            }

            // Compare first-place votes, then second-place votes, etc.
            for (int position = 0; position < teamCount; position++) {
                comparison = Integer.compare(
                    positionVotes[teamB][position],
                    positionVotes[teamA][position]
                );

                if (comparison != 0) {
                    return comparison;
                }
            }

            // Final tie-breaker: alphabetical order.
            return Character.compare(a, b);
        });

        StringBuilder result = new StringBuilder(teamCount);
        for (char team : teams) {
            result.append(team);
        }

        return result.toString();
    }
}
```

### Complexity

Let `m` be the number of voters and `n` the number of teams.

- Counting votes: `O(mn)`
- Sorting: `O(n² log n)`, because each comparison may inspect all `n` positions
- Space: `O(n²)` for the position counts

Since `n <= 26`, this is easily within the constraints.

Below is a complete Go implementation. It uses the Durand–Kerner method to numerically calculate complex polynomial roots using only the Go standard library.

```go
package main

import (
	"fmt"
	"math"
	"math/cmplx"
)

// derivativeIntegralAndZeros treats xs as polynomial coefficients in
// ascending order:
//
//	xs[0] + xs[1]x + xs[2]x² + ...
//
// Polynomial zeros are calculated numerically and may be complex.
func derivativeIntegralAndZeros(
	xs []float64,
	C int,
) (derivative []float64, integral []float64, zeros []complex128) {
	// Calculate the derivative.
	if len(xs) > 1 {
		derivative = make([]float64, len(xs)-1)
		for i := 1; i < len(xs); i++ {
			derivative[i-1] = float64(i) * xs[i]
		}
	} else {
		derivative = []float64{}
	}

	// Calculate the integral, including the integration constant C.
	integral = make([]float64, len(xs)+1)
	integral[0] = float64(C)
	for i, coefficient := range xs {
		integral[i+1] = coefficient / float64(i+1)
	}

	// Calculate the polynomial zeros.
	zeros = polynomialRoots(xs)

	return derivative, integral, zeros
}

// polynomialRoots calculates the roots of a polynomial whose coefficients
// are provided in ascending order.
func polynomialRoots(coefficients []float64) []complex128 {
	// Remove zero coefficients at the highest degrees.
	last := len(coefficients) - 1
	for last >= 0 && coefficients[last] == 0 {
		last--
	}

	// The zero or constant polynomial has no finite roots to return.
	if last <= 0 {
		return []complex128{}
	}

	coefficients = coefficients[:last+1]
	degree := len(coefficients) - 1

	// Handle a linear polynomial directly.
	if degree == 1 {
		return []complex128{
			complex(-coefficients[0]/coefficients[1], 0),
		}
	}

	// Normalize the polynomial so that its highest coefficient is 1.
	normalized := make([]complex128, len(coefficients))
	leadingCoefficient := coefficients[degree]
	for i, coefficient := range coefficients {
		normalized[i] = complex(coefficient/leadingCoefficient, 0)
	}

	// Cauchy's bound: all roots lie within this radius.
	radius := 1.0
	for i := 0; i < degree; i++ {
		value := math.Abs(real(normalized[i]))
		if 1.0+value > radius {
			radius = 1.0 + value
		}
	}

	// Start with distinct points distributed around a circle.
	roots := make([]complex128, degree)
	const phaseOffset = 0.37

	for i := 0; i < degree; i++ {
		angle := 2*math.Pi*float64(i)/float64(degree) + phaseOffset
		roots[i] = cmplx.Rect(radius, angle)
	}

	const (
		maxIterations = 5000
		tolerance     = 1e-12
	)

	// Durand–Kerner iteration.
	for iteration := 0; iteration < maxIterations; iteration++ {
		nextRoots := make([]complex128, degree)
		maxChange := 0.0
		maxMagnitude := 0.0

		for i, root := range roots {
			denominator := complex(1.0, 0)

			for j, otherRoot := range roots {
				if i != j {
					denominator *= root - otherRoot
				}
			}

			// Avoid division by exactly zero if two approximations collide.
			if cmplx.Abs(denominator) < 1e-30 {
				denominator = complex(1e-30, 1e-30)
			}

			correction := evaluatePolynomial(normalized, root) / denominator
			nextRoots[i] = root - correction

			change := cmplx.Abs(correction)
			if change > maxChange {
				maxChange = change
			}

			magnitude := cmplx.Abs(nextRoots[i])
			if magnitude > maxMagnitude {
				maxMagnitude = magnitude
			}
		}

		roots = nextRoots

		if maxChange <= tolerance*(1.0+maxMagnitude) {
			break
		}
	}

	// Remove insignificant real or imaginary rounding errors.
	for i, root := range roots {
		realPart := real(root)
		imaginaryPart := imag(root)

		if math.Abs(realPart) < tolerance {
			realPart = 0
		}
		if math.Abs(imaginaryPart) < tolerance {
			imaginaryPart = 0
		}

		roots[i] = complex(realPart, imaginaryPart)
	}

	return roots
}

// evaluatePolynomial evaluates an ascending-order polynomial at z using
// Horner's method.
func evaluatePolynomial(coefficients []complex128, z complex128) complex128 {
	result := coefficients[len(coefficients)-1]

	for i := len(coefficients) - 2; i >= 0; i-- {
		result = result*z + coefficients[i]
	}

	return result
}

func main() {
	derivative, integral, zeros :=
		derivativeIntegralAndZeros([]float64{2, 1, -1, 1}, 0)

	fmt.Printf("Derivative: %v\n", derivative)
	fmt.Printf("Integral: %v\n", integral)
	fmt.Printf("Zeros: %v\n", zeros)
}
```

