```javascript
// mac-validator.js

function validateMacAddress(macAddress) {
    if (typeof macAddress !== "string") {
        return {
            valid: false,
            error: "The MAC address must be a string."
        };
    }

    // Accept six hexadecimal octets separated consistently by ":" or "-".
    const macPattern =
        /^([0-9A-Fa-f]{2})([:-])(?:[0-9A-Fa-f]{2}\2){4}[0-9A-Fa-f]{2}$/;

    const match = macAddress.match(macPattern);

    if (!match) {
        return {
            valid: false,
            error: "Invalid MAC address format."
        };
    }

    const firstOctet = parseInt(match[1], 16);

    // Bit 0 (least significant bit) is the Individual/Group bit:
    // 0 = unicast, 1 = multicast.
    const transmissionType =
        (firstOctet & 0b00000001) === 0 ? "unicast" : "multicast";

    // Bit 1 is the Universal/Local bit:
    // 0 = universally administered, 1 = locally administered.
    const administrationType =
        (firstOctet & 0b00000010) === 0
            ? "universally administered"
            : "locally administered";

    return {
        valid: true,
        normalizedAddress: macAddress.replace(/-/g, ":").toUpperCase(),
        transmissionType,
        administrationType
    };
}

// Read the MAC address from the command line.
const macAddress = process.argv[2];

if (!macAddress) {
    console.error("Usage: node mac-validator.js <MAC-address>");
    process.exit(1);
}

const result = validateMacAddress(macAddress);

if (!result.valid) {
    console.error(result.error);
    process.exit(1);
}

console.log(`MAC address: ${result.normalizedAddress}`);
console.log(`Address type: ${result.transmissionType}`);
console.log(`Administration: ${result.administrationType}`);
```

Example:

```bash
node mac-validator.js 02:42:AC:11:00:02
```

Output:

```text
MAC address: 02:42:AC:11:00:02
Address type: unicast
Administration: locally administered
```

Final answer: The program validates six-octet colon- or hyphen-separated MAC addresses and classifies them using bits 0 and 1 of the first octet.

