import java.math.BigInteger;
import java.util.Locale;
import java.util.StringJoiner;

class Solution {

    /**
     * Converts an already evaluated, non-negative integer value to binary.
     *
     * Java integers do not retain their original numeral-system notation, so
     * convertToBinary("octal", 20) treats 20 as the numeric value twenty, as
     * required by the example.
     */
    public String convertToBinary(String numberSystem, int number) {
        validateNumberSystem(numberSystem);

        if (number < 0) {
            throw new IllegalArgumentException("The number must be non-negative");
        }

        return formatBinary(Integer.toBinaryString(number));
    }

    /**
     * Converts digits written in the specified numeral system.
     *
     * Examples:
     * convertToBinary("octal", "20") -> "db-1-0-0-0-0-db"
     * convertToBinary("hexa", "A")   -> "db-1-0-1-0-db"
     */
    public String convertToBinary(String numberSystem, String number) {
        int radix = validateNumberSystem(numberSystem);

        if (number == null) {
            throw new IllegalArgumentException("Number must not be null");
        }

        String value = number.trim();
        if (value.isEmpty()) {
            throw new IllegalArgumentException("Number must not be empty");
        }

        // Accept conventional prefixes when they match the selected system.
        if (radix == 16 && (value.startsWith("0x") || value.startsWith("0X"))) {
            value = value.substring(2);
        } else if (radix == 8 && (value.startsWith("0o") || value.startsWith("0O"))) {
            value = value.substring(2);
        }

        if (value.isEmpty() || value.charAt(0) == '-') {
            throw new IllegalArgumentException(
                "The number must be a valid non-negative " + numberSystem + " value"
            );
        }

        try {
            BigInteger parsed = new BigInteger(value, radix);
            return formatBinary(parsed.toString(2));
        } catch (NumberFormatException exception) {
            throw new IllegalArgumentException(
                "'" + number + "' is not a valid " + numberSystem + " number",
                exception
            );
        }
    }

    /**
     * Supports calls such as convertToBinary("hexa", 'A').
     */
    public String convertToBinary(String numberSystem, char number) {
        return convertToBinary(numberSystem, String.valueOf(number));
    }

    private int validateNumberSystem(String numberSystem) {
        if (numberSystem == null) {
            throw new IllegalArgumentException("Number system must not be null");
        }

        switch (numberSystem.trim().toLowerCase(Locale.ROOT)) {
            case "decimal":
            case "dec":
                return 10;

            case "octal":
            case "oct":
                return 8;

            case "hexa":
            case "hex":
            case "hexadecimal":
                return 16;

            default:
                throw new IllegalArgumentException(
                    "Unsupported number system: " + numberSystem
                );
        }
    }

    private String formatBinary(String binary) {
        StringJoiner result = new StringJoiner("-", "db-", "-db");

        for (int i = 0; i < binary.length(); i++) {
            result.add(String.valueOf(binary.charAt(i)));
        }

        return result.toString();
    }
}
