Microsoft Edge’s browser engine is primarily implemented in **C++**. The following C++ console program uses **libcurl** to perform an HTTP/HTTPS GET request, follow redirects, inspect the response, and print the returned page content.

### `main.cpp`

```cpp
#include <curl/curl.h>

#include <cstdlib>
#include <iostream>
#include <limits>
#include <string>

namespace {
constexpr std::size_t MAX_PAGE_SIZE = 20 * 1024 * 1024; // 20 MiB

struct ResponseBody {
    std::string content;
    bool sizeLimitExceeded = false;
};

size_t writeCallback(char* data, size_t size, size_t count, void* userData) {
    auto* body = static_cast<ResponseBody*>(userData);

    if (size != 0 && count > std::numeric_limits<size_t>::max() / size) {
        return 0;
    }

    const size_t bytes = size * count;

    if (bytes > MAX_PAGE_SIZE - body->content.size()) {
        body->sizeLimitExceeded = true;
        return 0; // Causes libcurl to stop with CURLE_WRITE_ERROR.
    }

    try {
        body->content.append(data, bytes);
    } catch (...) {
        return 0;
    }

    return bytes;
}

class CurlGlobalContext {
public:
    CurlGlobalContext()
        : initialized_(curl_global_init(CURL_GLOBAL_DEFAULT) == CURLE_OK) {}

    ~CurlGlobalContext() {
        if (initialized_) {
            curl_global_cleanup();
        }
    }

    CurlGlobalContext(const CurlGlobalContext&) = delete;
    CurlGlobalContext& operator=(const CurlGlobalContext&) = delete;

    bool initialized() const {
        return initialized_;
    }

private:
    bool initialized_;
};
} // namespace

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: simple_browser <http-or-https-url>\n";
        return EXIT_FAILURE;
    }

    const std::string url = argv[1];

    CurlGlobalContext curlContext;
    if (!curlContext.initialized()) {
        std::cerr << "Failed to initialize libcurl.\n";
        return EXIT_FAILURE;
    }

    CURL* curl = curl_easy_init();
    if (curl == nullptr) {
        std::cerr << "Failed to create an HTTP client.\n";
        return EXIT_FAILURE;
    }

    ResponseBody responseBody;
    char errorBuffer[CURL_ERROR_SIZE] = {};

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errorBuffer);

    // Behave like a small browser.
    curl_easy_setopt(curl, CURLOPT_USERAGENT,
                     "SimpleCppBrowser/1.0 (libcurl)");
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 10L);
    curl_easy_setopt(curl, CURLOPT_ACCEPT_ENCODING, "");

    // Only allow HTTP and HTTPS, including after redirects.
    curl_easy_setopt(curl, CURLOPT_PROTOCOLS,
                     static_cast<long>(CURLPROTO_HTTP | CURLPROTO_HTTPS));
    curl_easy_setopt(curl, CURLOPT_REDIR_PROTOCOLS,
                     static_cast<long>(CURLPROTO_HTTP | CURLPROTO_HTTPS));

    // Timeouts prevent the program from waiting indefinitely.
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30L);

    // Keep TLS certificate verification enabled.
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 1L);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 2L);

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &responseBody);

    const CURLcode result = curl_easy_perform(curl);

    if (result != CURLE_OK) {
        if (responseBody.sizeLimitExceeded) {
            std::cerr << "Response exceeded the "
                      << MAX_PAGE_SIZE
                      << "-byte size limit.\n";
        } else {
            std::cerr << "Request failed: "
                      << (errorBuffer[0] != '\0'
                              ? errorBuffer
                              : curl_easy_strerror(result))
                      << '\n';
        }

        curl_easy_cleanup(curl);
        return EXIT_FAILURE;
    }

    long statusCode = 0;
    char* effectiveUrl = nullptr;
    char* contentType = nullptr;

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &statusCode);
    curl_easy_getinfo(curl, CURLINFO_EFFECTIVE_URL, &effectiveUrl);
    curl_easy_getinfo(curl, CURLINFO_CONTENT_TYPE, &contentType);

    std::cout << "Effective URL: "
              << (effectiveUrl != nullptr ? effectiveUrl : url.c_str())
              << '\n';
    std::cout << "HTTP status: " << statusCode << '\n';
    std::cout << "Content-Type: "
              << (contentType != nullptr ? contentType : "unknown")
              << "\n\n";
    std::cout << "----- Page content -----\n";
    std::cout.write(responseBody.content.data(),
                    static_cast<std::streamsize>(responseBody.content.size()));
    std::cout << "\n----- End page content -----\n";

    curl_easy_cleanup(curl);

    // libcurl successfully received a response, but expose HTTP errors
    // through the process exit status.
    return statusCode >= 400 ? 2 : EXIT_SUCCESS;
}
```

