public class AdditionGUI extends JFrame {
    private final JTextField firstNumberField = new JTextField(12);
    private final JTextField secondNumberField = new JTextField(12);
    private final JLabel resultLabel = new JLabel(" ");

    public AdditionGUI() {
        super("Number Addition");

        JButton addButton = new JButton("Add");
        addButton.addActionListener(e -> addNumbers());

        JPanel panel = new JPanel(new GridLayout(4, 2, 8, 8));
        panel.setBorder(BorderFactory.createEmptyBorder(15, 15, 15, 15));

        panel.add(new JLabel("First number:"));
        panel.add(firstNumberField);
        panel.add(new JLabel("Second number:"));
        panel.add(secondNumberField);
        panel.add(new JLabel("Result:"));
        panel.add(resultLabel);
        panel.add(new JLabel());
        panel.add(addButton);

        getRootPane().setDefaultButton(addButton);
        add(panel);

        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        pack();
        setLocationRelativeTo(null);
        setResizable(false);
    }

    private void addNumbers() {
        try {
            BigDecimal first =
                    new BigDecimal(firstNumberField.getText().trim());
            BigDecimal second =
                    new BigDecimal(secondNumberField.getText().trim());

            BigDecimal sum = first.add(second).stripTrailingZeros();
            resultLabel.setText(sum.toPlainString());
        } catch (NumberFormatException ex) {
            resultLabel.setText("Invalid input");
            JOptionPane.showMessageDialog(
                    this,
                    "Please enter two valid numbers.",
                    "Input Error",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new AdditionGUI().setVisible(true));
    }
}
