class EpisodeStatus(str, Enum):
    DRAFT = "draft"
    SCHEDULED = "scheduled"
    PUBLISHED = "published"
    ARCHIVED = "archived"


@dataclass(frozen=True, slots=True, order=True)
class Chapter:
    """A navigable chapter within an episode."""

    start_seconds: float
    title: str
    url: str | None = None
    image_url: str | None = None

    def __post_init__(self) -> None:
        if self.start_seconds < 0:
            raise ValueError("Chapter start time cannot be negative.")
        if not self.title.strip():
            raise ValueError("Chapter title cannot be empty.")

