        if self.url is not None:
            _validate_url(self.url, "chapter URL")
        if self.image_url is not None:
            _validate_url(self.image_url, "chapter image URL")


@dataclass(frozen=True, slots=True, order=True)
class TranscriptSegment:
    """A timestamped portion of an episode transcript."""

    start_seconds: float
    end_seconds: float
    text: str = field(compare=False)
    speaker: str | None = field(default=None, compare=False)

    def __post_init__(self) -> None:
