```javascript
/**
 * Finds <input type="text"> elements that contain a specified attribute,
 * optionally attaches a change listener, and returns the number found.
 *
 * @param {string} attributeName Attribute whose existence should be checked.
 * @param {Function} [changeHandler] Optional change-event handler.
 * @param {Document|Element} [root=document] Node within which to search.
 * @returns {number}
 */
function processTextInputs(attributeName, changeHandler, root) {
    root = root || document;

    var inputs = root.getElementsByTagName("input");
    var count = 0;

    for (var i = 0; i < inputs.length; i++) {
        var input = inputs[i];

        // The DOM type property is normalized and also handles the default
        // input type, which is "text" when no type is specified.
        if (String(input.type).toLowerCase() !== "text") {
            continue;
        }

        // hasAttribute is preferred; getAttributeNode supports older browsers.
        var hasRequestedAttribute;
        if (typeof input.hasAttribute === "function") {
            hasRequestedAttribute = input.hasAttribute(attributeName);
        } else {
            var attributeNode = input.getAttributeNode(attributeName);
            hasRequestedAttribute = !!(attributeNode && attributeNode.specified);
        }

        if (!hasRequestedAttribute) {
            continue;
        }

        count++;

        if (typeof changeHandler === "function") {
            if (input.addEventListener) {
                input.addEventListener("change", changeHandler, false);
            } else if (input.attachEvent) {
                // Compatibility with older versions of Internet Explorer.
                (function (element) {
                    element.attachEvent("onchange", function () {
                        changeHandler.call(element, window.event);
                    });
                }(input));
            } else {
                input.onchange = changeHandler;
            }
        }
    }

    return count;
}

// Example: count text inputs having a "data-track" attribute and listen for changes.
var count = processTextInputs("data-track", function (event) {
    console.log("Changed:", this.value);
});

console.log("Matching inputs:", count);
```

The native event name is `"change"` for `addEventListener` and `"onchange"` for legacy `attachEvent`.

Final answer: `processTextInputs` returns the number of text inputs containing the requested attribute and optionally registers a cross-browser change handler on each one.

