The following C++17 program expects an array length followed by that many signed integers. It rejects invalid or incomplete input, negative or excessively large lengths, allocation failure, and arithmetic overflow. An empty array is valid and has a sum of zero.

```cpp
#include <iostream>
#include <limits>
#include <new>
#include <vector>

bool calculateSum(const std::vector<long long>& values, long long& result)
{
    long long sum = 0;

    for (long long value : values) {
        // Check for overflow before performing the addition.
        if ((value > 0 &&
             sum > std::numeric_limits<long long>::max() - value) ||
            (value < 0 &&
             sum < std::numeric_limits<long long>::min() - value)) {
            return false;
        }

        sum += value;
    }

    result = sum;
    return true;
}

int main()
{
    std::cout << "Enter the number of elements followed by the elements:\n";

    long long inputSize;
    if (!(std::cin >> inputSize)) {
        std::cerr << "Error: the array size must be an integer.\n";
        return 1;
    }

    if (inputSize < 0) {
        std::cerr << "Error: the array size cannot be negative.\n";
        return 1;
    }

    const auto requestedSize = static_cast<unsigned long long>(inputSize);
    const std::vector<long long> emptyVector;

    if (requestedSize > emptyVector.max_size()) {
        std::cerr << "Error: the requested array is too large.\n";
        return 1;
    }

    std::vector<long long> values;

    try {
        values.resize(static_cast<std::size_t>(requestedSize));
    } catch (const std::bad_alloc&) {
        std::cerr << "Error: insufficient memory for the array.\n";
        return 1;
    }

    for (std::size_t i = 0; i < values.size(); ++i) {
        if (!(std::cin >> values[i])) {
            std::cerr << "Error: element " << i
                      << " is missing or is not a valid integer.\n";
            return 1;
        }
    }

    long long sum;
    if (!calculateSum(values, sum)) {
        std::cerr << "Error: the sum exceeds the range of long long.\n";
        return 1;
    }

    std::cout << "Sum: " << sum << '\n';
    return 0;
}
