Below is a C++20 implementation using `std::deque`. Each nontrivial recursive partition is processed by a newly created thread, including the initial partition.

```cpp
#include <cstddef>
#include <deque>
#include <functional>
#include <iostream>
#include <syncstream>
#include <thread>
#include <utility>

using Index = std::ptrdiff_t;

/*
 * Three-way partition:
 *
 * [low, lessEnd)       elements less than pivot
 * [lessEnd, equalEnd]  elements equal to pivot
 * (equalEnd, high]     elements greater than pivot
 *
 * Three-way partitioning also avoids excessive recursion when the deque
 * contains many duplicate values.
 */
template <typename T, typename Compare>
std::pair<Index, Index> partitionDeque(
    std::deque<T>& values,
    Index low,
    Index high,
    Compare compare)
{
    const Index pivotIndex = low + (high - low) / 2;
    const T pivot = values[static_cast<std::size_t>(pivotIndex)];

    Index lessEnd = low;
    Index current = low;
    Index greaterStart = high;

    while (current <= greaterStart) {
        T& element = values[static_cast<std::size_t>(current)];

        if (compare(element, pivot)) {
            std::swap(
                values[static_cast<std::size_t>(lessEnd)],
                values[static_cast<std::size_t>(current)]
            );

            ++lessEnd;
            ++current;
        } else if (compare(pivot, element)) {
            std::swap(
                values[static_cast<std::size_t>(current)],
                values[static_cast<std::size_t>(greaterStart)]
            );

            --greaterStart;

            // Do not increment current because the swapped-in element
            // has not yet been examined.
        } else {
            ++current;
        }
    }

    return {lessEnd, greaterStart};
}

template <typename T, typename Compare>
void threadedQuickSortImpl(
    std::deque<T>& values,
    Index low,
    Index high,
    Compare compare)
{
    if (low >= high) {
        return;
    }

    // This partition executes on the thread that invoked this function.
    const auto [equalBegin, equalEnd] =
        partitionDeque(values, low, high, compare);

    std::osyncstream(std::cout)
        << "Thread " << std::this_thread::get_id()
        << " partitioned range [" << low << ", " << high << "]\n";

    std::thread leftThread;
    std::thread rightThread;

    // At least two elements must exist for another partition to be needed.
    if (equalBegin - low > 1) {
        const Index leftHigh = equalBegin - 1;

        leftThread = std::thread(
            [&values, low, leftHigh, compare]() mutable {
                threadedQuickSortImpl(values, low, leftHigh, compare);
            }
        );
    }

    if (high - equalEnd > 1) {
        const Index rightLow = equalEnd + 1;

        rightThread = std::thread(
            [&values, rightLow, high, compare]() mutable {
                threadedQuickSortImpl(values, rightLow, high, compare);
            }
        );
    }

    // A partition must not return until both of its subpartitions finish.
    if (leftThread.joinable()) {
        leftThread.join();
    }

    if (rightThread.joinable()) {
        rightThread.join();
    }
}

template <typename T, typename Compare = std::less<T>>
void threadedQuickSort(
    std::deque<T>& values,
    Compare compare = Compare{})
{
    if (values.size() < 2) {
        return;
    }

    // Start the root partition on its own thread as well.
    std::thread rootThread(
        [&values, compare]() mutable {
            threadedQuickSortImpl(
                values,
                0,
                static_cast<Index>(values.size()) - 1,
                compare
            );
        }
    );

    rootThread.join();
}

template <typename T>
void printDeque(const std::deque<T>& values)
{
    for (const T& value : values) {
        std::cout << value << ' ';
    }
    std::cout << '\n';
}

int main()
{
    std::deque<int> values{
        42, 7, 19, 3, 88, 25, 7, 1, 64, 12, 42, 5
    };

    std::cout << "Before sorting: ";
    printDeque(values);

    threadedQuickSort(values);

    std::cout << "After sorting:  ";
    printDeque(values);

    return 0;
}
```

Compile it with thread support:

```bash
g++ -std=c++20 -O2 -pthread threaded_quicksort.cpp -o threaded_quicksort
./threaded_quicksort
```

The algorithm operates as follows:

1. Select a pivot and partition the current deque range into values smaller than, equal to, and greater than the pivot.
2. Start separate threads for the left and right subranges that still require sorting.
3. Each child thread repeats the partitioning process and creates its own child threads.
4. Join both child threads before returning.
5. Because child ranges are disjoint and no elements are inserted into or removed from the deque, the threads do not modify the same elements concurrently.

This literal thread-per-partition design is primarily educational. It can create up to \(O(n)\) operating-system threads and exhaust system resources for large inputs. A production implementation should normally submit partition tasks to a bounded thread pool or stop creating threads below a size threshold.

