ground_truth:
C#’s static typing makes the `isinstance` checks unnecessary, although `x` should still be checked for `null`. Using `BigInteger` preserves Python’s arbitrary-precision integer behavior:

```csharp
using System;
using System.Numerics;
using System.Text;

public static class NumberConverter
{
    public static string NumberToBinary(string x, int numberBase)
    {
        if (x is null)
            throw new ArgumentNullException(nameof(x), "Input x must be a string.");

        if (numberBase is not (8 or 10 or 16))
        {
            throw new ArgumentOutOfRangeException(
                nameof(numberBase),
                "Base must be 8 (octal), 10 (decimal), or 16 (hexadecimal).");
        }

        string text = x.Trim();

        if (text.Length == 0)
            throw new FormatException("Input x is not a valid number.");

        int position = 0;
        bool negative = false;

        if (text[position] is '+' or '-')
        {
            negative = text[position] == '-';
            position++;

            if (position == text.Length)
                throw new FormatException("Input x is not a valid number.");
        }

        // Support optional 0x and 0o prefixes, as Python's int does.
        if (position + 1 < text.Length && text[position] == '0')
        {
            char prefix = char.ToLowerInvariant(text[position + 1]);

            if ((numberBase == 16 && prefix == 'x') ||
                (numberBase == 8 && prefix == 'o'))
            {
                position += 2;
            }
        }

        if (position == text.Length)
            throw new FormatException("Input x is not a valid number.");

        BigInteger value = BigInteger.Zero;

        for (; position < text.Length; position++)
        {
            int digit = GetDigitValue(text[position]);

            if (digit < 0 || digit >= numberBase)
            {
                throw new FormatException(
                    $"Character '{text[position]}' is invalid for base {numberBase}.");
            }

            value = value * numberBase + digit;
        }

        if (value.IsZero)
            return "0";

        var binary = new StringBuilder();

        while (value > 0)
        {
            binary.Append(value.IsEven ? '0' : '1');
            value >>= 1;
        }

        char[] characters = binary.ToString().ToCharArray();
        Array.Reverse(characters);

        return negative ? "-" + new string(characters) : new string(characters);
    }

    private static int GetDigitValue(char character)
    {
        if (character is >= '0' and <= '9')
            return character - '0';

        if (character is >= 'a' and <= 'f')
            return character - 'a' + 10;

        if (character is >= 'A' and <= 'F')
            return character - 'A' + 10;

        return -1;
    }
}
```

Example:

```csharp
Console.WriteLine(NumberConverter.NumberToBinary("17", 10)); // 10001
Console.WriteLine(NumberConverter.NumberToBinary("21", 8));  // 10001
Console.WriteLine(NumberConverter.NumberToBinary("11", 16)); // 10001
Console.WriteLine(NumberConverter.NumberToBinary("FF", 16)); // 11111111
```

This also returns a sensible result for negative inputs, such as `"-101"`. The original Python expression `bin(int(x, base))[2:]` mishandles negatives: for `-5`, it produces `"b101"` because it slices `"-0b101"` starting at index 2.

Final answer: The `NumberToBinary` C# implementation above provides the equivalent conversion while retaining arbitrary-precision support.

