ground_truth:
An exact minimum and maximum cannot be found in sublinear time because every element must be inspected. However, a pairwise tournament finds both in one pass using about \(3n/2\) comparisons instead of the roughly \(2n\) comparisons required by two separate searches.

```cpp
#include <cstddef>
#include <vector>

using namespace std;

vector<float> rescale_to_unit(vector<float> numbers) {
    const size_t n = numbers.size();

    if (n == 0) {
        return numbers;
    }

    float min_value;
    float max_value;
    size_t i;

    // Initialize from either one element or the first pair.
    if (n % 2 == 0) {
        if (numbers[0] < numbers[1]) {
            min_value = numbers[0];
            max_value = numbers[1];
        } else {
            min_value = numbers[1];
            max_value = numbers[0];
        }
        i = 2;
    } else {
        min_value = max_value = numbers[0];
        i = 1;
    }

    // Compare elements in pairs: one comparison within each pair,
    // followed by one comparison against each current extreme.
    for (; i + 1 < n; i += 2) {
        float pair_min;
        float pair_max;

        if (numbers[i] < numbers[i + 1]) {
            pair_min = numbers[i];
            pair_max = numbers[i + 1];
        } else {
            pair_min = numbers[i + 1];
            pair_max = numbers[i];
        }

        if (pair_min < min_value) {
            min_value = pair_min;
        }
        if (pair_max > max_value) {
            max_value = pair_max;
        }
    }

    // A constant vector cannot have its sole value mapped to both 0 and 1.
    // By convention, map it to all zeros.
    if (min_value == max_value) {
        for (float& value : numbers) {
            value = 0.0f;
        }
        return numbers;
    }

    // Use double for the subtraction to avoid overflow when the input
    // contains very large finite floats of opposite signs.
    const double minimum = static_cast<double>(min_value);
    const double range =
        static_cast<double>(max_value) - static_cast<double>(min_value);

    for (float& value : numbers) {
        value = static_cast<float>(
            (static_cast<double>(value) - minimum) / range
        );
    }

    return numbers;
}
```

The transformation is \(y=(x-\min)/(\max-\min)\). The total running time is necessarily \(O(n)\), with \(O(1)\) auxiliary space beyond the returned vector.

