import unittest


class Person:
    VALID_GENDERS = {"Male", "Female", "Other"}

    def __init__(self, name: str, age: int, gender: str):
        self.__name = self._validate_name(name)
        self.__age = self._validate_age(age)
        self.__gender = self._validate_gender(gender)

    @staticmethod
    def _validate_name(name: str) -> str:
        if not isinstance(name, str):
            raise TypeError("Name must be a string.")

        name = name.strip()
        if not name:
            raise ValueError("Name must not be empty.")
        if any(character.isdigit() for character in name):
            raise ValueError("Name must not contain digits.")

        return name

    @staticmethod
    def _validate_age(age: int) -> int:
        # bool is a subclass of int in Python, so it must be rejected explicitly.
        if isinstance(age, bool) or not isinstance(age, int):
            raise TypeError("Age must be an integer.")
        if not 1 <= age <= 150:
            raise ValueError("Age must be between 1 and 150.")

        return age

    @classmethod
    def _validate_gender(cls, gender: str) -> str:
        if not isinstance(gender, str):
            raise TypeError("Gender must be a string.")
        if gender not in cls.VALID_GENDERS:
            raise ValueError('Gender must be "Male", "Female", or "Other".')

        return gender

    def get_info(self) -> dict:
        return {
            "name": self.__name,
            "age": self.__age,
            "gender": self.__gender,
        }


class Employee(Person):
    def __init__(self, name: str, age: int, gender: str, job_title: str):
        super().__init__(name, age, gender)
        self.__job_title = self._validate_job_title(job_title)

    @staticmethod
    def _validate_job_title(job_title: str) -> str:
        if not isinstance(job_title, str):
            raise TypeError("Job title must be a string.")

        job_title = job_title.strip()
        if not job_title:
            raise ValueError("Job title must not be empty.")
        if any(character.isdigit() for character in job_title):
            raise ValueError("Job title must not contain digits.")

        return job_title

    def get_info(self) -> dict:
        information = super().get_info()
        information["job_title"] = self.__job_title
        return information


class TestPersonAndEmployee(unittest.TestCase):
    def test_valid_person(self):
        person = Person("Alice Smith", 30, "Female")
        self.assertEqual(
            person.get_info(),
            {
                "name": "Alice Smith",
                "age": 30,
                "gender": "Female",
            },
        )

    def test_valid_employee(self):
        employee = Employee("Bob Jones", 42, "Male", "Software Engineer")
        self.assertEqual(
            employee.get_info(),
            {
                "name": "Bob Jones",
                "age": 42,
                "gender": "Male",
                "job_title": "Software Engineer",
            },
        )
        self.assertIsInstance(employee, Person)

    def test_surrounding_whitespace_is_removed(self):
        person = Person("  Taylor Lee  ", 25, "Other")
        employee = Employee("Jordan Doe", 35, "Other", "  Project Manager  ")

        self.assertEqual(person.get_info()["name"], "Taylor Lee")
        self.assertEqual(employee.get_info()["job_title"], "Project Manager")

    def test_invalid_names(self):
        invalid_names = ["", "   ", "John123", 100, None]

        for name in invalid_names:
            with self.subTest(name=name):
                with self.assertRaises((TypeError, ValueError)):
                    Person(name, 30, "Male")

    def test_invalid_ages(self):
        invalid_ages = [0, -1, 151, 25.5, "30", True, None]

        for age in invalid_ages:
            with self.subTest(age=age):
                with self.assertRaises((TypeError, ValueError)):
                    Person("Alice", age, "Female")

    def test_invalid_genders(self):
        invalid_genders = ["Unknown", "male", "", None, 1]

        for gender in invalid_genders:
            with self.subTest(gender=gender):
                with self.assertRaises((TypeError, ValueError)):
                    Person("Alice", 30, gender)

    def test_invalid_job_titles(self):
        invalid_titles = ["", "   ", "Engineer2", 123, None]

        for job_title in invalid_titles:
            with self.subTest(job_title=job_title):
                with self.assertRaises((TypeError, ValueError)):
                    Employee("Bob", 40, "Male", job_title)


if __name__ == "__main__":
    unittest.main()
```

