      const row = document.createElement("tr");

      const positionCell = document.createElement("td");
      positionCell.textContent = String(index + 1);

      const characterCell = document.createElement("td");
      characterCell.textContent =
        phrase[index] === " " ? "␠ (space)" : phrase[index];

      const decimalCell = document.createElement("td");
      decimalCell.textContent = String(byte);

      const binaryCell = document.createElement("td");
      binaryCell.textContent = byteToBinary(byte);

      row.append(
        positionCell,
        characterCell,
        decimalCell,
        binaryCell
      );

      tableBody.appendChild(row);
    });
  </script>
</body>
</html>
