```java
import java.util.*;

class Solution {
    /**
     * Returns the n-th Fib4 number using zero-based indexing.
     *
     * @throws IllegalArgumentException if n is negative
     * @throws ArithmeticException if the result cannot be represented as an int
     */
    public int fib4(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        int[] initial = {0, 0, 2, 0};
        if (n < initial.length) {
            return initial[n];
        }

        int a = 0;
        int b = 0;
        int c = 2;
        int d = 0;

        for (int i = 4; i <= n; i++) {
            long next = (long) a + b + c + d;
            if (next > Integer.MAX_VALUE) {
                throw new ArithmeticException("Fib4 value exceeds int range");
            }

            a = b;
            b = c;
            c = d;
            d = (int) next;
        }

        return d;
    }

    /**
     * Returns the first n Fib4 numbers.
     *
     * @throws IllegalArgumentException if n is negative
     * @throws ArithmeticException if an element cannot be represented as an int
     */
    public int[] fib4N(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        int[] result = new int[n];
        int[] initial = {0, 0, 2, 0};

        int initialCount = Math.min(n, initial.length);
        System.arraycopy(initial, 0, result, 0, initialCount);

        for (int i = 4; i < n; i++) {
            long next = (long) result[i - 1]
                      + result[i - 2]
                      + result[i - 3]
                      + result[i - 4];

            if (next > Integer.MAX_VALUE) {
                throw new ArithmeticException("Fib4 value exceeds int range");
            }

            result[i] = (int) next;
        }

        return result;
    }

    /**
     * Returns the zero-based position of the first occurrence of target,
     * or -1 if target is not in the Fib4 sequence.
     */
    public int fib4Find(int target) {
        if (target < 0) {
            return -1;
        }

        int[] initial = {0, 0, 2, 0};
        for (int i = 0; i < initial.length; i++) {
            if (initial[i] == target) {
                return i;
            }
        }

        long a = 0;
        long b = 0;
        long c = 2;
        long d = 0;

        for (int index = 4; ; index++) {
            long next = a + b + c + d;

            if (next == target) {
                return index;
            }

            // From index 4 onward, the sequence is increasing.
            if (next > target) {
                return -1;
            }

            a = b;
            b = c;
            c = d;
            d = next;
        }
    }
}
```

