import java.util.UUID

data class GroceryItem(
    val id: String,
    val name: String
)

/**
 * Stores grocery items in SharedPreferences as JSON so the list survives
 * activity recreation and application restarts.
 */
class GroceryRepository(context: Context) {
    private val preferences = context.getSharedPreferences(
        "grocery_list_preferences",
        Context.MODE_PRIVATE
    )

    fun loadItems(): List<GroceryItem> {
        val json = preferences.getString(KEY_ITEMS, null) ?: return emptyList()

        return try {
            val array = JSONArray(json)

            buildList {
                for (index in 0 until array.length()) {
                    val objectValue = array.getJSONObject(index)

                    add(
                        GroceryItem(
                            id = objectValue.getString("id"),
                            name = objectValue.getString("name")
                        )
                    )
                }
            }
        } catch (_: Exception) {
            emptyList()
        }
    }

    fun saveItems(items: List<GroceryItem>) {
        val array = JSONArray()

        items.forEach { item ->
            array.put(
                JSONObject().apply {
                    put("id", item.id)
                    put("name", item.name)
                }
            )
        }

        preferences.edit()
            .putString(KEY_ITEMS, array.toString())
            .apply()
    }

    private companion object {
        const val KEY_ITEMS = "items"
    }
}

class MainActivity : ComponentActivity() {
    private lateinit var repository: GroceryRepository

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        repository = GroceryRepository(applicationContext)

        setContent {
            GroceryListTheme {
                GroceryListScreen(repository = repository)
            }
        }
    }
}

@Composable
fun GroceryListTheme(content: @Composable () -> Unit) {
    MaterialTheme(
        colorScheme = if (isSystemInDarkTheme()) {
            darkColorScheme()
        } else {
            lightColorScheme()
        },
        content = content
    )
}

@Composable
fun GroceryListScreen(repository: GroceryRepository) {
    val groceryItems = remember {
        mutableStateListOf<GroceryItem>().apply {
            addAll(repository.loadItems())
        }
    }

    var itemName by remember { mutableStateOf("") }
    val focusManager = LocalFocusManager.current

    fun addItem() {
        val trimmedName = itemName.trim()

        if (trimmedName.isEmpty()) {
            return
        }

        groceryItems.add(
            GroceryItem(
                id = UUID.randomUUID().toString(),
                name = trimmedName
            )
        )

        repository.saveItems(groceryItems)
        itemName = ""
        focusManager.clearFocus()
    }

    fun removeItem(item: GroceryItem) {
        groceryItems.remove(item)
        repository.saveItems(groceryItems)
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(WindowInsets.safeDrawing)
            .padding(16.dp)
    ) {
        Text(
            text = "Grocery List",
            style = MaterialTheme.typography.headlineMedium,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.padding(bottom = 16.dp)
        )

        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            OutlinedTextField(
                value = itemName,
                onValueChange = { itemName = it },
                label = { Text("Grocery item") },
                placeholder = { Text("For example, Milk") },
                singleLine = true,
                keyboardOptions = KeyboardOptions(
                    imeAction = ImeAction.Done
                ),
                keyboardActions = KeyboardActions(
                    onDone = { addItem() }
                ),
                modifier = Modifier.weight(1f)
            )

            Button(
                onClick = { addItem() },
                enabled = itemName.isNotBlank()
            ) {
                Text("Add")
            }
        }

        if (groceryItems.isEmpty()) {
            Text(
                text = "Your grocery list is empty.",
                style = MaterialTheme.typography.bodyLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(top = 32.dp)
            )
        } else {
            Text(
                text = "${groceryItems.size} item${if (groceryItems.size == 1) "" else "s"}",
                style = MaterialTheme.typography.labelLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(top = 20.dp, bottom = 8.dp)
            )

            LazyColumn(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                items(
                    items = groceryItems,
                    key = { item -> item.id }
                ) { item ->
                    GroceryItemRow(
                        item = item,
                        onRemove = { removeItem(item) }
                    )
                }
            }
        }
    }
}

@Composable
fun GroceryItemRow(
    item: GroceryItem,
