import "fmt"

// countUpperVowels counts uppercase vowels at even, zero-based indices.
// Converting the string to []rune makes the indices correspond to characters
// rather than individual UTF-8 bytes.
func countUpperVowels(s string) int {
	upperVowels := "AEIOU"
	counter := 0

	for index, letter := range []rune(s) {
		// Skip characters at odd indices.
		if index%2 != 0 {
			continue
		}

		// Check whether the character is an uppercase vowel.
		for _, vowel := range upperVowels {
			if letter == vowel {
				counter++
				break
			}
		}
	}

	return counter
}

func main() {
	fmt.Println(countUpperVowels("aBCdEf")) // 1
	fmt.Println(countUpperVowels("abcdefg")) // 0
	fmt.Println(countUpperVowels("dBBE"))    // 0
}
```

