def special_factors(*args):
    def get_factors(n):
        factors = set()

        for x in range(1, int(n**0.5) + 1):
            if n % x == 0:
                factors.add(x)
                factors.add(n // x)

        return sorted(factors)

    def is_prime(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False

        i = 5
        step = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += step
            step = 6 - step

        return True

    def get_highest_prime_factor(factors):
        return max(
            filter(is_prime, factors),
            default="No prime factors found",
        )

    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    result = {}

    for n in args:
        if not isinstance(n, int) or n <= 0:
            result[n] = "Invalid input - must be a positive integer"
            continue

        factors = get_factors(n)
        is_even = len(factors) % 2 == 0
        sum_of_factors = sum(factors)
        highest_prime_factor = get_highest_prime_factor(factors)

        hcf = factors[0]
        least_cm = factors[-1]

        for factor in factors[1:]:
            hcf = gcd(hcf, factor)
            least_cm = lcm(least_cm, factor)

        result[n] = (
            is_even,
            factors,
            sum_of_factors,
            highest_prime_factor,
            [least_cm, hcf],
        )

    return result
