```java
import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> mergeSort(List<Integer> array) {
        List<Integer> result = new ArrayList<>(array);

        if (result.size() < 2) {
            return result;
        }

        long endpointSum = (long) result.get(0) + result.get(result.size() - 1);
        boolean ascending = (endpointSum & 1L) == 1L;

        List<Integer> auxiliary = new ArrayList<>(result);
        mergeSort(result, auxiliary, 0, result.size(), ascending);

        return result;
    }

    private void mergeSort(List<Integer> array,
                           List<Integer> auxiliary,
                           int start,
                           int end,
                           boolean ascending) {
        if (end - start <= 1) {
            return;
        }

        int middle = start + (end - start) / 2;

        mergeSort(array, auxiliary, start, middle, ascending);
        mergeSort(array, auxiliary, middle, end, ascending);
        merge(array, auxiliary, start, middle, end, ascending);
    }

    private void merge(List<Integer> array,
                       List<Integer> auxiliary,
                       int start,
                       int middle,
                       int end,
                       boolean ascending) {
        for (int i = start; i < end; i++) {
            auxiliary.set(i, array.get(i));
        }

        int left = start;
        int right = middle;

        for (int destination = start; destination < end; destination++) {
            if (left >= middle) {
                array.set(destination, auxiliary.get(right++));
            } else if (right >= end) {
                array.set(destination, auxiliary.get(left++));
            } else {
                int leftValue = auxiliary.get(left);
                int rightValue = auxiliary.get(right);

                boolean takeLeft = ascending
                        ? leftValue <= rightValue
                        : leftValue >= rightValue;

                if (takeLeft) {
                    array.set(destination, leftValue);
                    left++;
                } else {
                    array.set(destination, rightValue);
                    right++;
                }
            }
        }
    }
}
