#include <iostream>
#include <vector>
#include <cstddef>
#include <boost/multiprecision/cpp_int.hpp>

using boost::multiprecision::cpp_int;

// Returns the first n Fibonacci numbers:
// n = 0 -> {}
// n = 1 -> {0}
// n = 2 -> {0, 1}
std::vector<cpp_int> fibonacci(std::size_t n) {
    std::vector<cpp_int> sequence;
    sequence.reserve(n);

    if (n == 0) {
        return sequence;
    }

    sequence.push_back(0);

    if (n == 1) {
        return sequence;
    }

    sequence.push_back(1);

    for (std::size_t i = 2; i < n; ++i) {
        sequence.push_back(sequence[i - 1] + sequence[i - 2]);
    }

    return sequence;
}

int main() {
    std::size_t n;

    std::cout << "Enter the number of Fibonacci terms: ";
    if (!(std::cin >> n)) {
        std::cerr << "Invalid input\n";
        return 1;
    }

    const std::vector<cpp_int> sequence = fibonacci(n);

    for (std::size_t i = 0; i < sequence.size(); ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << sequence[i];
    }
    std::cout << '\n';

    return 0;
}
