ground_truth:
```javascript
/**
 * Performs algebraic operations sequentially from left to right.
 *
 * Supported operators: +, -, *, /, //, **, and %.
 * This does not apply standard operator precedence.
 *
 * @param {string[]} operators
 * @param {number[]} operands
 * @returns {number|string|null}
 */
function performAlgebra(operators, operands) {
    if (!operators.length || !operands.length) {
        return null;
    }

    if (operands.length < operators.length + 1) {
        throw new RangeError("Not enough operands for the provided operators");
    }

    // JavaScript's % is remainder, while Python's % is modulo.
    // This preserves Python's behavior when negative values are used.
    function pythonModulo(a, b) {
        if (b === 0) {
            throw new RangeError("Modulo by zero");
        }

        const remainder = a % b;

        if (remainder === 0) {
            return 0;
        }

        return Math.sign(remainder) === Math.sign(b)
            ? remainder
            : remainder + b;
    }

    let result = operands[0];

    for (let i = 0; i < operators.length; i++) {
        const op = operators[i];
        const num = operands[i + 1];

        switch (op) {
            case "+":
                result += num;
                break;
            case "-":
                result -= num;
                break;
            case "*":
                result *= num;
                break;
            case "/":
                if (num === 0) {
                    throw new RangeError("Division by zero");
                }
                result /= num;
                break;
            case "//":
                if (num === 0) {
                    throw new RangeError("Division by zero");
                }
                // Math.floor matches Python's floor division for negatives.
                result = Math.floor(result / num);
                break;
            case "**":
                if (result === 0 && num < 0) {
                    throw new RangeError("Zero cannot be raised to a negative power");
                }
                result **= num;
                break;
            case "%":
                result = pythonModulo(result, num);
                break;
            default:
                return `Invalid operator found: ${op}`;
        }
    }

    return result;
}
```

Example:

```javascript
console.log(performAlgebra(["+", "*", "//"], [10, 2, 3, 4]));
// Sequential calculation: ((10 + 2) * 3) // 4
// 9
```

This implementation uses JavaScript `number` values. Unlike Python integers, they lose integer precision beyond `Number.MAX_SAFE_INTEGER`.

