HTTP provides only one status code for the whole request, so partial success should be represented in the response body. Do not use the `Warning` header; it is intended for HTTP/cache-related warnings, not application validation errors.

For example, return one result for each customer:

```csharp
public sealed record CustomerSaveResult(
    int Index,
    int? CustomerId,
    bool Saved,
    string? ErrorCode,
    string? ErrorMessage);

public sealed record BulkCustomerSaveResponse(
    int Received,
    int Saved,
    int Failed,
    IReadOnlyList<CustomerSaveResult> Results);
```

```csharp
[HttpPost]
[ProducesResponseType(typeof(BulkCustomerSaveResponse), StatusCodes.Status200OK)]
public ActionResult<BulkCustomerSaveResponse> PostCustomer(
    List<Customer> customers)
{
    var results = new List<CustomerSaveResult>();

    for (var index = 0; index < customers.Count; index++)
    {
        var customer = customers[index];

        try
        {
            SaveCustomer(customer);

            results.Add(new CustomerSaveResult(
                Index: index,
                CustomerId: customer.Id,
                Saved: true,
                ErrorCode: null,
                ErrorMessage: null));
        }
        catch (CustomerValidationException exception)
        {
            results.Add(new CustomerSaveResult(
                Index: index,
                CustomerId: customer.Id,
                Saved: false,
                ErrorCode: "customer_validation_failed",
                ErrorMessage: exception.Message));
        }
    }

    var response = new BulkCustomerSaveResponse(
        Received: results.Count,
        Saved: results.Count(x => x.Saved),
        Failed: results.Count(x => !x.Saved),
        Results: results);

    return Ok(response);
}
