import random
from typing import Optional


class HeptagonDice:
    """Represents a seven-faced die with face values from 1 through 7."""

    NUMBER_OF_FACES = 7

    def __init__(self) -> None:
        self._current_face: Optional[int] = None

    @property
    def current_face(self) -> Optional[int]:
        """Return the current face value, or None if the die has not been rolled."""
        return self._current_face

    def roll(self) -> int:
        """Roll the die, update its current face, and return the result."""
        self._current_face = random.randint(1, self.NUMBER_OF_FACES)
        return self._current_face

    def display_current_face(self) -> None:
        """Display the die's current face value."""
        if self._current_face is None:
            print("The heptagon die has not been rolled yet.")
        else:
            print(f"The current face value is {self._current_face}.")

    def __str__(self) -> str:
        if self._current_face is None:
            return "HeptagonDice(not rolled)"
        return f"HeptagonDice(current_face={self._current_face})"


def main() -> None:
    die = HeptagonDice()

    die.display_current_face()

    result = die.roll()
    print(f"You rolled a {result}.")

    die.display_current_face()


