class CommonElementProcessor:
    def __init__(self, pre_defined_list):
        self.pre_defined_list = pre_defined_list

    @staticmethod
    def _typed_key(value):
        """Keep values of different types distinct, e.g. 1 and '1'."""
        return type(value), value

    @staticmethod
    def _transform(value):
        if isinstance(value, str):
            return value + value          # Concatenate matching strings
        if isinstance(value, int) and not isinstance(value, bool):
            return value * value          # Square matching integers
        raise TypeError(f"Unsupported element type: {type(value).__name__}")

    def process(self, provided_list):
        predefined_elements = {
            self._typed_key(value) for value in self.pre_defined_list
        }

        return [
            self._transform(value)
            for value in provided_list
            if self._typed_key(value) in predefined_elements
        ]


