<script>
    const form = document.getElementById("registration-form");
    const submitButton = document.getElementById("submit-button");
    const statusBox = document.getElementById("form-status");
    const textFields = form.querySelectorAll('input[type="text"]');
    const checkboxes = [...form.querySelectorAll('input[name="interests"]')];

    function showStatus(message, type) {
        statusBox.textContent = message;
        statusBox.className = type;
    }

    function clearStatus() {
        statusBox.textContent = "";
        statusBox.className = "";
    }

    // Prevent text fields from accepting non-alphanumeric characters.
    textFields.forEach((field) => {
        field.addEventListener("input", () => {
            field.value = field.value.replace(/[^A-Za-z0-9]/g, "");
        });
    });

    // HTML has no native "at least one checkbox" constraint, so add one.
    function validateCheckboxes() {
        const atLeastOneChecked = checkboxes.some(
            (checkbox) => checkbox.checked
        );

        checkboxes[0].setCustomValidity(
            atLeastOneChecked
                ? ""
                : "Please choose at least one interest."
        );

        return atLeastOneChecked;
    }

    checkboxes.forEach((checkbox) => {
        checkbox.addEventListener("change", validateCheckboxes);
    });

    form.addEventListener("submit", async (event) => {
        event.preventDefault();
        clearStatus();
        validateCheckboxes();

        // Checks required fields, patterns, select, radio, and checkboxes.
        if (!form.checkValidity()) {
            form.reportValidity();
            showStatus("Please correct the highlighted fields.", "error");
            return;
        }

        submitButton.disabled = true;
        showStatus("Submitting the form...", "pending");

        try {
            const response = await fetch(form.action, {
                method: form.method.toUpperCase(),
                body: new FormData(form),
                headers: {
                    "Accept": "application/json"
                }
            });

            if (!response.ok) {
                throw new Error(`Server returned status ${response.status}.`);
            }

            showStatus(
                "Submission successful. Your form was sent without refreshing the page.",
                "success"
            );
        } catch (error) {
            console.error(error);
            showStatus(
                "The form could not be submitted. Please try again.",
                "error"
            );
        } finally {
            submitButton.disabled = false;
        }
    });

    form.addEventListener("reset", () => {
        // The native reset clears text, select, radio, and checkbox values.
        clearStatus();
        checkboxes[0].setCustomValidity("");
        submitButton.disabled = false;
    });
</script>
