```cpp
#include <cstddef>
#include <iostream>
#include <memory>

class BinaryTree {
public:
    struct Node {
        int value;
        std::unique_ptr<Node> left;
        std::unique_ptr<Node> right;

        explicit Node(int value) : value(value) {}
    };

    std::unique_ptr<Node> root;

    // Increments every value less than 10 and returns the number changed.
    static std::size_t incrementValuesBelowTen(Node* node) {
        if (node == nullptr) {
            return 0;
        }

        std::size_t count = 0;

        if (node->value < 10) {
            ++node->value;
            ++count;
        }

        count += incrementValuesBelowTen(node->left.get());
        count += incrementValuesBelowTen(node->right.get());

        return count;
    }

    std::size_t incrementValuesBelowTen() {
        return incrementValuesBelowTen(root.get());
    }
};

int main() {
    BinaryTree tree;

    tree.root = std::make_unique<BinaryTree::Node>(8);
    tree.root->left = std::make_unique<BinaryTree::Node>(4);
    tree.root->right = std::make_unique<BinaryTree::Node>(12);
    tree.root->left->left = std::make_unique<BinaryTree::Node>(10);
    tree.root->left->right = std::make_unique<BinaryTree::Node>(7);

    const std::size_t incremented = tree.incrementValuesBelowTen();

    std::cout << "Nodes incremented: " << incremented << '\n'; // 3
}
```

Each node is visited exactly once, so the time complexity is \(O(n)\). The recursive call stack uses \(O(h)\) space, where \(h\) is the tree height; this is \(O(\log n)\) for a balanced tree and \(O(n)\) for a fully skewed tree. No global or static count is used.

Final answer: The recursive traversal runs in O(n) time, uses O(h) call-stack space, and returns the increment count through its recursive return values.

