```swift
func median(_ values: [Double]) -> Double? {
    guard !values.isEmpty else {
        return nil
    }

    // Zero-based ranks of the two middle elements.
    let lowerRank = (values.count - 1) / 2
    let upperRank = values.count / 2

    var lowerMedian: Double?
    var upperMedian: Double?

    for candidate in values {
        var less = 0
        var equal = 0

        for value in values {
            if value < candidate {
                less += 1
            } else if value == candidate {
                equal += 1
            }
        }

        // This candidate occupies the ranks less...(less + equal - 1).
        if less <= lowerRank && lowerRank < less + equal {
            lowerMedian = candidate
        }

        if less <= upperRank && upperRank < less + equal {
            upperMedian = candidate
        }

        if let lower = lowerMedian, let upper = upperMedian {
            return (lower + upper) / 2.0
        }
    }

    return nil
}
```

