```javascript
const factorize = (n) => {
  if (!Number.isSafeInteger(n) || n < 1) {
    throw new RangeError("n must be a positive safe integer");
  }

  const original = n;
  const factors = [];

  // Extract all factors of 2.
  while (n % 2 === 0) {
    factors.push(2);
    n /= 2;
  }

  // Test only odd possible factors.
  for (let divisor = 3; divisor <= n / divisor; divisor += 2) {
    while (n % divisor === 0) {
      factors.push(divisor);
      n /= divisor;
    }
  }

  // Any remaining value greater than 1 is prime.
  if (n > 1) {
    factors.push(n);
  }

  if (factors.reduce((product, factor) => product * factor, 1) !== original) {
    throw new Error("Factorization validation failed");
  }

  return factors;
};
