The program reads one pair per nonempty input line and continues until end-of-file. Each pair must contain exactly two positive integers. Invalid, negative, zero, or non-integer inputs are reported without terminating the program. `BigInteger` avoids overflow for large values.

```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.math.BigInteger;

public class Main {

    // Euclidean algorithm for greatest common divisor
    private static BigInteger gcd(BigInteger a, BigInteger b) {
        while (!b.equals(BigInteger.ZERO)) {
            BigInteger remainder = a.mod(b);
            a = b;
            b = remainder;
        }
        return a;
    }

    private static BigInteger lcm(BigInteger a, BigInteger b) {
        // Divide before multiplying to keep intermediate values smaller.
        return a.divide(gcd(a, b)).multiply(b);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader =
                new BufferedReader(new InputStreamReader(System.in));

        String line;
        int lineNumber = 0;

        // Read until EOF. Each nonempty line represents one pair.
        while ((line = reader.readLine()) != null) {
            lineNumber++;
            line = line.trim();

            if (line.isEmpty()) {
                continue;
            }

            String[] values = line.split("\\s+");

            if (values.length != 2) {
                System.out.println(
                        "Invalid input on line " + lineNumber
                        + ": enter exactly two integers.");
                continue;
            }

            try {
                BigInteger first = new BigInteger(values[0]);
                BigInteger second = new BigInteger(values[1]);

                if (first.signum() <= 0 || second.signum() <= 0) {
                    System.out.println(
                            "Invalid input on line " + lineNumber
                            + ": both integers must be greater than zero.");
                    continue;
                }

                System.out.println(
                        "LCM(" + first + ", " + second + ") = "
                        + lcm(first, second));

            } catch (NumberFormatException e) {
                System.out.println(
                        "Invalid input on line " + lineNumber
                        + ": both values must be integers.");
            }
        }
    }
}
```

