```

### 2. Create the Rust project

```bash
cargo new spacy_rust_example
cd spacy_rust_example
```

Use this `Cargo.toml`:

```toml
[package]
name = "spacy_rust_example"
version = "0.1.0"
edition = "2021"

[dependencies]
# auto-initialize starts the embedded Python interpreter for us.
pyo3 = { version = "0.22", features = ["auto-initialize"] }
```

### 3. Rust translation

Place this in `src/main.rs`:

```rust
use pyo3::prelude::*;
use pyo3::types::PyModule;

fn main() -> PyResult<()> {
    // Python::with_gil gives this thread permission to interact with
    // the embedded Python interpreter.
    Python::with_gil(|py| {
        // Equivalent to:
        // import spacy
        let spacy = PyModule::import_bound(py, "spacy")?;

        // Equivalent to:
        // import pandas as pd
        //
        // The leading underscore tells Rust that it is intentionally
        // unused for now, just as the original snippet only imports pandas.
        let _pd = PyModule::import_bound(py, "pandas")?;

        // Equivalent to:
        // from spacy.util import minibatch, compounding
        let spacy_util = PyModule::import_bound(py, "spacy.util")?;
        let _minibatch = spacy_util.getattr("minibatch")?;
