```javascript
// geometricMean.js
"use strict";

function geometricMean(values) {
    if (!Array.isArray(values) || values.length !== 4) {
        throw new Error("Exactly four numbers are required.");
    }

    for (const value of values) {
        if (!Number.isSafeInteger(value) || value <= 0) {
            throw new Error(
                `"${value}" is invalid. All values must be positive, non-zero integers.`
            );
        }
    }

    // Using logarithms avoids creating a potentially very large product.
    return Math.exp(values.reduce((sum, value) => sum + Math.log(value), 0) / 4);
}

try {
    // Accept values as command-line arguments, e.g.:
    // node geometricMean.js 7 2 4 12
    const input = process.argv.slice(2);

    if (input.length !== 4) {
        throw new Error("Usage: node geometricMean.js <n1> <n2> <n3> <n4>");
    }

    const values = input.map((text) => {
        if (!/^\+?\d+$/.test(text)) {
            throw new Error(`"${text}" is not a positive integer.`);
        }

        const value = Number(text);

        if (!Number.isSafeInteger(value) || value <= 0) {
            throw new Error(`"${text}" is outside the valid positive-integer range.`);
        }

        return value;
    });

    console.log(`Geometric mean: ${geometricMean(values)}`);
} catch (error) {
    console.error(`Error: ${error.message}`);
    process.exitCode = 1;
}
