The following Python CLI uses an object-oriented handler for CSV, JSON, and XML datasets.

```python
#!/usr/bin/env python3

import argparse
import csv
import json
import math
import os
import tempfile
import xml.etree.ElementTree as ET

from abc import ABC, abstractmethod
from pathlib import Path
from typing import Any


Record = dict[str, Any]


class DatasetHandler(ABC):
    @abstractmethod
    def load(self, path: Path) -> list[Record]:
        """Load records from path."""

    @abstractmethod
    def save(self, path: Path, records: list[Record]) -> None:
        """Save records to path."""


class CSVHandler(DatasetHandler):
    def __init__(self) -> None:
        self.delimiter = ","
        self.fieldnames: list[str] = []

    def load(self, path: Path) -> list[Record]:
        with path.open("r", encoding="utf-8-sig", newline="") as file:
            sample = file.read(4096)
            file.seek(0)

            try:
                dialect = csv.Sniffer().sniff(sample, delimiters=",;|\t")
                self.delimiter = dialect.delimiter
            except csv.Error:
                self.delimiter = ","

            reader = csv.DictReader(
                file,
                delimiter=self.delimiter,
                skipinitialspace=True,
            )

            if reader.fieldnames is None:
                return []

            self.fieldnames = [name.strip() for name in reader.fieldnames]

            records: list[Record] = []
            for raw_row in reader:
                row = {
                    str(key).strip(): value.strip() if isinstance(value, str) else value
                    for key, value in raw_row.items()
                    if key is not None
                }
                records.append(row)

            return records

    def save(self, path: Path, records: list[Record]) -> None:
        fieldnames = self.fieldnames
        if not fieldnames and records:
            fieldnames = list(records[0].keys())

        with path.open("w", encoding="utf-8", newline="") as file:
            writer = csv.DictWriter(
                file,
                fieldnames=fieldnames,
                delimiter=self.delimiter,
                extrasaction="ignore",
            )
            writer.writeheader()
            writer.writerows(records)


class JSONHandler(DatasetHandler):
    def __init__(self) -> None:
        self.document: Any = None
        self.records_key: str | None = None

    def load(self, path: Path) -> list[Record]:
        with path.open("r", encoding="utf-8") as file:
            self.document = json.load(file)

        if isinstance(self.document, list):
            records = self.document
        elif isinstance(self.document, dict):
            # Supports documents such as {"records": [...]}
            for candidate in ("records", "data", "items"):
                if isinstance(self.document.get(candidate), list):
                    self.records_key = candidate
                    records = self.document[candidate]
                    break
            else:
                raise ValueError(
                    "JSON must be an array or contain a 'records', 'data', "
                    "or 'items' array."
                )
        else:
            raise ValueError("Unsupported JSON structure.")

        if not all(isinstance(record, dict) for record in records):
            raise ValueError("Every JSON record must be an object.")

        return records

    def save(self, path: Path, records: list[Record]) -> None:
        if self.records_key is None:
            output: Any = records
        else:
            output = dict(self.document)
            output[self.records_key] = records

        with path.open("w", encoding="utf-8") as file:
            json.dump(output, file, indent=2, ensure_ascii=False)
            file.write("\n")


class XMLHandler(DatasetHandler):
    def __init__(self) -> None:
        self.root_tag = "records"
        self.root_attributes: dict[str, str] = {}
        self.record_tag = "record"

    def load(self, path: Path) -> list[Record]:
        tree = ET.parse(path)
        root = tree.getroot()

        self.root_tag = root.tag
        self.root_attributes = dict(root.attrib)

        elements = list(root)
        if not elements:
            return []

        self.record_tag = elements[0].tag
        records: list[Record] = []

        for element in elements:
            row: Record = dict(element.attrib)

            for child in element:
                row[child.tag] = child.text.strip() if child.text else ""

            records.append(row)

        return records

    def save(self, path: Path, records: list[Record]) -> None:
        root = ET.Element(self.root_tag, self.root_attributes)

        for record in records:
            record_element = ET.SubElement(root, self.record_tag)

            for key, value in record.items():
                field = ET.SubElement(record_element, str(key))
                field.text = "" if value is None else str(value)

        tree = ET.ElementTree(root)
        ET.indent(tree, space="  ")
        tree.write(path, encoding="utf-8", xml_declaration=True)


class HandlerFactory:
    HANDLERS = {
        ".csv": CSVHandler,
        ".json": JSONHandler,
        ".xml": XMLHandler,
    }

    @classmethod
    def create(cls, path: Path) -> DatasetHandler:
        extension = path.suffix.lower()

        try:
            return cls.HANDLERS[extension]()
        except KeyError as exc:
            supported = ", ".join(sorted(cls.HANDLERS))
            raise ValueError(
                f"Unsupported format {extension!r}; supported formats: {supported}"
            ) from exc


def get_field(record: Record, requested_name: str) -> Any:
    """Look up a field without making capitalization significant."""
    requested = requested_name.casefold()

    for key, value in record.items():
        if key.casefold() == requested:
            return value

    raise ValueError(f"Record is missing required field {requested_name!r}: {record}")


def is_prime(value: int) -> bool:
    if value < 2:
        return False
    if value == 2:
        return True
    if value % 2 == 0:
        return False

    limit = math.isqrt(value)
    for divisor in range(3, limit + 1, 2):
        if value % divisor == 0:
            return False

    return True


class DatasetFilter:
    def __init__(self, allowed_countries: set[str]) -> None:
        self.allowed_countries = {
            country.strip().casefold() for country in allowed_countries
        }

    def should_delete(self, record: Record) -> bool:
        location = str(get_field(record, "Location")).strip().casefold()

        raw_id = get_field(record, "ID")
        try:
            identifier = int(raw_id)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"ID must be an integer, but received {raw_id!r}") from exc

        location_is_disallowed = location not in self.allowed_countries
        id_is_prime = is_prime(identifier)

        return location_is_disallowed or id_is_prime

    def apply(self, records: list[Record]) -> tuple[list[Record], int]:
        retained = [
            record for record in records
            if not self.should_delete(record)
        ]
        return retained, len(records) - len(retained)


def save_in_place(
    handler: DatasetHandler,
    input_path: Path,
    records: list[Record],
) -> None:
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{input_path.name}.",
        suffix=".tmp",
        dir=input_path.parent,
    )
    os.close(descriptor)
    temporary_path = Path(temporary_name)

    try:
        handler.save(temporary_path, records)
        os.replace(temporary_path, input_path)
    except Exception:
        temporary_path.unlink(missing_ok=True)
        raise


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Delete records whose location is not allowed or whose ID is prime."
        )
    )
    parser.add_argument("input", type=Path, help="Input CSV, JSON, or XML file")
    parser.add_argument(
        "--allowed",
        nargs="+",
        required=True,
        metavar="COUNTRY",
        help="Allowed countries",
    )

    destination = parser.add_mutually_exclusive_group(required=True)
    destination.add_argument(
        "--output",
        type=Path,
        help="Write filtered data to this file",
    )
    destination.add_argument(
        "--in-place",
        action="store_true",
        help="Atomically replace the input file",
    )

    return parser.parse_args()


def main() -> None:
    args = parse_arguments()

    if not args.input.is_file():
        raise SystemExit(f"Input file does not exist: {args.input}")

    if args.output and args.output.resolve() == args.input.resolve():
        raise SystemExit(
            "Use --in-place when the output and input paths are the same."
        )

    handler = HandlerFactory.create(args.input)
    records = handler.load(args.input)

    dataset_filter = DatasetFilter(set(args.allowed))
    retained, deleted_count = dataset_filter.apply(records)

    if args.in_place:
        save_in_place(handler, args.input, retained)
        destination = args.input
    else:
        handler.save(args.output, retained)
        destination = args.output

    print(
        f"Deleted {deleted_count} record(s); retained {len(retained)}. "
        f"Result: {destination}"
    )


if __name__ == "__main__":
    main()
```

