The following program reads users from a four-column CSV file, validates each record, continues after invalid records, stores valid users by email, and removes a requested user.

```java
import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.regex.Pattern;

/*
 * Expected CSV format:
 *
 * name,age,email,address
 *
 * Example data (without a header):
 * Alice Smith,25,alice@example.com,New York
 * Bob Jones,17,bob@example.com,Chicago
 * Mary Brown,31,mary@example.com,Boston
 */
public class UserManagementDemo {

    private static final Pattern NAME_PATTERN =
            Pattern.compile("^[\\p{L}][\\p{L} .'-]*$");

    private static final Pattern EMAIL_PATTERN =
            Pattern.compile(
                    "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"
            );

    private final Map<String, User> users = new HashMap<>();

    /**
     * Reads the CSV file and adds all valid users to the map.
     *
     * A malformed record is reported and skipped. File-level I/O errors are
     * propagated to the caller.
     */
    public void loadUsers(String fileName)
            throws FileNotFoundException, IOException {

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(
                        new FileInputStream(fileName),
                        StandardCharsets.UTF_8))) {

            String line;
            int lineNumber = 0;

            while ((line = reader.readLine()) != null) {
                lineNumber++;

                // Ignore blank lines.
                if (line.trim().isEmpty()) {
                    continue;
                }

                try {
                    User user = parseUser(line, lineNumber);

                    User previous = users.put(user.getEmail(), user);
                    if (previous == null) {
                        System.out.println("Added user: " + user);
                    } else {
                        System.out.println(
                                "Replaced existing user with email "
                                        + user.getEmail());
                    }
                } catch (InvalidNameException e) {
                    logValidationError(lineNumber, "Invalid name", e);
                } catch (InvalidAgeException e) {
                    logValidationError(lineNumber, "Invalid age", e);
                } catch (InvalidEmailException e) {
                    logValidationError(lineNumber, "Invalid email", e);
                } catch (InvalidAddressException e) {
                    logValidationError(lineNumber, "Invalid address", e);
                } catch (IOException e) {
                    // A record with missing or extra columns is malformed.
                    System.err.println(
                            "CSV format error on line " + lineNumber
                                    + ": " + e.getMessage());
                }
            }
        }
    }

    /**
     * Parses and validates one CSV row.
     *
     * This example expects exactly four comma-separated columns. It does not
     * implement quoted CSV fields, so commas cannot occur inside a field.
     */
    private User parseUser(String line, int lineNumber)
            throws IOException,
            InvalidNameException,
            InvalidAgeException,
            InvalidEmailException,
            InvalidAddressException {

        // A negative limit preserves empty trailing columns.
        String[] columns = line.split(",", -1);

        if (columns.length != 4) {
            throw new IOException(
                    "Expected 4 columns but found " + columns.length
                            + " on line " + lineNumber);
        }

        String name = columns[0].trim();
        String ageText = columns[1].trim();
        String email = columns[2].trim();
        String address = columns[3].trim();

        validateName(name);
        int age = validateAge(ageText);
        validateEmail(email);
        validateAddress(address);

        return new User(name, age, email, address);
    }

    private void validateName(String name) throws InvalidNameException {
        if (name.isEmpty()) {
            throw new InvalidNameException("Name must not be empty.");
        }

        if (!NAME_PATTERN.matcher(name).matches()) {
            throw new InvalidNameException(
                    "Name contains invalid characters: " + name);
        }
    }

    private int validateAge(String ageText) throws InvalidAgeException {
        final int age;

        try {
            age = Integer.parseInt(ageText);
        } catch (NumberFormatException e) {
            throw new InvalidAgeException(
                    "Age must be an integer: " + ageText, e);
        }

        if (age < 18 || age > 99) {
            throw new InvalidAgeException(
                    "Age must be between 18 and 99: " + age);
        }

        return age;
    }

    private void validateEmail(String email) throws InvalidEmailException {
        if (email.isEmpty() || !EMAIL_PATTERN.matcher(email).matches()) {
            throw new InvalidEmailException(
                    "Email has an invalid format: " + email);
        }
    }

    private void validateAddress(String address)
            throws InvalidAddressException {

        if (address.isEmpty()) {
            throw new InvalidAddressException(
                    "Address must not be empty.");
        }
    }

    /**
     * Removes a user by email.
     *
     * @throws NoSuchElementException if the email is not in the map
     */
    public User removeUser(String email) throws NoSuchElementException {
        User removed = users.remove(email);

        if (removed == null) {
            throw new NoSuchElementException(
                    "No user exists with email: " + email);
        }

        return removed;
    }

    public Map<String, User> getUsers() {
        return new HashMap<>(users);
    }

    private static void logValidationError(
            int lineNumber, String type, Exception exception) {

        System.err.println(
                type + " on line " + lineNumber
                        + ": " + exception.getMessage());
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println(
                    "Usage: java UserManagementDemo "
                            + "<csv-file> <email-to-remove>");
            return;
        }

        String csvFile = args[0];
        String emailToRemove = args[1];

        UserManagementDemo system = new UserManagementDemo();

        try {
            system.loadUsers(csvFile);
        } catch (FileNotFoundException e) {
            System.err.println(
                    "Input file was not found: " + csvFile);
            return;
        } catch (IOException e) {
            System.err.println(
                    "An I/O error occurred while reading "
                            + csvFile + ": " + e.getMessage());
            return;
        }

        System.out.println("\nValid users currently in the database:");
        for (User user : system.getUsers().values()) {
            System.out.println(user);
        }

        try {
            User removed = system.removeUser(emailToRemove);
            System.out.println("\nRemoved user: " + removed);
        } catch (NoSuchElementException e) {
            System.err.println("\nUnable to remove user: " + e.getMessage());
        }
    }
}

class User {
    private final String name;
    private final int age;
    private final String email;
    private final String address;

    public User(String name, int age, String email, String address) {
        this.name = name;
        this.age = age;
        this.email = email;
        this.address = address;
    }

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public String getEmail() {
        return email;
    }

    public String getAddress() {
        return address;
    }

    @Override
    public String toString() {
        return "User{name='" + name
                + "', age=" + age
                + ", email='" + email
                + "', address='" + address + "'}";
    }
}

class InvalidNameException extends Exception {
    private static final long serialVersionUID = 1L;

    public InvalidNameException(String message) {
        super(message);
    }
}

class InvalidAgeException extends Exception {
    private static final long serialVersionUID = 1L;

    public InvalidAgeException(String message) {
        super(message);
    }

    public InvalidAgeException(String message, Throwable cause) {
        super(message, cause);
    }
}

class InvalidEmailException extends Exception {
    private static final long serialVersionUID = 1L;

    public InvalidEmailException(String message) {
        super(message);
    }
}

class InvalidAddressException extends Exception {
    private static final long serialVersionUID = 1L;

    public InvalidAddressException(String message) {
        super(message);
    }
}
