public class Solution {

    public ArrayList<Double> findClosestElements(List<Double> values) {
        double closestDistance = Math.abs(values.get(0) - values.get(1));
        double first = values.get(0);
        double second = values.get(1);

        for (int i = 0; i < values.size() - 1; i++) {
