The stop-word is `STOP` (case-insensitive). Word frequencies are accumulated across all entered sentences.

```python
import unicodedata


def remove_punctuation(text):
    """Replace punctuation with spaces so adjacent words do not merge."""
    cleaned_characters = []

    for character in text:
        if unicodedata.category(character).startswith("P"):
            cleaned_characters.append(" ")
        else:
            cleaned_characters.append(character)

    return "".join(cleaned_characters)


def reverse_word_order(words):
    """Reverse a list's order without reverse() or [::-1]."""
    reversed_words = []
    index = len(words) - 1

    while index >= 0:
        reversed_words.append(words[index])
        index -= 1

    return reversed_words


word_frequencies = {}
reversed_sentences = []

print("Enter sentences one at a time.")
print("Enter STOP to finish.\n")

while True:
    sentence = input("> ")

    if sentence.strip().casefold() == "stop":
        break

    cleaned_sentence = remove_punctuation(sentence)
    words = cleaned_sentence.split()
    reversed_words = reverse_word_order(words)

    reversed_sentence = " ".join(reversed_words)
    reversed_sentences.append(reversed_sentence)

    # casefold() provides case-insensitive counting
    for word in reversed_words:
        normalized_word = word.casefold()
        word_frequencies[normalized_word] = (
            word_frequencies.get(normalized_word, 0) + 1
        )

