function primeDivisors(n) {
  if (!Number.isSafeInteger(n) || n < 1) {
    throw new RangeError("n must be a positive whole number");
  }

  const divisors = [];

  for (let divisor = 2; divisor * divisor <= n; divisor++) {
    if (n % divisor === 0) {
      divisors.push(divisor);

      // Remove every occurrence so each prime divisor appears once.
      while (n % divisor === 0) {
        n /= divisor;
      }
    }
  }

  // Any remaining value greater than 1 is prime.
  if (n > 1) {
