```cpp
#include <algorithm>
#include <cmath>
#include <tuple>
#include <utility>
#include <vector>

using Car = std::pair<double, double>;
// Each collision contains:
// (collision time, left car index, right car index)
using Collision = std::tuple<double, int, int>;

std::vector<Collision> carRaceCollision(
    int n,
    const std::vector<Car>& leftCars,
    const std::vector<Car>& rightCars)
{
    std::vector<Collision> collisions;

    // Compare every left-side car with every right-side car.
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            // The second value in each pair represents the time at which
            // that car reaches the epicenter.
            const double leftTime = leftCars[i].second;
            const double rightTime = rightCars[j].second;

            // The cars collide if they reach the epicenter at nearly
            // the same time. An epsilon is used for floating-point values.
            if (std::abs(leftTime - rightTime) < 1e-6) {
                collisions.emplace_back(leftTime, i, j);
            }
        }
    }

    // Sort collisions by collision time. stable_sort preserves the original
    // order of collision records that have equal times, like Python's sorted.
    std::stable_sort(
        collisions.begin(),
        collisions.end(),
        [](const Collision& a, const Collision& b) {
            return std::get<0>(a) < std::get<0>(b);
        }
    );

    return collisions;
}
```

Final answer: The C++ function above is a direct translation and returns collision records as `(time, left-car index, right-car index)`.

