```javascript
function findPalindromeSubstrings(string) {
    // Convert the string into an array of characters.
    // Array.from correctly handles Unicode characters such as emojis.
    const characters = Array.from(string);

    // A Set stores only unique substrings, automatically removing duplicates.
    const substringsSet = new Set();

    // Generate every possible non-empty substring.
    for (let start = 0; start < characters.length; start++) {
        for (let end = start + 1; end <= characters.length; end++) {
            const substring = characters.slice(start, end).join("");
            substringsSet.add(substring);
        }
    }

    // Store the unique substrings that are palindromes.
    const palindromeSubstrings = [];

    for (const substring of substringsSet) {
        // Reverse the substring and compare it with the original.
        const reversedSubstring = Array.from(substring).reverse().join("");

        if (substring === reversedSubstring) {
            palindromeSubstrings.push(substring);
        }
    }

    // Return both the palindrome substrings and their total count.
    return [palindromeSubstrings, palindromeSubstrings.length];
}

// Example:
