```python
"""Views for user registration, authentication, and profile management."""

import json
from typing import Any, Dict, List, Optional

from django.contrib.auth.hashers import check_password, make_password
from django.core.exceptions import ValidationError
from django.db import IntegrityError, transaction
from django.http import HttpRequest, JsonResponse
from django.views.decorators.http import require_GET, require_POST

from .models import User


def _request_data(request: HttpRequest) -> Dict[str, Any]:
    """Return request data from either JSON or form-encoded input."""
    content_type: str = request.content_type or ""

    if content_type == "application/json":
        if not request.body:
            return {}

        try:
            payload: Any = json.loads(request.body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("The request body must contain valid JSON.") from exc

        if not isinstance(payload, dict):
            raise ValueError("The JSON request body must be an object.")

        return payload

    return request.POST.dict()


def _normalize_interests(value: Any) -> List[str]:
    """Convert an interests value to a normalized list of unique strings."""
    raw_interests: List[Any]

    if value is None:
        return []
    if isinstance(value, str):
        raw_interests = value.split(",")
    elif isinstance(value, (list, tuple)):
        raw_interests = list(value)
    else:
        raise ValueError("Interests must be a list or comma-separated string.")

    interests: List[str] = []
    seen_interests: set[str] = set()

    for raw_interest in raw_interests:
        if not isinstance(raw_interest, str):
            raise ValueError("Every interest must be a string.")

        interest: str = raw_interest.strip()
        normalized_interest: str = interest.casefold()

        if interest and normalized_interest not in seen_interests:
            interests.append(interest)
            seen_interests.add(normalized_interest)

    return interests


def _serialize_user(user: User) -> Dict[str, Any]:
    """Return a safe JSON representation of a user."""
    interests: Any = user.interests

    if interests is None:
        serialized_interests: List[str] = []
    elif isinstance(interests, list):
        serialized_interests = interests
    else:
        serialized_interests = _normalize_interests(interests)

    return {
        "id": user.pk,
        "username": user.username,
        "email": user.email,
        "interests": serialized_interests,
    }


def _validation_error_response(exc: ValidationError) -> JsonResponse:
    """Convert a Django validation error into a JSON response."""
    if hasattr(exc, "message_dict"):
        errors: Any = exc.message_dict
    else:
        errors = exc.messages

    return JsonResponse({"errors": errors}, status=400)


def _authenticated_user(request: HttpRequest) -> Optional[User]:
    """Return the custom user associated with the current session."""
    user_id: Optional[Any] = request.session.get("user_id")
    if user_id is None:
        return None

    try:
        return User.objects.get(pk=user_id)
    except (User.DoesNotExist, ValueError, TypeError):
        request.session.pop("user_id", None)
        return None


@require_POST
def register_user(request: HttpRequest) -> JsonResponse:
    """Create a user account and establish an authenticated session."""
    try:
        data: Dict[str, Any] = _request_data(request)
        username: str = str(data.get("username", "")).strip()
        email: str = str(data.get("email", "")).strip()
        password: str = str(data.get("password", ""))
        interests: List[str] = _normalize_interests(data.get("interests", []))
    except ValueError as exc:
        return JsonResponse({"error": str(exc)}, status=400)

    missing_fields: List[str] = [
        field_name
        for field_name, value in (
            ("username", username),
            ("email", email),
            ("password", password),
        )
        if not value
    ]
    if missing_fields:
        return JsonResponse(
            {
                "error": "Required fields are missing.",
                "fields": missing_fields,
            },
            status=400,
        )

    user: User = User(
        username=username,
        email=email,
        password=make_password(password),
        interests=interests,
    )

    try:
        with transaction.atomic():
            user.full_clean()
            user.save()
    except ValidationError as exc:
        return _validation_error_response(exc)
    except IntegrityError:
        return JsonResponse(
            {"error": "A user with that username or email already exists."},
            status=409,
        )

    request.session.cycle_key()
    request.session["user_id"] = str(user.pk)

    return JsonResponse({"user": _serialize_user(user)}, status=201)


@require_POST
def login_user(request: HttpRequest) -> JsonResponse:
    """Authenticate a user using a username and password."""
    try:
        data: Dict[str, Any] = _request_data(request)
    except ValueError as exc:
        return JsonResponse({"error": str(exc)}, status=400)

    username: str = str(data.get("username", "")).strip()
    password: str = str(data.get("password", ""))

    if not username or not password:
        return JsonResponse(
            {"error": "Username and password are required."},
            status=400,
        )

    user: Optional[User] = User.objects.filter(username=username).first()
    if user is None or not check_password(password, user.password):
        return JsonResponse(
            {"error": "Invalid username or password."},
            status=401,
        )

    request.session.cycle_key()
    request.session["user_id"] = str(user.pk)

    return JsonResponse({"user": _serialize_user(user)}, status=200)


@require_POST
def logout_user(request: HttpRequest) -> JsonResponse:
    """End the current user's authenticated session."""
    request.session.flush()
    return JsonResponse({"message": "Successfully logged out."}, status=200)


@require_GET
def user_profile(
    request: HttpRequest,
    user_id: Optional[int] = None,
) -> JsonResponse:
    """Return a public user profile or the current user's profile."""
    user: Optional[User]

    if user_id is None:
        user = _authenticated_user(request)
        if user is None:
            return JsonResponse(
                {"error": "Authentication is required."},
                status=401,
            )
    else:
        try:
            user = User.objects.get(pk=user_id)
        except User.DoesNotExist:
            return JsonResponse({"error": "User not found."}, status=404)

    return JsonResponse({"user": _serialize_user(user)}, status=200)


@require_POST
def update_interests(request: HttpRequest) -> JsonResponse:
    """Replace the authenticated user's interests."""
    user: Optional[User] = _authenticated_user(request)
    if user is None:
        return JsonResponse(
            {"error": "Authentication is required."},
            status=401,
        )

    try:
        data: Dict[str, Any] = _request_data(request)
        interests: List[str] = _normalize_interests(data.get("interests", []))
    except ValueError as exc:
        return JsonResponse({"error": str(exc)}, status=400)

    user.interests = interests

    try:
        with transaction.atomic():
            user.full_clean()
            user.save(update_fields=["interests"])
    except ValidationError as exc:
        return _validation_error_response(exc)
    except IntegrityError:
        return JsonResponse(
            {"error": "The interests could not be updated."},
            status=409,
