```javascript
/**
 * Colors every h1-h6 heading green, unless its text contains one of the
 * specified keywords, in which case it is colored red.
 *
 * @param {string[]} keywords Keywords that mark a heading as special.
 * @param {Document|Element} root Document or element to search within.
 */
function colorHeadings(
  keywords = ["Warning:"],
  root = globalThis.document
) {
  if (!root) {
    throw new Error("A document or root element is required.");
  }

  const headings = root.querySelectorAll("h1, h2, h3, h4, h5, h6");

  headings.forEach((heading) => {
    const containsKeyword = keywords.some((keyword) =>
      heading.textContent.includes(keyword)
    );

    heading.style.color = containsKeyword ? "red" : "green";
  });
}

// Allows the function to be imported by Jest or Node.js.
if (typeof module !== "undefined" && module.exports) {
  module.exports = colorHeadings;
}
```

It can be called in the browser after the document has loaded:

```javascript
document.addEventListener("DOMContentLoaded", () => {
  colorHeadings(["Warning:"]);
});
```

