```python
import random


class Node:
    def __init__(self, height: int = 0, val: int | None = None):
        self.val = val
        self.next: list[Node | None] = [None] * height


class Skiplist:
    MAX_HEIGHT = 16

    def __init__(self):
        self.head = Node(self.MAX_HEIGHT)

    def _iter(self, num: int) -> Node:
        """Return the node immediately preceding num at level 0."""
        curr = self.head

        for level in reversed(range(self.MAX_HEIGHT)):
            while (
                curr.next[level] is not None
                and curr.next[level].val < num
            ):
                curr = curr.next[level]

        return curr

    def _random_height(self) -> int:
        height = 1

        while height < self.MAX_HEIGHT and random.random() < 0.5:
            height += 1

        return height

    def search(self, target: int) -> bool:
        node = self._iter(target)
        next_node = node.next[0]

        return next_node is not None and next_node.val == target

    def add(self, num: int) -> None:
        update = [self.head] * self.MAX_HEIGHT
        curr = self.head

        for level in reversed(range(self.MAX_HEIGHT)):
            while (
                curr.next[level] is not None
                and curr.next[level].val < num
            ):
                curr = curr.next[level]

            update[level] = curr

        height = self._random_height()
        new_node = Node(height, num)

        for level in range(height):
            new_node.next[level] = update[level].next[level]
            update[level].next[level] = new_node

    def erase(self, num: int) -> bool:
        update = [self.head] * self.MAX_HEIGHT
        curr = self.head

        for level in reversed(range(self.MAX_HEIGHT)):
            while (
                curr.next[level] is not None
                and curr.next[level].val < num
            ):
                curr = curr.next[level]

            update[level] = curr

        node = update[0].next[0]

        if node is None or node.val != num:
            return False

        for level in range(len(node.next)):
            if update[level].next[level] is node:
                update[level].next[level] = node.next[level]

        return True
```

