// MakePalindrome returns the shortest palindrome that starts with str.
func MakePalindrome(str string) string {
	chars := []rune(str)
	n := len(chars)
	if n < 2 {
		return str
	}

	// Build reverse(str) + sentinel + str.
	// The final KMP prefix length is the longest palindromic suffix.
	sequence := make([]int, 0, 2*n+1)
	for i := n - 1; i >= 0; i-- {
		sequence = append(sequence, int(chars[i]))
	}
	sequence = append(sequence, -1) // Not a valid Unicode code point.
	for _, ch := range chars {
		sequence = append(sequence, int(ch))
	}

	prefix := make([]int, len(sequence))
	for i := 1; i < len(sequence); i++ {
		j := prefix[i-1]
		for j > 0 && sequence[i] != sequence[j] {
			j = prefix[j-1]
		}
		if sequence[i] == sequence[j] {
			j++
		}
		prefix[i] = j
	}

	palindromeSuffixLen := prefix[len(prefix)-1]
	prefixLen := n - palindromeSuffixLen

	addition := make([]rune, prefixLen)
	for i := 0; i < prefixLen; i++ {
		addition[i] = chars[prefixLen-1-i]
	}

	return str + string(addition)
}
```

This runs in `O(n)` time and `O(n)` space, treating Unicode code points as characters.

