```go
func RescaleToUnit(numbers []float64) []float64 {
	minVal, maxVal := numbers[0], numbers[0]

	for _, number := range numbers[1:] {
		if number < minVal {
			minVal = number
		}
		if number > maxVal {
			maxVal = number
		}
	}

	result := make([]float64, len(numbers))

	// No such rescaling is possible when all values are equal.
	// Return zeros as the conventional normalization in this case.
	if minVal == maxVal {
		return result
	}

	scale := maxVal - minVal
	for i, number := range numbers {
		result[i] = (number - minVal) / scale
	}

	return result
}
