// LargestDivisor returns the largest positive divisor of n that is less than n.
// It returns 0 when no such divisor exists (n <= 1).
func LargestDivisor(n int) int {
	if n <= 1 {
		return 0
	}

	// The first divisor found is the smallest non-trivial divisor,
	// so its complementary divisor is the largest proper divisor.
	for divisor := 2; divisor <= n/divisor; divisor++ {
		if n%divisor == 0 {
			return n / divisor
		}
	}

	// n is prime.
	return 1
}
