func Factorize(n int) []int {
	factors := []int{}

	// Extract all factors of 2.
	for n >= 2 && n%2 == 0 {
		factors = append(factors, 2)
		n /= 2
	}

	// Test only odd divisors. Using divisor <= n/divisor avoids overflow.
	for divisor := 3; divisor <= n/divisor; divisor += 2 {
		for n%divisor == 0 {
			factors = append(factors, divisor)
			n /= divisor
		}
	}

	// Any remainder greater than 1 is prime.
	if n > 1 {
		factors = append(factors, n)
	}

	return factors
}
