package polynomial

import "math"

// FindZero returns one real zero of the polynomial
//
//	xs[0] + xs[1]*x + xs[2]*x^2 + ...
//
// The input is assumed to have an odd degree, so at least one real zero
// exists.
func FindZero(xs []int) float64 {
	if len(xs) == 0 {
		panic("FindZero: empty coefficient list")
	}

	// Ignore trailing zero coefficients.
	n := len(xs) - 1
	for n >= 0 && xs[n] == 0 {
		n--
	}

	// The zero polynomial has every number as a root.
	if n < 0 {
		return 0
	}

	// If the constant coefficient is zero, x = 0 is a root.
	if xs[0] == 0 {
		return 0
	}

	eval := func(x float64) float64 {
		y := float64(xs[n])
		for i := n - 1; i >= 0; i-- {
			y = y*x + float64(xs[i])
		}
		return y
	}

	// A value larger than the Cauchy root bound:
	// |root| <= 1 + max_i |a_i / a_n|.
	leading := math.Abs(float64(xs[n]))
	maxRatio := 0.0
	for i := 0; i < n; i++ {
		ratio := math.Abs(float64(xs[i])) / leading
		if ratio > maxRatio {
			maxRatio = ratio
		}
	}
	bound := 2 * (1 + maxRatio)

	lo, hi := -bound, bound
	flo, fhi := eval(lo), eval(hi)

	if flo == 0 {
		return lo
	}
	if fhi == 0 {
		return hi
	}
	if (flo < 0) == (fhi < 0) {
		panic("FindZero: polynomial does not have the promised odd degree")
	}

	// Bisect until no representable float remains between the endpoints.
	for i := 0; i < 2048; i++ {
		mid := lo + (hi-lo)/2
		if mid == lo || mid == hi {
			return mid
		}

		fmid := eval(mid)
		if fmid == 0 {
			return mid
		}

		if (fmid < 0) == (flo < 0) {
			lo, flo = mid, fmid
		} else {
			hi, fhi = mid, fmid
		}
	}

	return lo + (hi-lo)/2
}
```

