func TriplesSumToZero(l []int) bool {
	if len(l) < 3 {
		return false
	}

	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1

	for i := 0; i < len(l)-2; i++ {
		seen := make(map[int]struct{})

		for j := i + 1; j < len(l); j++ {
			a, b := l[i], l[j]

			// If a+b overflows, no int-valued third element can make
			// the mathematical sum equal zero.
			overflows := (b > 0 && a > maxInt-b) ||
				(b < 0 && a < minInt-b)

			if !overflows {
				sum := a + b

				// -minInt is not representable as an int.
				if sum != minInt {
					if _, found := seen[-sum]; found {
						return true
					}
				}
			}

			seen[b] = struct{}{}
		}
	}

	return false
}
