		remainder := n % base
		if remainder < 0 {
			remainder = -remainder
		}
		digits = append(digits, byte(remainder)+'0')
		n /= base
	}

	// Digits were generated in reverse order.
	for i, j := 0, len(digits)-1; i < j; i, j = i+1, j-1 {
		digits[i], digits[j] = digits[j], digits[i]
	}

	if negative {
		return "-" + string(digits)
	}
	return string(digits)
