// Modp returns 2^n modulo p.
// It uses binary exponentiation and overflow-safe modular multiplication.
func Modp(n int, p int) int {
	if n < 0 {
		panic("Modp: n must be non-negative")
	}
	if p <= 0 {
		panic("Modp: p must be positive")
	}

	result := 1 % p
	base := 2 % p

	for n > 0 {
		if n&1 == 1 {
			result = mulMod(result, base, p)
		}
		n >>= 1
		base = mulMod(base, base, p)
	}

	return result
}

// mulMod computes (a*b) % mod without overflowing int.
func mulMod(a, b, mod int) int {
	result := 0

	for b > 0 {
		if b&1 == 1 {
			result = addMod(result, a, mod)
		}
		b >>= 1
		if b > 0 {
			a = addMod(a, a, mod)
		}
	}

	return result
}

// addMod computes (a+b) % mod without overflowing int.
// It requires 0 <= a,b < mod.
func addMod(a, b, mod int) int {
	if a >= mod-b {
		return a - (mod - b)
	}
	return a + b
}
