import "math"

func TriangleArea(a float64, b float64, c float64) interface{} {
	if a <= 0 || b <= 0 || c <= 0 ||
		math.IsNaN(a) || math.IsNaN(b) || math.IsNaN(c) ||
		math.IsInf(a, 0) || math.IsInf(b, 0) || math.IsInf(c, 0) {
		return -1
	}

	// Sort so that a <= b <= c.
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}

	if a <= c-b {
		return -1
	}

	// Numerically stable form of Heron's formula.
	f1 := c + (b + a)
	f2 := a - (c - b)
	f3 := a + (c - b)
	f4 := c + (b - a)

	left := math.Sqrt(f1) * math.Sqrt(f2) / 2
	right := math.Sqrt(f3) * math.Sqrt(f4) / 2
	area := left * right

	if area <= math.MaxFloat64/100 {
		area = math.Round(area*100) / 100
	}

	return area
}
