// IsSimplePower reports whether x == n^k for some non-negative integer k.
func IsSimplePower(x int, n int) bool {
	// n^0 == 1 for any n.
	if x == 1 {
		return true
	}

	switch n {
	case 0:
		return x == 0 // 0^k == 0 for k > 0
	case 1:
		return false
	case -1:
		return x == -1
	}

	// A nonzero base cannot produce zero.
	if x == 0 {
		return false
	}

	for x != 1 {
		if x%n != 0 {
			return false
		}
		x /= n
	}

	return true
