import "strconv"

func Iscube(a int) bool {
	if a == 0 {
		return true
	}

	// Obtain the absolute value safely, including for the minimum int.
	var n uint
	if a < 0 {
		n = uint(-(a + 1)) + 1
	} else {
		n = uint(a)
	}

	lo := uint(1)
	hi := uint(1) << ((strconv.IntSize + 2) / 3)

	for lo <= hi {
		mid := lo + (hi-lo)/2
		square := mid * mid
		quotient := n / mid
		remainder := n % mid

		if square == quotient && remainder == 0 {
			return true
		}

		if square < quotient || (square == quotient && remainder > 0) {
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}

	return false
}
