func NextSmallest(lst []int) interface{} {
	var smallest, secondSmallest int
	hasSmallest, hasSecond := false, false

	for _, n := range lst {
		if !hasSmallest || n < smallest {
			if hasSmallest {
				secondSmallest = smallest
				hasSecond = true
			}
			smallest = n
			hasSmallest = true
		} else if n > smallest && (!hasSecond || n < secondSmallest) {
			secondSmallest = n
			hasSecond = true
		}
	}

	if !hasSecond {
