func AnyInt(x, y, z interface{}) bool {
	a, okA := asInteger(x)
	b, okB := asInteger(y)
	c, okC := asInteger(z)

	if !okA || !okB || !okC {
		return false
	}

	return new(big.Int).Add(a, b).Cmp(c) == 0 ||
		new(big.Int).Add(a, c).Cmp(b) == 0 ||
		new(big.Int).Add(b, c).Cmp(a) == 0
}

func asInteger(value interface{}) (*big.Int, bool) {
	if value == nil {
		return nil, false
	}

	v := reflect.ValueOf(value)

	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return big.NewInt(v.Int()), true

	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32,
		reflect.Uint64, reflect.Uintptr:
		return new(big.Int).SetUint64(v.Uint()), true

	case reflect.Float32, reflect.Float64:
		f := v.Float()
		if math.IsNaN(f) || math.IsInf(f, 0) || math.Trunc(f) != f {
			return nil, false
		}

		n, _ := new(big.Float).SetFloat64(f).Int(nil)
		return n, true

	default:
		return nil, false
	}
}
```

This supports all built-in integer types, integer-valued floats such as `3.0`, and rejects fractional or non-numeric values. Using `big.Int` also prevents overflow while calculating sums.

