func Encode(message string) string {
	result := []byte(message)

	for i, ch := range result {
		isVowel := ch == 'a' || ch == 'e' || ch == 'i' ||
			ch == 'o' || ch == 'u' || ch == 'A' ||
			ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U'

		switch {
		case ch >= 'a' && ch <= 'z':
			ch -= 'a' - 'A' // Convert to uppercase.
		case ch >= 'A' && ch <= 'Z':
			ch += 'a' - 'A' // Convert to lowercase.
		default:
