func Skjkasdkd(lst []int) int {
	isPrime := func(n int) bool {
		if n < 2 {
			return false
		}
		if n%2 == 0 {
			return n == 2
		}
		for divisor := 3; divisor <= n/divisor; divisor += 2 {
			if n%divisor == 0 {
				return false
			}
		}
		return true
	}

	largestPrime := 0
	for _, value := range lst {
		if value > largestPrime && isPrime(value) {
			largestPrime = value
		}
	}

	digitSum := 0
	for largestPrime > 0 {
		digitSum += largestPrime % 10
		largestPrime /= 10
	}

	return digitSum
}
