import "unicode"

func CheckDictCase(dict map[interface{}]interface{}) bool {
	if len(dict) == 0 {
		return false
	}

	allLower, allUpper := true, true

	for key := range dict {
		s, ok := key.(string)
		if !ok {
			return false
		}

		lower, upper := keyCase(s)
		allLower = allLower && lower
		allUpper = allUpper && upper

		if !allLower && !allUpper {
			return false
		}
	}

	return allLower || allUpper
}

// keyCase reports whether s is lowercase or uppercase. Non-letter
// characters are allowed, but the string must contain a cased letter.
func keyCase(s string) (lower, upper bool) {
	lower, upper = true, true
	hasCasedLetter := false

	for _, r := range s {
		switch {
		case unicode.IsLower(r):
			hasCasedLetter = true
			upper = false
		case unicode.IsUpper(r):
			hasCasedLetter = true
			lower = false
		case unicode.IsTitle(r):
			hasCasedLetter = true
			lower, upper = false, false
		}
	}

	if !hasCasedLetter {
		return false, false
	}

	return lower, upper
}
