func CountUpTo(n int) []int {
	primes := make([]int, 0)
	if n <= 2 {
		return primes
	}

	composite := make([]bool, n)

	// Mark composite numbers using the Sieve of Eratosthenes.
	for p := 2; p <= (n-1)/p; p++ {
		if !composite[p] {
			for multiple := p * p; multiple < n; multiple += p {
				composite[multiple] = true
			}
		}
	}

	for i := 2; i < n; i++ {
		if !composite[i] {
			primes = append(primes, i)
		}
	}

	return primes
}
