func CountNums(arr []int) int {
	count := 0

	for _, n := range arr {
		sum := 0

		if n >= 0 {
			for x := n; x != 0; x /= 10 {
				sum += x % 10
			}
		} else {
			x := n
			mostSignificant := 0

			for x != 0 {
				digit := -(x % 10)
				sum += digit
				mostSignificant = digit
				x /= 10
			}

			// Only the most significant digit carries the negative sign.
			sum -= 2 * mostSignificant
		}

		if sum > 0 {
			count++
		}
	}

	return count
}
