```go
package histogram

import "unicode"

func Histogram(test string) map[rune]int {
	counts := make(map[rune]int)
	maxCount := 0

	for _, letter := range test {
		if unicode.IsSpace(letter) {
			continue
		}

		counts[letter]++
		if counts[letter] > maxCount {
			maxCount = counts[letter]
		}
	}

	result := make(map[rune]int)
	for letter, count := range counts {
		if count == maxCount {
			result[letter] = count
		}
	}

	return result
}
```

Final answer: `Histogram` returns a map containing every most-frequent non-space rune and its count.

