package main

func ReverseDelete(s, c string) [2]interface{} {
	remove := make(map[rune]struct{})
	for _, ch := range c {
		remove[ch] = struct{}{}
	}

	filtered := make([]rune, 0, len(s))
	for _, ch := range s {
		if _, found := remove[ch]; !found {
			filtered = append(filtered, ch)
		}
	}

	isPalindrome := true
	for left, right := 0, len(filtered)-1; left < right; left, right = left+1, right-1 {
		if filtered[left] != filtered[right] {
			isPalindrome = false
			break
		}
	}

	return [2]interface{}{string(filtered), isPalindrome}
}
