func Minsubarraysum(nums []int) int {
	if len(nums) == 0 {
		panic("Minsubarraysum requires a non-empty slice")
	}

	currentMin := nums[0]
	globalMin := nums[0]

	for _, num := range nums[1:] {
		if currentMin+num < num {
			currentMin += num
		} else {
			currentMin = num
		}

		if currentMin < globalMin {
			globalMin = currentMin
		}
	}

	return globalMin
}
