func SortArray(arr []int) []int {
	sort.Slice(arr, func(i, j int) bool {
		onesI := bits.OnesCount64(uint64(arr[i]))
		onesJ := bits.OnesCount64(uint64(arr[j]))

		if onesI == onesJ {
