func Intersection(interval1 [2]int, interval2 [2]int) string {
	left := interval1[0]
	if interval2[0] > left {
		left = interval2[0]
	}

	right := interval1[1]
	if interval2[1] < right {
		right = interval2[1]
	}

	// No intersection, or the intersection is a single point with length 0.
	if right <= left {
		return "NO"
	}

	length := uint64(right) - uint64(left)
	if isPrime(length) {
		return "YES"
	}
	return "NO"
}

func isPrime(n uint64) bool {
	if n < 2 {
		return false
	}
	if n == 2 || n == 3 {
		return true
	}
	if n%2 == 0 || n%3 == 0 {
		return false
	}

	for divisor := uint64(5); divisor <= n/divisor; divisor += 6 {
		if n%divisor == 0 || n%(divisor+2) == 0 {
			return false
		}
	}
	return true
}
