func ProdSigns(arr []int) interface{} {
	if len(arr) == 0 {
		return nil
	}

	sum, signProduct := 0, 1

	for _, n := range arr {
		switch {
		case n < 0:
			sum += -n
			signProduct *= -1
		case n > 0:
			sum += n
		default:
			signProduct = 0
		}
	}

	return sum * signProduct
