func Tri(n int) []float64 {
	if n < 0 {
		return []float64{}
	}

	sequence := make([]float64, n+1)
	sequence[0] = 1

	if n >= 1 {
		sequence[1] = 3
	}

	for i := 2; i <= n; i++ {
		if i%2 == 0 {
			sequence[i] = 1 + float64(i)/2
		} else {
			// i+1 is even, so Tri(i+1) follows the even formula.
			next := 1 + float64(i+1)/2
			sequence[i] = sequence[i-1] + sequence[i-2] + next
		}
	}

	return sequence
}
