func GetMaxTriples(n int) int {
	// Computes C(x, 3), reducing factors first to limit overflow.
	choose3 := func(x int) int {
		if x < 3 {
			return 0
		}

		factors := [3]int{x, x - 1, x - 2}

		for i := range factors {
			if factors[i]%2 == 0 {
				factors[i] /= 2
				break
			}
		}
		for i := range factors {
			if factors[i]%3 == 0 {
				factors[i] /= 3
				break
			}
		}

		return factors[0] * factors[1] * factors[2]
	}

	// a[i] is 0 modulo 3 exactly when i is 2 modulo 3;
	// otherwise, it is 1 modulo 3.
	zeroCount := n / 3
	if n%3 == 2 {
		zeroCount++
	}
	oneCount := n - zeroCount

	// A valid triple must contain either three residue-0 values
	// or three residue-1 values.
	return choose3(zeroCount) + choose3(oneCount)
}
