package main

// DoAlgebra evaluates the expression using standard operator precedence.
// Exponentiation is right-associative; all other operators are left-associative.
func DoAlgebra(operator []string, operand []int) int {
	if len(operand) < 2 || len(operator) != len(operand)-1 {
		panic("invalid operator or operand count")
	}

	precedence := func(op string) int {
		switch op {
		case "+", "-":
			return 1
		case "*", "//":
			return 2
		case "**":
			return 3
		default:
			panic("unsupported operator: " + op)
		}
	}

	pow := func(base, exponent int) int {
		if exponent < 0 {
			panic("negative exponent is not supported")
		}

		result := 1
		for exponent > 0 {
			if exponent&1 == 1 {
				result *= base
			}
			base *= base
			exponent >>= 1
		}
		return result
	}

	// Unlike Go integer division, floor division rounds toward negative infinity.
	floorDiv := func(a, b int) int {
		if b == 0 {
			panic("division by zero")
		}

		q, r := a/b, a%b
		if r != 0 && (r > 0) != (b > 0) {
			q--
		}
		return q
	}

	operandPos, operatorPos := 0, 0

	// Precedence-climbing parser over the alternating operand/operator lists.
	var parse func(minPrecedence int) int
	parse = func(minPrecedence int) int {
		left := operand[operandPos]
		operandPos++

		for operatorPos < len(operator) {
			op := operator[operatorPos]
			opPrecedence := precedence(op)
			if opPrecedence < minPrecedence {
				break
			}

			operatorPos++

			// ** is right-associative. All other operators are left-associative.
			nextMinPrecedence := opPrecedence + 1
			if op == "**" {
				nextMinPrecedence = opPrecedence
			}

			right := parse(nextMinPrecedence)

			switch op {
			case "+":
				left += right
			case "-":
				left -= right
			case "*":
				left *= right
			case "//":
				left = floorDiv(left, right)
			case "**":
				left = pow(left, right)
			}
		}

		return left
	}

	return parse(1)
}
