#include <string>
#include <vector>

std::string make_palindrome(std::string str) {
    const std::size_t n = str.size();
    if (n == 0) {
        return str;
    }

    // A palindromic suffix of str matches a prefix of reversed.
    const std::string reversed(str.rbegin(), str.rend());

    // Prefix-function for the KMP pattern `reversed`.
    std::vector<std::size_t> prefix(n, 0);
    for (std::size_t i = 1; i < n; ++i) {
        std::size_t j = prefix[i - 1];

        while (j > 0 && reversed[i] != reversed[j]) {
            j = prefix[j - 1];
        }
        if (reversed[i] == reversed[j]) {
            ++j;
        }

        prefix[i] = j;
    }

    // Find the longest suffix of str matching a prefix of reversed.
    std::size_t suffix_length = 0;
    for (char ch : str) {
        while (suffix_length > 0 &&
               ch != reversed[suffix_length]) {
            suffix_length = prefix[suffix_length - 1];
        }
        if (ch == reversed[suffix_length]) {
            ++suffix_length;
        }
    }

    // Reverse and append the prefix before the palindromic suffix.
    std::string result = str;
    result.reserve(2 * n - suffix_length);

    for (std::size_t i = n - suffix_length; i > 0; --i) {
        result.push_back(str[i - 1]);
    }

    return result;
}
```

