Because the number of coefficients is even and the highest-degree coefficient is nonzero, the polynomial has odd degree and therefore at least one real root. A Cauchy bound brackets all real roots, after which bisection finds one of them.

```cpp
#include <vector>
#include <cmath>
#include <algorithm>

double find_zero(std::vector<double> xs) {
    // Scale the coefficients to reduce the chance of overflow.
    long double scale = 0.0L;
    for (double x : xs) {
        scale = std::max(scale, std::fabs(static_cast<long double>(x)));
    }

    std::vector<long double> coefficients;
    coefficients.reserve(xs.size());
    for (double x : xs) {
        coefficients.push_back(static_cast<long double>(x) / scale);
    }

    auto poly = [&](long double x) {
        // Horner's method; coefficients are in ascending order.
        long double result = 0.0L;
        for (auto it = coefficients.rbegin(); it != coefficients.rend(); ++it) {
            result = result * x + *it;
        }
        return result;
    };

    // If the constant term is zero, zero itself is a root.
    if (coefficients[0] == 0.0L) {
        return 0.0;
    }

    // Every root satisfies
    // |x| <= 1 + max_i |a_i / a_n|.
    const long double leading = std::fabs(coefficients.back());
    long double bound = 1.0L;

    for (std::size_t i = 0; i + 1 < coefficients.size(); ++i) {
        bound = std::max(
            bound,
            1.0L + std::fabs(coefficients[i]) / leading
        );
    }

    // Using a slightly larger interval avoids roots exactly on the bound.
    long double lo = -2.0L * bound;
    long double hi =  2.0L * bound;
    long double flo = poly(lo);
    long double fhi = poly(hi);

    if (flo == 0.0L) return static_cast<double>(lo);
    if (fhi == 0.0L) return static_cast<double>(hi);

    // The odd degree guarantees opposite signs at sufficiently large
    // negative and positive arguments.
    for (int iteration = 0; iteration < 4096; ++iteration) {
        long double mid = lo + (hi - lo) / 2.0L;

        // No further representable refinement is possible.
        if (mid == lo || mid == hi) {
            break;
        }

        long double fmid = poly(mid);
        if (fmid == 0.0L) {
            return static_cast<double>(mid);
        }

        if ((flo < 0.0L && fmid > 0.0L) ||
            (flo > 0.0L && fmid < 0.0L)) {
            hi = mid;
            fhi = fmid;
        } else {
            lo = mid;
            flo = fmid;
        }
    }

    return static_cast<double>(lo + (hi - lo) / 2.0L);
}
```

