    int c = 2; // fib4(2)
    int d = 0; // fib4(3)

    for (int i = 4; i <= n; ++i) {
        long long next = static_cast<long long>(a) + b + c + d;

        if (next > std::numeric_limits<int>::max()) {
            throw std::overflow_error("fib4 result exceeds int range");
