float triangle_area(float a, float b, float c)
{
    const double x = a;
    const double y = b;
    const double z = c;

    if (x <= 0.0 || y <= 0.0 || z <= 0.0 ||
        x + y <= z || x + z <= y || y + z <= x) {
        return -1.0f;
