bool is_simple_power(int x, int n)
{
    long long value = x;
    const long long base = n;

    // Any base to exponent 0 equals 1.
    if (value == 1)
        return true;

    if (base == 0)
        return value == 0;  // 0^k = 0 for k > 0

    if (base == 1)
        return false;

    if (base == -1)
        return value == -1;

    // Zero cannot be a power of a nonzero base.
    if (value == 0)
        return false;

    while (value % base == 0) {
        value /= base;
        if (value == 1)
            return true;
    }

    return false;
}
