bool iscube(int a) {
    long long n = a;
    if (n < 0) n = -n;

    long long low = 0;
    long long high = n;

    while (low <= high) {
        long long mid = low + (high - low) / 2;

        if (mid == 0) {
            if (n == 0) return true;
            low = 1;
            continue;
        }

        // Check whether mid^3 > n without risking overflow.
        if (mid > n / mid / mid) {
            high = mid - 1;
        } else {
            long long cube = mid * mid * mid;
            if (cube == n) return true;
            low = mid + 1;
        }
    }

    return false;
}
