    // Count lowercase letters with odd zero-based alphabet positions.
    int count = 0;
    for (char ch : txt) {
        if (ch >= 'a' && ch <= 'z' && (ch - 'a') % 2 == 1) {
            ++count;
        }
    }

    return {std::to_string(count)};
