bool right_angle_triangle(float a, float b, float c)
{
    if (!std::isfinite(a) || !std::isfinite(b) || !std::isfinite(c) ||
        a <= 0.0f || b <= 0.0f || c <= 0.0f) {
        return false;
    }

    std::array<double, 3> sides{a, b, c};
    std::sort(sides.begin(), sides.end());

    // The sides must form a non-degenerate triangle.
    if (sides[0] + sides[1] <= sides[2]) {
        return false;
    }

    const double lhs = sides[0] * sides[0] + sides[1] * sides[1];
    const double rhs = sides[2] * sides[2];

    // Allow for rounding errors in the float inputs.
    const double tolerance =
        8.0 * std::numeric_limits<float>::epsilon() * std::max(lhs, rhs);

    return std::abs(lhs - rhs) <= tolerance;
}
