but now you need to eat more carrots to complete the day's meals.
you should return a vector of { total number of eaten carrots after your meals,
the number of carrots left after your meals }
if there are not enough remaining carrots, you will eat all remaining carrots, but will still be hungry.
Example:
* eat(5, 6, 10) -> {11, 4}
* eat(4, 8, 9) -> {12, 1}
* eat(1, 10, 10) -> {11, 0}
* eat(2, 11, 5) -> {7, 0}
Variables:
@number : integer
the number of carrots that you have eaten.
@need : integer
the number of carrots that you need to eat.
@remaining : integer
the number of remaining carrots thet exist in stock
Constrain:
* 0 <= number <= 1000
* 0 <= need <= 1000
* 0 <= remaining <= 1000
Have fun :)

ground_truth:
```cpp
#include <algorithm>
#include <vector>
using namespace std;

vector<int> eat(int number, int need, int remaining) {
    int eaten = min(need, remaining);
    return {number + eaten, remaining - eaten};
}
```

The expression is parsed with standard precedence:

1. `**` — right-associative
2. `*`, `//` — left-associative
3. `+`, `-` — left-associative

```cpp
#include <bits/stdc++.h>
using namespace std;

int do_algebra(vector<string> operato, vector<int> operand) {
    size_t operandPos = 0;
    size_t operatorPos = 0;

    auto integerPower = [](long long base, long long exponent) {
        long long result = 1;

        while (exponent > 0) {
            if (exponent & 1LL)
                result *= base;

            exponent >>= 1LL;
            if (exponent > 0)
                base *= base;
        }

        return result;
    };

    // Mathematical floor division, including for negative intermediate values.
    auto floorDivide = [](long long a, long long b) {
        if (b == 0)
            throw domain_error("Division by zero");

        long long quotient = a / b;
        long long remainder = a % b;

        if (remainder != 0 && ((remainder < 0) != (b < 0)))
            --quotient;

        return quotient;
    };

    function<long long()> parseExpression;
    function<long long()> parseTerm;
    function<long long()> parsePower;

    // Exponentiation is right-associative: a ** b ** c = a ** (b ** c).
    parsePower = [&]() -> long long {
        long long base = operand[operandPos++];

        if (operatorPos < operato.size() &&
            operato[operatorPos] == "**") {
            ++operatorPos;
            long long exponent = parsePower();
            return integerPower(base, exponent);
        }

        return base;
    };

    parseTerm = [&]() -> long long {
        long long value = parsePower();

        while (operatorPos < operato.size() &&
               (operato[operatorPos] == "*" ||
                operato[operatorPos] == "//")) {
            string op = operato[operatorPos++];
            long long right = parsePower();

            if (op == "*")
                value *= right;
            else
                value = floorDivide(value, right);
        }

        return value;
    };

    parseExpression = [&]() -> long long {
        long long value = parseTerm();

        while (operatorPos < operato.size() &&
               (operato[operatorPos] == "+" ||
                operato[operatorPos] == "-")) {
            string op = operato[operatorPos++];
            long long right = parseTerm();

            if (op == "+")
                value += right;
            else
                value -= right;
        }

        return value;
    };

    return static_cast<int>(parseExpression());
}
```

This assumes the expression contains no division by zero and that its result fits in an `int`.

