        0x289b7ec6, 0xeaa127fa, 0xd4ef3085, 0x04881d05,
        0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
        0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039,
        0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
        0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1,
        0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391
    };

    auto rotate_left = [](std::uint32_t value, std::uint32_t amount) {
        return static_cast<std::uint32_t>(
            (value << amount) | (value >> (32U - amount))
        );
    };

    const std::uint64_t bit_length =
        static_cast<std::uint64_t>(text.size()) * 8ULL;

    std::vector<std::uint8_t> message(text.begin(), text.end());

    // Append the mandatory 1 bit, represented by 0x80.
    message.push_back(0x80);

    // Pad until the size is 56 modulo 64 bytes.
    while (message.size() % 64 != 56) {
        message.push_back(0);
    }

    // Append the original bit length as a 64-bit little-endian integer.
    for (int i = 0; i < 8; ++i) {
        message.push_back(
            static_cast<std::uint8_t>((bit_length >> (8 * i)) & 0xffU)
        );
    }

    std::uint32_t h0 = 0x67452301;
    std::uint32_t h1 = 0xefcdab89;
    std::uint32_t h2 = 0x98badcfe;
    std::uint32_t h3 = 0x10325476;

    for (std::size_t offset = 0; offset < message.size(); offset += 64) {
        std::array<std::uint32_t, 16> words{};

        for (std::size_t i = 0; i < 16; ++i) {
            const std::size_t j = offset + i * 4;
            words[i] =
                static_cast<std::uint32_t>(message[j]) |
                (static_cast<std::uint32_t>(message[j + 1]) << 8) |
                (static_cast<std::uint32_t>(message[j + 2]) << 16) |
                (static_cast<std::uint32_t>(message[j + 3]) << 24);
        }

        std::uint32_t a = h0;
        std::uint32_t b = h1;
        std::uint32_t c = h2;
        std::uint32_t d = h3;

        for (std::uint32_t i = 0; i < 64; ++i) {
            std::uint32_t f;
            std::uint32_t word_index;

            if (i < 16) {
                f = (b & c) | (~b & d);
                word_index = i;
            } else if (i < 32) {
                f = (d & b) | (~d & c);
                word_index = (5 * i + 1) % 16;
            } else if (i < 48) {
                f = b ^ c ^ d;
                word_index = (3 * i + 5) % 16;
            } else {
                f = c ^ (b | ~d);
                word_index = (7 * i) % 16;
            }

            const std::uint32_t old_d = d;
            d = c;
            c = b;
            b += rotate_left(
                a + f + constants[i] + words[word_index],
                shifts[i]
            );
            a = old_d;
        }

        h0 += a;
        h1 += b;
        h2 += c;
        h3 += d;
    }

    const std::array<std::uint32_t, 4> hash = {h0, h1, h2, h3};

    std::ostringstream result;
    result << std::hex << std::setfill('0');

    // MD5 outputs each state word in little-endian byte order.
    for (std::uint32_t word : hash) {
        for (int i = 0; i < 4; ++i) {
            result << std::setw(2)
                   << ((word >> (8 * i)) & 0xffU);
        }
    }

    return result.str();
}
