using namespace std;

vector<int> generate_integers(int a, int b) {
    int lower = min(a, b);
    int upper = max(a, b);
    vector<int> result;

    for (int digit = 2; digit <= 8; digit += 2) {
        if (digit >= lower && digit <= upper) {
