const parseNestedParens = (paren_string) => {
  const groups = paren_string.trim().split(/\s+/);

  if (paren_string.trim() === "") return [];

  return groups.map(group => {
    let depth = 0;
    let maxDepth = 0;

    for (const char of group) {
      if (char === "(") {
        depth++;
        maxDepth = Math.max(maxDepth, depth);
      } else if (char === ")") {
        depth--;
        if (depth < 0) throw new SyntaxError("Unbalanced parentheses");
      } else {
        throw new SyntaxError(`Invalid character: ${char}`);
      }
    }

    if (depth !== 0) throw new SyntaxError("Unbalanced parentheses");
    return maxDepth;
  });
};

