const makePalindrome = (string) => {
  const chars = [...string];

  const isPalindromeFrom = (start) => {
    let left = start;
    let right = chars.length - 1;

    while (left < right) {
      if (chars[left] !== chars[right]) return false;
      left++;
      right--;
    }

    return true;
  };

  for (let start = 0; start <= chars.length; start++) {
    if (isPalindromeFrom(start)) {
      const reversedPrefix = chars.slice(0, start).reverse().join('');
      return string + reversedPrefix;
    }
  }
};
```

The first palindromic suffix found is the longest, so appending the reversed preceding prefix produces the shortest possible palindrome.

