const rescaleToUnit = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length < 2) {
    throw new TypeError("Expected an array containing at least two numbers.");
  }

  let min = Infinity;
  let max = -Infinity;

  for (const number of numbers) {
    if (typeof number !== "number" || !Number.isFinite(number)) {
      throw new TypeError("Every element must be a finite number.");
    }

    min = Math.min(min, number);
    max = Math.max(max, number);
  }

  if (min === max) {
    throw new RangeError("Cannot rescale a list whose values are all equal.");
  }

  const range = max - min;
  return numbers.map((number) => (number - min) / range);
};

