const findZero = (xs) => {
  if (
    !Array.isArray(xs) ||
    xs.length < 2 ||
    xs.length % 2 !== 0 ||
    xs[xs.length - 1] === 0 ||
    !xs.every(Number.isFinite)
  ) {
    throw new TypeError(
      "xs must contain an even number of finite coefficients with a nonzero last coefficient"
    );
  }

  // Coefficients are ordered from the constant term upward.
  const poly = (x) => {
    let value = xs[xs.length - 1];
    for (let i = xs.length - 2; i >= 0; i--) {
      value = value * x + xs[i];
    }
    return value;
  };

  // Find an interval whose endpoints have opposite signs.
  let radius = 1;
  let lo, hi, fLo, fHi;

  while (true) {
    lo = -radius;
    hi = radius;
    fLo = poly(lo);
    fHi = poly(hi);

    if (fLo === 0) return lo;
    if (fHi === 0) return hi;

    if ((fLo < 0) !== (fHi < 0)) break;

    const nextRadius = radius * 2;
    if (!Number.isFinite(nextRadius)) {
      if (radius === Number.MAX_VALUE) {
        throw new RangeError("The root is outside JavaScript's finite range");
      }
      radius = Number.MAX_VALUE;
    } else {
      radius = nextRadius;
    }
  }

  // Bisection. It returns one root if the polynomial has several.
  for (let i = 0; i < 200; i++) {
    const mid = lo / 2 + hi / 2;

    // No further representable refinement is possible.
    if (mid === lo || mid === hi) return mid;

    const fMid = poly(mid);
    if (fMid === 0) return mid;

    if ((fMid < 0) === (fLo < 0)) {
      lo = mid;
      fLo = fMid;
    } else {
      hi = mid;
      fHi = fMid;
    }
  }

  return lo / 2 + hi / 2;
};

// Examples:
// Math.round(findZero([1, 2]) * 100) / 100                 // -0.5
// Math.round(findZero([-6, 11, -6, 1]) * 100) / 100       // 1
