const modp = (n, p) => {
  const toBigInt = (value, name) => {
    if (typeof value === "bigint") return value;

    if (typeof value === "number" && Number.isSafeInteger(value)) {
      return BigInt(value);
    }

    throw new RangeError(`${name} must be a safe integer or a BigInt`);
