  const modulus = toBigInt(p, "p");

  if (exponent < 0n) throw new RangeError("n must be non-negative");
  if (modulus <= 0n) throw new RangeError("p must be positive");

  let base = 2n % modulus;
  let result = 1n % modulus;

  while (exponent > 0n) {
    if (exponent & 1n) {
      result = (result * base) % modulus;
    }

    base = (base * base) % modulus;
    exponent >>= 1n;
  }

