const histogram = (test) => {
  const counts = {};
  let maxCount = 0;

  for (const letter of test.trim().split(/\s+/)) {
    if (!letter) continue;

    counts[letter] = (counts[letter] ?? 0) + 1;
    maxCount = Math.max(maxCount, counts[letter]);
