const doAlgebra = (operator, operand) => {
  const precedence = {
    "+": 1,
    "-": 1,
    "*": 2,
    "//": 2,
    "**": 3
  };

  const values = [operand[0]];
  const operators = [];

  const applyOperation = () => {
    const op = operators.pop();
    const right = values.pop();
    const left = values.pop();

    switch (op) {
      case "+":
        values.push(left + right);
        break;
      case "-":
        values.push(left - right);
        break;
      case "*":
        values.push(left * right);
        break;
      case "//":
        values.push(Math.floor(left / right));
        break;
      case "**":
        values.push(left ** right);
        break;
      default:
        throw new Error(`Unsupported operator: ${op}`);
    }
  };

  for (let i = 0; i < operator.length; i++) {
    const current = operator[i];

    // Exponentiation is right-associative; all other operators are
    // left-associative.
    while (
      operators.length > 0 &&
      (
        precedence[operators.at(-1)] > precedence[current] ||
        (
          precedence[operators.at(-1)] === precedence[current] &&
          current !== "**"
        )
      )
    ) {
      applyOperation();
    }

    operators.push(current);
    values.push(operand[i + 1]);
  }

  while (operators.length > 0) {
    applyOperation();
  }

  return values[0];
};
```

This respects standard operator precedence, left-associative floor division, and right-associative exponentiation.

