fn find_closest_elements(mut numbers: Vec<f32>) -> (f32, f32) {
    assert!(numbers.len() >= 2, "at least two numbers are required");
    assert!(
        numbers.iter().all(|number| !number.is_nan()),
        "NaN values are not supported"
    );

    numbers.sort_by(f32::total_cmp);

    let mut closest = (numbers[0], numbers[1]);
    let mut smallest_difference = if closest.0 == closest.1 {
        0.0
    } else {
        closest.1 - closest.0
    };

    for pair in numbers.windows(2).skip(1) {
        let difference = if pair[0] == pair[1] {
            0.0
        } else {
            pair[1] - pair[0]
        };

        if difference < smallest_difference {
            smallest_difference = difference;
            closest = (pair[0], pair[1]);
        }
    }

    closest
}
