pub fn rescale_to_unit(numbers: Vec<f32>) -> Vec<f32> {
    assert!(numbers.len() >= 2, "at least two numbers are required");
    assert!(
        numbers.iter().all(|x| x.is_finite()),
        "all numbers must be finite"
    );

    let min = numbers.iter().copied().fold(f32::INFINITY, f32::min);
    let max = numbers
        .iter()
        .copied()
        .fold(f32::NEG_INFINITY, f32::max);

    assert!(max > min, "the numbers must not all be equal");

    let range = max - min;
    numbers.into_iter().map(|x| (x - min) / range).collect()
}
