pub fn factorize(n: i32) -> Vec<i32> {
    assert!(n >= 1, "prime factorization is defined here only for positive integers");

    let mut remaining = n;
    let mut factors = Vec::new();

    while remaining % 2 == 0 {
        factors.push(2);
        remaining /= 2;
    }

    let mut divisor = 3;
    // Using division instead of divisor * divisor avoids integer overflow.
    while divisor <= remaining / divisor {
        while remaining % divisor == 0 {
            factors.push(divisor);
            remaining /= divisor;
        }
        divisor += 2;
    }

    if remaining > 1 {
        factors.push(remaining);
    }

    factors
}
