Assuming `xs[i]` is the coefficient of \(x^i\), an even coefficient count and a nonzero last coefficient imply an odd-degree polynomial. A Cauchy bound brackets every real root, after which bisection finds one root.

```rust
pub fn find_zero(xs: &Vec<f64>) -> f64 {
    assert!(!xs.is_empty(), "the coefficient list must not be empty");
    assert!(
        xs.len() % 2 == 0,
        "the polynomial must have an even number of coefficients"
    );
    assert!(
        xs.iter().all(|c| c.is_finite()),
        "coefficients must be finite"
    );

    let leading = *xs.last().unwrap();
    assert!(leading != 0.0, "the highest-degree coefficient must be nonzero");

    fn eval(xs: &[f64], x: f64) -> f64 {
        // Horner's method for xs[i] * x^i.
        xs.iter().rev().fold(0.0, |value, &c| value * x + c)
    }

    fn opposite_signs(a: f64, b: f64) -> bool {
        (a < 0.0) != (b < 0.0)
    }

    // Every root satisfies:
    // |x| <= 1 + max_i<n |xs[i] / xs[n]|.
    let mut max_ratio = 0.0_f64;
    for &coefficient in &xs[..xs.len() - 1] {
        max_ratio = max_ratio.max(coefficient.abs() / leading.abs());
    }

    let mut radius = 1.0 + max_ratio;
    if !radius.is_finite() {
        radius = f64::MAX;
    }

    let mut lo = -radius;
    let mut hi = radius;
    let mut f_lo = eval(xs, lo);
    let f_hi = eval(xs, hi);

    if f_lo == 0.0 {
        return lo;
    }
    if f_hi == 0.0 {
        return hi;
    }

    assert!(
        opposite_signs(f_lo, f_hi),
        "a root cannot be bracketed within the representable f64 range"
    );

    // Continue until no representable f64 remains strictly between the
    // endpoints. The large limit also handles brackets spanning almost the
    // entire floating-point exponent range.
    for _ in 0..4096 {
        // This form avoids overflow from computing hi - lo.
        let mid = lo * 0.5 + hi * 0.5;

        if mid == lo || mid == hi {
            break;
        }

        let f_mid = eval(xs, mid);
        if f_mid == 0.0 {
            return mid;
        }

        if opposite_signs(f_lo, f_mid) {
            hi = mid;
        } else {
            lo = mid;
            f_lo = f_mid;
        }
    }

    // Return the endpoint with the smaller residual.
    if eval(xs, lo).abs() <= eval(xs, hi).abs() {
        lo
    } else {
        hi
    }
}
```

