pub fn prime_fib(n: i32) -> i32 {
    assert!(n >= 1, "n must be positive");

    fn is_prime(x: i32) -> bool {
        if x < 2 {
            return false;
        }
        if x % 2 == 0 {
            return x == 2;
        }

        let mut divisor = 3_i64;
        let x = x as i64;

        while divisor * divisor <= x {
            if x % divisor == 0 {
                return false;
            }
            divisor += 2;
        }
        true
    }

    let mut a = 0_i32;
    let mut b = 1_i32;
    let mut count = 0;

    loop {
        if is_prime(a) {
            count += 1;
            if count == n {
                return a;
            }
        }

        let next = a.checked_add(b).expect(
            "the requested prime Fibonacci number cannot be represented as i32",
        );
        a = b;
        b = next;
    }
}
