fn triangle_area(a: i32, b: i32, c: i32) -> f64 {
    let (a, b, c) = (a as i64, b as i64, c as i64);

    if a <= 0
        || b <= 0
        || c <= 0
        || a + b <= c
        || a + c <= b
        || b + c <= a
