pub fn modp(n: i32, p: i32) -> i32 {
    assert!(n >= 0, "exponent must be non-negative");
    assert!(p > 0, "modulus must be positive");

    let modulus = i64::from(p);
    let mut exponent = n as u32;
    let mut base = 2_i64 % modulus;
    let mut result = 1_i64 % modulus;

    while exponent > 0 {
        if exponent & 1 == 1 {
            result = (result * base) % modulus;
        }
        base = (base * base) % modulus;
        exponent >>= 1;
    }

    result as i32
}
