pub fn circular_shift(x: i32, shift: i32) -> String {
    let value = x.to_string();
    let (sign, digits) = match value.strip_prefix('-') {
        Some(digits) => ("-", digits),
        None => ("", value.as_str()),
    };

    let len = digits.len();

    let result = if shift > len as i32 {
        digits.chars().rev().collect::<String>()
    } else {
        // rem_euclid also handles negative shifts consistently.
        let amount = shift.rem_euclid(len as i32) as usize;
        let split = len - amount;
        format!("{}{}", &digits[split..], &digits[..split])
    };

    format!("{sign}{result}")
}
```

