pub fn triangle_area_f64(a: f64, b: f64, c: f64) -> f64 {
    if !a.is_finite() || !b.is_finite() || !c.is_finite()
        || a <= 0.0 || b <= 0.0 || c <= 0.0
    {
        return -1.0;
    }

    let mut sides = [a, b, c];
    sides.sort_by(|x, y| x.partial_cmp(y).unwrap());

    let [x, y, z] = sides;

    if x + y <= z {
        return -1.0;
    }

    // Numerically stable form of Heron's formula, scaled to reduce
    // intermediate overflow and underflow.
    let xn = x / z;
    let yn = y / z;

    let product = (1.0 + (yn + xn))
        * (xn - (1.0 - yn))
        * (xn + (1.0 - yn))
        * (1.0 + (yn - xn));

    let normalized_area = 0.25 * product.max(0.0).sqrt();
    let area = (normalized_area * z) * z;

    if area.is_finite() && area <= f64::MAX / 100.0 {
        (area * 100.0).round() / 100.0
    } else {
        area
    }
}
```

Final answer: The function above validates the triangle, computes its area using a stable form of Heron’s formula, and rounds it to two decimal places.

