    let mut smallest: Option<i32> = None;
    let mut second_smallest: Option<i32> = None;

    for value in lst {
        match smallest {
            None => smallest = Some(value),

            Some(first) if value < first => {
                second_smallest = smallest;
                smallest = Some(value);
            }

            Some(first) if value > first => {
                if second_smallest.is_none_or(|second| value < second) {
