use std::collections::HashMap;

pub fn check_dict_case(dict: HashMap<&str, &str>) -> bool {
    if dict.is_empty() {
        return false;
    }

    fn is_cased(c: char) -> bool {
        c.to_lowercase().collect::<String>() != c.to_uppercase().collect::<String>()
    }

    fn is_lowercase(s: &str) -> bool {
        let mut has_cased_character = false;

        for c in s.chars() {
            if is_cased(c) {
                has_cased_character = true;
                if !c.is_lowercase() {
                    return false;
                }
            }
        }

        has_cased_character
    }

    fn is_uppercase(s: &str) -> bool {
        let mut has_cased_character = false;

        for c in s.chars() {
            if is_cased(c) {
                has_cased_character = true;
                if !c.is_uppercase() {
                    return false;
                }
            }
        }

        has_cased_character
    }

    dict.keys().all(|key| is_lowercase(key))
        || dict.keys().all(|key| is_uppercase(key))
}
