pub fn count_up_to(n: i32) -> Vec<i32> {
    if n <= 2 {
        return Vec::new();
    }

    let limit = n as usize;
    let mut is_prime = vec![true; limit];
    is_prime[0] = false;
    is_prime[1] = false;

    let mut p = 2;
    while p <= (limit - 1) / p {
        if is_prime[p] {
            let mut multiple = p * p;
            while multiple < limit {
                is_prime[multiple] = false;
                multiple += p;
            }
        }
        p += 1;
    }

    is_prime
        .into_iter()
        .enumerate()
        .filter_map(|(value, prime)| prime.then_some(value as i32))
        .collect()
}
```

