pub fn get_closest_vowel(word: &str) -> String {
    fn is_vowel(byte: u8) -> bool {
        matches!(byte, b'a' | b'e' | b'i' | b'o' | b'u'
                     | b'A' | b'E' | b'I' | b'O' | b'U')
