pub fn tri(n: i32) -> Vec<i32> {
    assert!(n >= 0, "n must be non-negative");

    let mut sequence: Vec<i32> = Vec::with_capacity(n as usize + 1);

    for i in 0..=n {
        let value = if i == 1 {
            3
        } else if i % 2 == 0 {
            1 + i / 2
        } else {
            // i + 1 is even, so tri(i + 1) = 1 + (i + 1) / 2.
            sequence[(i - 1) as usize]
                + sequence[(i - 2) as usize]
                + 1
                + (i + 1) / 2
        };

        sequence.push(value);
    }

    sequence
}
