use std::any::Any;
use std::cmp::Ordering;

#[derive(Debug, PartialEq)]
pub enum RtnType<S, F, I> {
    String(S),
    Float(F),
    Int(I),
    None,
}

enum Number {
    String(String, f64),
    Float(f64),
    Int(i32),
}

impl Number {
    fn value(&self) -> f64 {
        match self {
            Number::String(_, value) => *value,
            Number::Float(value) => *value,
            Number::Int(value) => f64::from(*value),
        }
    }

    fn into_result(self) -> RtnType<String, f64, i32> {
        match self {
            Number::String(original, _) => RtnType::String(original),
            Number::Float(value) => RtnType::Float(value),
            Number::Int(value) => RtnType::Int(value),
        }
    }
}

fn number_from_any(value: &dyn Any) -> Number {
    if let Some(value) = value.downcast_ref::<i32>() {
        Number::Int(*value)
    } else if let Some(value) = value.downcast_ref::<f64>() {
        Number::Float(*value)
    } else if let Some(value) = value.downcast_ref::<String>() {
        let parsed = value
            .trim()
            .replace(',', ".")
            .parse::<f64>()
            .expect("string must represent a real number");

        Number::String(value.clone(), parsed)
    } else if let Some(value) = value.downcast_ref::<&str>() {
        let parsed = value
            .trim()
            .replace(',', ".")
            .parse::<f64>()
            .expect("string must represent a real number");

        Number::String((*value).to_owned(), parsed)
    } else {
        panic!("expected an i32, f64, String, or &str");
    }
}

pub fn compare_one<'a>(
    a: &'a dyn Any,
    b: &'a dyn Any,
) -> RtnType<String, f64, i32> {
    let a = number_from_any(a);
    let b = number_from_any(b);

    match a
        .value()
        .partial_cmp(&b.value())
        .expect("NaN is not a real number")
    {
        Ordering::Greater => a.into_result(),
        Ordering::Less => b.into_result(),
        Ordering::Equal => RtnType::None,
    }
}
