pub fn simplify(x: &str, n: &str) -> bool {
    fn parse_fraction(s: &str) -> (u128, u128) {
        let (numerator, denominator) = s.split_once('/').unwrap();
        (
            numerator.parse().unwrap(),
            denominator.parse().unwrap(),
        )
    }

    fn gcd(mut a: u128, mut b: u128) -> u128 {
        while b != 0 {
            (a, b) = (b, a % b);
        }
        a
    }

    let (mut a, mut b) = parse_fraction(x);
    let (mut c, mut d) = parse_fraction(n);

    // Cancel denominator factors against both numerators, avoiding
    // multiplication and its associated overflow risk.
    let g = gcd(a, b);
    a /= g;
    b /= g;

    let g = gcd(c, b);
    c /= g;
    b /= g;

    let g = gcd(a, d);
    a /= g;
    d /= g;

    let g = gcd(c, d);
    d /= g;

    b == 1 && d == 1
}
