pub fn strongest_extension(class_name: &str, extensions: Vec<&str>) -> String {
    fn strength(extension: &str) -> i32 {
        extension.chars().fold(0, |score, ch| {
            if ch.is_uppercase() {
                score + 1
            } else if ch.is_lowercase() {
                score - 1
            } else {
                score
            }
        })
    }

    let mut strongest = extensions[0];
    let mut highest_strength = strength(strongest);

    for extension in extensions.into_iter().skip(1) {
        let current_strength = strength(extension);

        // Using `>` preserves the first extension in case of a tie.
        if current_strength > highest_strength {
            strongest = extension;
            highest_strength = current_strength;
        }
    }

    format!("{}.{}", class_name, strongest)
}
