```rust
pub fn right_angle_triangle(a: f32, b: f32, c: f32) -> bool {
    if !a.is_finite() || !b.is_finite() || !c.is_finite()
        || a <= 0.0 || b <= 0.0 || c <= 0.0
    {
        return false;
    }

    let mut sides = [a as f64, b as f64, c as f64];
    sides.sort_by(|x, y| x.total_cmp(y));

    let [x, y, z] = sides;

    // The side lengths must form a non-degenerate triangle.
    if x + y <= z {
        return false;
    }

    let sum_of_squares = x * x + y * y;
    let longest_square = z * z;

    // Use a relative tolerance because the inputs are floating-point values.
    let tolerance =
        8.0 * (f32::EPSILON as f64) * sum_of_squares.max(longest_square);

    (sum_of_squares - longest_square).abs() <= tolerance
}
