```rust
pub fn do_algebra(operato: Vec<&str>, operand: Vec<i32>) -> i32 {
    fn floor_div(a: i32, b: i32) -> i32 {
        assert!(b != 0, "division by zero");

        let quotient = a / b;
        let remainder = a % b;

        // Rust truncates toward zero, so adjust when mathematical floor
        // division must round toward negative infinity.
        if remainder != 0 && ((a < 0) != (b < 0)) {
            quotient - 1
        } else {
            quotient
        }
    }

    fn parse_operand(operands: &[i32], operand_pos: &mut usize) -> i32 {
        let value = operands[*operand_pos];
        *operand_pos += 1;
        value
    }

    // Exponentiation is right-associative: 2 ** 3 ** 2 = 2 ** (3 ** 2).
    fn parse_power(
        operators: &[&str],
        operands: &[i32],
        operator_pos: &mut usize,
        operand_pos: &mut usize,
    ) -> i32 {
        let base = parse_operand(operands, operand_pos);

        if *operator_pos < operators.len() && operators[*operator_pos] == "**" {
            *operator_pos += 1;
            let exponent =
                parse_power(operators, operands, operator_pos, operand_pos);

            assert!(exponent >= 0, "negative integer exponent");
            base.pow(exponent as u32)
        } else {
            base
        }
    }

    fn parse_product(
        operators: &[&str],
        operands: &[i32],
        operator_pos: &mut usize,
        operand_pos: &mut usize,
    ) -> i32 {
        let mut result =
            parse_power(operators, operands, operator_pos, operand_pos);

        while *operator_pos < operators.len() {
            match operators[*operator_pos] {
                "*" => {
                    *operator_pos += 1;
                    result *=
                        parse_power(operators, operands, operator_pos, operand_pos);
                }
                "//" => {
                    *operator_pos += 1;
                    let divisor =
                        parse_power(operators, operands, operator_pos, operand_pos);
                    result = floor_div(result, divisor);
                }
                _ => break,
            }
        }

        result
    }

    fn parse_expression(
        operators: &[&str],
        operands: &[i32],
        operator_pos: &mut usize,
        operand_pos: &mut usize,
    ) -> i32 {
        let mut result =
            parse_product(operators, operands, operator_pos, operand_pos);

        while *operator_pos < operators.len() {
            match operators[*operator_pos] {
                "+" => {
                    *operator_pos += 1;
                    result +=
                        parse_product(operators, operands, operator_pos, operand_pos);
                }
                "-" => {
                    *operator_pos += 1;
                    result -=
                        parse_product(operators, operands, operator_pos, operand_pos);
                }
                _ => panic!("invalid operator: {}", operators[*operator_pos]),
            }
        }

        result
    }

    assert_eq!(
        operand.len(),
        operato.len() + 1,
        "there must be exactly one more operand than operators"
    );

    let mut operator_pos = 0;
    let mut operand_pos = 0;
    let result = parse_expression(
        &operato,
        &operand,
        &mut operator_pos,
        &mut operand_pos,
    );

    assert_eq!(operator_pos, operato.len());
    assert_eq!(operand_pos, operand.len());

    result
}
```

This applies standard precedence: `**`, then `*`/`//`, then `+`/`-`; exponentiation is right-associative.

