import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        Objects.requireNonNull(numbers, "numbers must not be null");

        if (numbers.size() < 2) {
            throw new IllegalArgumentException(
                "numbers must contain at least two elements"
            );
        }

        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        int bestIndex = 0;
        double smallestDifference = sorted.get(1) - sorted.get(0);

        for (int i = 2; i < sorted.size(); i++) {
            double difference = sorted.get(i) - sorted.get(i - 1);

            if (difference < smallestDifference) {
                smallestDifference = difference;
                bestIndex = i - 1;
            }
        }

        return Arrays.asList(sorted.get(bestIndex), sorted.get(bestIndex + 1));
    }
}
```

