import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        Objects.requireNonNull(numbers, "numbers must not be null");

        if (numbers.size() < 2) {
            throw new IllegalArgumentException("At least two numbers are required");
        }

        double min = Double.POSITIVE_INFINITY;
        double max = Double.NEGATIVE_INFINITY;

        for (Double number : numbers) {
            if (number == null || !Double.isFinite(number)) {
                throw new IllegalArgumentException(
                    "All numbers must be non-null and finite"
                );
            }
            min = Math.min(min, number);
            max = Math.max(max, number);
        }

        if (Double.compare(min, max) == 0) {
            throw new IllegalArgumentException(
                "Cannot rescale when all numbers are equal"
            );
        }

        double range = max - min;
        List<Double> result = new ArrayList<>(numbers.size());

        for (double number : numbers) {
            result.add((number - min) / range);
        }

        return result;
    }
}
```

The transform applied to every element is `(number - min) / (max - min)`.

