public int modp(int n, int p) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (p <= 0) {
        throw new IllegalArgumentException("p must be positive");
    }

    long result = 1 % p;
    long base = 2 % p;
    int exponent = n;

    while (exponent > 0) {
        if ((exponent & 1) != 0) {
            result = (result * base) % p;
        }
        base = (base * base) % p;
        exponent >>>= 1;
    }

    return (int) result;
}
