        ListIterator<Integer> left = arr.listIterator();
        ListIterator<Integer> right = arr.listIterator(arr.size());

        for (int i = 0; i < arr.size() / 2; i++) {
            if (!Objects.equals(left.next(), right.previous())) {
                changes++;
            }
        }

        return changes;
