public boolean isMultiplyPrime(int a) {
    if (a < 2) {
        return false;
    }

    int factorCount = 0;
    int n = a;

    for (int divisor = 2; divisor * divisor <= n; divisor++) {
        while (n % divisor == 0) {
            n /= divisor;
            factorCount++;

            if (factorCount > 3) {
                return false;
            }
        }
    }

    // Any remainder greater than 1 is itself a prime factor.
    if (n > 1) {
        factorCount++;
    }

    return factorCount == 3;
}
