public int isBored(String S) {
    if (S == null || S.isEmpty()) {
        return 0;
    }

    int count = 0;
    int sentenceStart = 0;

    for (int end = 0; end <= S.length(); end++) {
        boolean sentenceEnd = end == S.length()
                || S.charAt(end) == '.'
                || S.charAt(end) == '?'
                || S.charAt(end) == '!';

        if (!sentenceEnd) {
            continue;
        }

        int pos = sentenceStart;
        while (pos < end && Character.isWhitespace(S.charAt(pos))) {
            pos++;
        }

        if (pos < end && S.charAt(pos) == 'I') {
            int next = pos + 1;

            // Ensure that "I" is a complete word, rather than part of
            // another word such as "It" or "Interesting".
            if (next == end) {
                count++;
            } else {
                int nextCodePoint = S.codePointAt(next);
                if (!Character.isLetterOrDigit(nextCodePoint)
                        && nextCodePoint != '_') {
                    count++;
                }
            }
        }

        sentenceStart = end + 1;
    }

    return count;
}
