import java.util.Map;

public class DictionaryCaseChecker {

    public boolean checkDictCase(Map<Object, Object> dict) {
        if (dict == null || dict.isEmpty()) {
            return false;
        }

        boolean allLowerCase = true;
        boolean allUpperCase = true;

        for (Object key : dict.keySet()) {
            if (!(key instanceof String)) {
                return false;
            }

            String text = (String) key;
            allLowerCase &= isLowerCase(text);
            allUpperCase &= isUpperCase(text);

            if (!allLowerCase && !allUpperCase) {
                return false;
            }
        }

        return allLowerCase || allUpperCase;
    }

    private boolean isLowerCase(String text) {
        boolean hasLowerCaseLetter = false;

        for (int i = 0; i < text.length(); ) {
            int codePoint = text.codePointAt(i);

            if (Character.isUpperCase(codePoint)
                    || Character.isTitleCase(codePoint)) {
                return false;
            }

            if (Character.isLowerCase(codePoint)) {
                hasLowerCaseLetter = true;
            }

            i += Character.charCount(codePoint);
        }

        return hasLowerCaseLetter;
    }

    private boolean isUpperCase(String text) {
        boolean hasUpperCaseLetter = false;

        for (int i = 0; i < text.length(); ) {
            int codePoint = text.codePointAt(i);

            if (Character.isLowerCase(codePoint)
                    || Character.isTitleCase(codePoint)) {
                return false;
            }

            if (Character.isUpperCase(codePoint)) {
                hasUpperCaseLetter = true;
            }

            i += Character.charCount(codePoint);
        }

        return hasUpperCaseLetter;
    }
}
