import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class PrimeCounter {

    public List<Integer> countUpTo(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        if (n <= 2) {
            return new ArrayList<>();
        }

        boolean[] isPrime = new boolean[n];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;

        for (int prime = 2; (long) prime * prime < n; prime++) {
            if (isPrime[prime]) {
                for (long multiple = (long) prime * prime;
                     multiple < n;
                     multiple += prime) {
                    isPrime[(int) multiple] = false;
                }
            }
        }

        List<Integer> primes = new ArrayList<>();
        for (int number = 2; number < n; number++) {
            if (isPrime[number]) {
                primes.add(number);
            }
        }

        return primes;
    }
}
```

Final answer: The function returns all prime integers strictly less than `n`.

