import java.util.Set;

public class Solution {
    public List<Object> reverseDelete(String s, String c) {
        Set<Character> charactersToDelete = new HashSet<>();
        for (char ch : c.toCharArray()) {
            charactersToDelete.add(ch);
        }

        StringBuilder filtered = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (!charactersToDelete.contains(ch)) {
                filtered.append(ch);
            }
        }

        String result = filtered.toString();
        boolean isPalindrome = true;

        for (int left = 0, right = result.length() - 1; left < right; left++, right--) {
            if (result.charAt(left) != result.charAt(right)) {
                isPalindrome = false;
                break;
            }
        }

        return Arrays.<Object>asList(result, isPalindrome);
    }
}
