public class Collatz {
    public List<Integer> getOddCollatz(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        List<Integer> oddNumbers = new ArrayList<>();
        long current = n; // Prevent overflow in 3 * current + 1.

        while (true) {
            if ((current & 1L) != 0) {
                // The requested return type cannot represent values outside int range.
                oddNumbers.add(Math.toIntExact(current));
            }

            if (current == 1) {
                break;
            }

            if ((current & 1L) == 0) {
                current /= 2;
            } else {
                current = Math.addExact(Math.multiplyExact(3L, current), 1L);
            }
        }

        Collections.sort(oddNumbers);
        return oddNumbers;
    }
}
