import java.util.List;

public class Solution {
    public String intersection(List<Integer> interval1,
                               List<Integer> interval2) {
        long intersectionStart = Math.max(
                (long) interval1.get(0),
                (long) interval2.get(0)
        );
        long intersectionEnd = Math.min(
                (long) interval1.get(1),
                (long) interval2.get(1)
        );

        // No intersection, or the intervals only touch at one point.
        if (intersectionEnd <= intersectionStart) {
            return "NO";
        }

        long length = intersectionEnd - intersectionStart;
        return isPrime(length) ? "YES" : "NO";
    }

    private boolean isPrime(long number) {
        if (number < 2) {
            return false;
        }
        if (number % 2 == 0) {
            return number == 2;
        }
        if (number % 3 == 0) {
            return number == 3;
        }

        for (long divisor = 5; divisor <= number / divisor; divisor += 6) {
            if (number % divisor == 0 || number % (divisor + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}
