            return Optional.empty();
        }

        long magnitudeSum = 0;
        int sign = 1;

        for (int value : arr) {
            if (value == 0) {
                return Optional.of(0);
            }

            magnitudeSum += Math.abs((long) value);
            if (value < 0) {
