import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.Optional;

public class Solution {

    public Optional<Object> compareOne(Object a, Object b) {
        BigDecimal first = toBigDecimal(a);
        BigDecimal second = toBigDecimal(b);

        int comparison = first.compareTo(second);
        if (comparison == 0) {
            return Optional.empty();
        }

        // Return the original object, preserving its variable type.
        return Optional.of(comparison > 0 ? a : b);
    }

    private BigDecimal toBigDecimal(Object value) {
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }

        if (value instanceof BigDecimal decimal) {
            return decimal;
        }

        if (value instanceof BigInteger integer) {
            return new BigDecimal(integer);
        }

        if (value instanceof Byte
                || value instanceof Short
                || value instanceof Integer
                || value instanceof Long) {
            return BigDecimal.valueOf(((Number) value).longValue());
        }

        if (value instanceof Float || value instanceof Double) {
            double number = ((Number) value).doubleValue();
            if (!Double.isFinite(number)) {
                throw new IllegalArgumentException("Value must be a real number");
            }
            return new BigDecimal(value.toString());
        }

        if (value instanceof String text) {
            String normalized = text.trim().replace(',', '.');
            try {
                return new BigDecimal(normalized);
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException(
                        "Invalid real-number string: " + text, e);
            }
        }

        throw new IllegalArgumentException(
                "Expected an integer, floating-point number, or numeric string");
    }
}
