        // The filename must start with a Latin letter.
        char first = file_name.charAt(0);
        if (!((first >= 'a' && first <= 'z') ||
              (first >= 'A' && first <= 'Z'))) {
            return "No";
        }

        // There must not be more than three digits.
        int digitCount = 0;
        for (int i = 0; i < file_name.length(); i++) {
            char c = file_name.charAt(i);
            if (c >= '0' && c <= '9' && ++digitCount > 3) {
                return "No";
            }
        }

        // Check the extension.
        String extension = file_name.substring(dotIndex + 1);
        if (!extension.equals("txt") &&
            !extension.equals("exe") &&
            !extension.equals("dll")) {
            return "No";
        }

        return "Yes";
