import java.math.BigInteger;

public class Solution {
    public boolean simplify(String x, String n) {
        BigInteger[] first = parseFraction(x);
        BigInteger[] second = parseFraction(n);

        BigInteger numerator = first[0].multiply(second[0]);
        BigInteger denominator = first[1].multiply(second[1]);

        return numerator.mod(denominator).equals(BigInteger.ZERO);
    }

    private BigInteger[] parseFraction(String fraction) {
        int slash = fraction.indexOf('/');
        return new BigInteger[] {
            new BigInteger(fraction.substring(0, slash)),
            new BigInteger(fraction.substring(slash + 1))
        };
    }
}
