import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        List<Integer> result = new ArrayList<>(nums);

        // List.sort is stable, so equal scores retain their original order.
        result.sort((a, b) -> Integer.compare(digitSum(a), digitSum(b)));

        return result;
    }

    private int digitSum(int number) {
        String value = Integer.toString(number);
        boolean negative = value.charAt(0) == '-';
        int start = negative ? 1 : 0;
        int sum = 0;

        for (int i = start; i < value.length(); i++) {
            int digit = value.charAt(i) - '0';

            // For a negative number, the leading digit is negative.
            if (negative && i == start) {
                sum -= digit;
            } else {
                sum += digit;
            }
        }

        return sum;
    }
}
