    public List<String> bf(String planet1, String planet2) {
        List<String> planets = Arrays.asList(
            "Mercury", "Venus", "Earth", "Mars",
            "Jupiter", "Saturn", "Uranus", "Neptune"
        );

        int first = planets.indexOf(planet1);
        int second = planets.indexOf(planet2);

        if (first == -1 || second == -1) {
            return new ArrayList<>();
        }

        int from = Math.min(first, second) + 1;
        int to = Math.max(first, second);

        return new ArrayList<>(planets.subList(from, to));
    }
}
