public int xOrY(int n, int x, int y) {
    if (n < 2) {
        return y;
    }

    if (n == 2) {
        return x;
    }

    if (n % 2 == 0) {
        return y;
    }

    for (int divisor = 3; divisor <= n / divisor; divisor += 2) {
        if (n % divisor == 0) {
            return y;
        }
    }

    return x;
}
