public boolean cycpatternCheck(String a, String b) {
    if (a == null || b == null) {
        return false;
    }

    int length = b.length();

    // The empty string is a substring of every string.
    if (length == 0) {
        return true;
    }

    if (length > a.length()) {
        return false;
    }

    // Every rotation of b occurs as a length-|b| substring of b + b.
    String doubled = b + b;

    for (int i = 0; i <= a.length() - length; i++) {
        String candidate = a.substring(i, i + length);
        if (doubled.contains(candidate)) {
            return true;
        }
    }

    return false;
}
