    public List<Integer> evenOddCount(int num) {
        long value = Math.abs((long) num);
        int evenCount = 0;
        int oddCount = 0;

        do {
            int digit = (int) (value % 10);

            if (digit % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }

            value /= 10;
        } while (value > 0);

        return Arrays.asList(evenCount, oddCount);
