        int maxUnique = -1;

        for (String word : words) {
            Set<Character> unique = new HashSet<>();
            for (char c : word.toCharArray()) {
                unique.add(c);
            }

            int count = unique.size();
            if (count > maxUnique ||
                (count == maxUnique && word.compareTo(best) < 0)) {
                maxUnique = count;
                best = word;
