```java
import java.util.List;

public class Solution {

    public int doAlgebra(List<String> operator, List<Integer> operand) {
        if (operator == null || operand == null
                || operator.size() < 1
                || operand.size() != operator.size() + 1) {
            throw new IllegalArgumentException("Invalid operator or operand list");
        }

        Parser parser = new Parser(operator, operand);
        int result = parser.parseExpression();

        if (!parser.isAtEnd()) {
            throw new IllegalArgumentException("Invalid algebraic expression");
        }

        return result;
    }

    private static class Parser {
        private final List<String> operators;
        private final List<Integer> operands;
        private int operatorIndex;
        private int operandIndex;

        Parser(List<String> operators, List<Integer> operands) {
            this.operators = operators;
            this.operands = operands;
        }

        // Handles + and -
        int parseExpression() {
            int value = parseTerm();

            while (hasOperator("+") || hasOperator("-")) {
                String op = operators.get(operatorIndex++);
                int right = parseTerm();

                if (op.equals("+")) {
                    value += right;
                } else {
                    value -= right;
                }
            }

            return value;
        }

        // Handles * and /
        private int parseTerm() {
            int value = parsePower();

            while (hasOperator("*") || hasOperator("/")) {
                String op = operators.get(operatorIndex++);
                int right = parsePower();

                if (op.equals("*")) {
                    value *= right;
                } else {
                    // Math.floorDiv performs floor division, including for
                    // negative intermediate values.
                    value = Math.floorDiv(value, right);
                }
            }

            return value;
        }

        // Handles right-associative exponentiation:
        // 2 ** 3 ** 2 is evaluated as 2 ** (3 ** 2).
        private int parsePower() {
            int start = operandIndex++;
            int end = start;

            while (hasOperator("**")) {
                operatorIndex++;
                end = operandIndex++;
            }

            int value = getOperand(end);
            for (int i = end - 1; i >= start; i--) {
                value = integerPower(getOperand(i), value);
            }

            return value;
        }

        private int getOperand(int index) {
            Integer value = operands.get(index);
            if (value == null || value < 0) {
                throw new IllegalArgumentException(
                        "Operands must be non-negative integers");
            }
            return value;
        }

        private boolean hasOperator(String expected) {
            return operatorIndex < operators.size()
                    && expected.equals(operators.get(operatorIndex));
        }

        boolean isAtEnd() {
            return operatorIndex == operators.size()
                    && operandIndex == operands.size();
        }

        private static int integerPower(int base, int exponent) {
            if (exponent < 0) {
                throw new ArithmeticException("Negative exponent");
            }

            int result = 1;
            int factor = base;
            int power = exponent;

            while (power > 0) {
                if ((power & 1) != 0) {
                    result *= factor;
                }

                power >>>= 1;
                if (power != 0) {
                    factor *= factor;
                }
            }

            return result;
        }
    }
}
```

This applies standard precedence: `**`, then `*` and `/`, then `+` and `-`. Exponentiation is right-associative, and division uses mathematical floor division.

