import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Optional;

public class Md5Util {

    public Optional<String> stringToMd5(String text)
            throws NoSuchAlgorithmException {
        if (text == null || text.isEmpty()) {
            return Optional.empty();
        }

        MessageDigest md5 = MessageDigest.getInstance("MD5");
        byte[] digest = md5.digest(text.getBytes(StandardCharsets.UTF_8));

        StringBuilder hash = new StringBuilder(32);
        for (byte value : digest) {
            int unsigned = value & 0xff;
            hash.append(Character.forDigit(unsigned >>> 4, 16));
            hash.append(Character.forDigit(unsigned & 0x0f, 16));
        }

        return Optional.of(hash.toString());
    }
}
