import java.util.ArrayList;
import java.util.List;

public List<Integer> generateIntegers(int a, int b) {
    int lower = Math.min(a, b);
    int upper = Math.max(a, b);

    List<Integer> result = new ArrayList<>();

    // Even decimal digits are 0, 2, 4, 6, and 8.
    // Since a and b are positive, only 2, 4, 6, and 8 can be in range.
    for (int digit = 2; digit <= 8; digit += 2) {
        if (digit >= lower && digit <= upper) {
            result.add(digit);
        }
    }

    return result;
}
