```csharp
using System.ComponentModel.DataAnnotations;
using FormSqlApp.Data;
using FormSqlApp.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

namespace FormSqlApp.Pages;

public sealed class IndexModel : PageModel
{
    private readonly AppDbContext _database;

    public IndexModel(AppDbContext database)
    {
        _database = database;
    }

    [BindProperty]
    public ContactInput Input { get; set; } = new();

    [TempData]
    public string? StatusMessage { get; set; }

    public void OnGet()
    {
    }

    public async Task<IActionResult> OnPostAsync()
    {
        if (!ModelState.IsValid)
        {
            return Page();
        }

        var submission = new ContactSubmission
        {
            Name = Input.Name.Trim(),
            Email = Input.Email.Trim(),
            Message = Input.Message.Trim(),
            CreatedUtc = DateTime.UtcNow
        };

        _database.ContactSubmissions.Add(submission);
        await _database.SaveChangesAsync();

        StatusMessage = "Your form was submitted successfully.";

        // Redirecting prevents duplicate submissions when the page is refreshed.
        return RedirectToPage();
    }

    public sealed class ContactInput
    {
        [Required]
        [StringLength(100)]
        public string Name { get; set; } = string.Empty;

        [Required]
        [EmailAddress]
        [StringLength(255)]
        public string Email { get; set; } = string.Empty;

        [Required]
        [StringLength(2000, MinimumLength = 5)]
        public string Message { get; set; } = string.Empty;
    }
}
