```javascript
/**
 * Counts Friday-the-13th occurrences between two calendar years, inclusive.
 * Uses the proleptic Gregorian calendar.
 *
 * @param {number} startYear - First year in the span.
 * @param {number} endYear   - Last year in the span.
 * @returns {number} Total number of Friday-the-13ths.
 */
function countFridayThe13ths(startYear, endYear) {
    if (!Number.isSafeInteger(startYear) || !Number.isSafeInteger(endYear)) {
        throw new TypeError("Years must be safe integers.");
    }
    if (startYear < 1 || endYear < startYear) {
        throw new RangeError("Specify a valid inclusive year range.");
    }

    // Month offsets for the Gregorian day-of-week calculation.
    const offsets = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
    let count = 0;

    for (let year = startYear; year <= endYear; year++) {
        for (let month = 1; month <= 12; month++) {
            let adjustedYear = year;
            if (month < 3) adjustedYear--;

            // 0 = Sunday, 1 = Monday, ..., 5 = Friday.
            const weekday =
                (adjustedYear +
                    Math.floor(adjustedYear / 4) -
                    Math.floor(adjustedYear / 100) +
                    Math.floor(adjustedYear / 400) +
                    offsets[month - 1] +
                    13) % 7;

            if (weekday === 5) count++;
        }
    }

    return count;
}

// Example:
console.log(countFridayThe13ths(2000, 2025)); // 45
```

Final answer: `countFridayThe13ths(startYear, endYear)` returns the total number of Friday-the-13ths in the inclusive year span.

