function removeAdjacentDuplicatesAndMultiples(arr) {
  return arr.filter((current, index) => {
    if (index === 0) return true;

    const previous = arr[index - 1];
    const isDuplicate = current === previous;
    const isMultiple = previous !== 0 && current % previous === 0;

