### Approach: Weighted Graph + DFS

Treat each equation `A / B = v` as two directed graph edges:

- `A -> B` with weight `v`
- `B -> A` with weight `1 / v`

For each query `C / D`, search for a path from `C` to `D`. The product of the edge weights along that path is the answer. If either variable is unknown or no path exists, return `-1.0`.

```python
from collections import defaultdict
from typing import List


class Solution:
    def calcEquation(
        self,
        equations: List[List[str]],
        values: List[float],
        queries: List[List[str]]
    ) -> List[float]:
        graph = defaultdict(list)

        for (numerator, denominator), value in zip(equations, values):
            graph[numerator].append((denominator, value))
            graph[denominator].append((numerator, 1.0 / value))

        def evaluate(source: str, target: str) -> float:
            if source not in graph or target not in graph:
                return -1.0

            if source == target:
                return 1.0

            visited = {source}
            stack = [(source, 1.0)]

            while stack:
                variable, product = stack.pop()

                if variable == target:
                    return product

                for neighbor, weight in graph[variable]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append((neighbor, product * weight))

            return -1.0

        return [evaluate(source, target) for source, target in queries]
```

For each query, the search takes `O(V + E)` time. The graph uses `O(V + E)` space.

This version uses `math/big.Int` for arbitrary precision, memoizes results across calls, and computes iteratively to avoid stack overflow. It also implements the documented negative-index recurrence; the original Python code’s `n <= 1` condition makes its negative branch unreachable.

```go
package fibfib

import (
	"math/big"
	"sync"
)

var (
	mu sync.Mutex

	memo = map[int64]*big.Int{
		0: big.NewInt(0),
		1: big.NewInt(0),
		2: big.NewInt(1),
	}

	maxComputed int64 = 2
	minComputed int64 = 0
)

// FibFib returns the nth FibFib number.
//
//	FibFib(0) = 0
//	FibFib(1) = 0
//	FibFib(2) = 1
//
// For n > 2:
//
//	FibFib(n) = FibFib(n-1) + FibFib(n-2) + FibFib(n-3)
//
// For n < 0:
//
//	FibFib(n) = FibFib(n+3) - FibFib(n+2) - FibFib(n+1)
//
// The returned *big.Int is an independent copy and may be modified safely
// by the caller.
func FibFib(n int64) *big.Int {
	mu.Lock()
	defer mu.Unlock()

	if value, ok := memo[n]; ok {
		return new(big.Int).Set(value)
	}

	if n > maxComputed {
		for i := maxComputed + 1; ; i++ {
			result := new(big.Int).Add(memo[i-1], memo[i-2])
			result.Add(result, memo[i-3])

			memo[i] = result

			if i == n {
				break
			}
		}
		maxComputed = n
	} else if n < minComputed {
		for i := minComputed - 1; ; i-- {
			result := new(big.Int).Sub(memo[i+3], memo[i+2])
			result.Sub(result, memo[i+1])

			memo[i] = result

			if i == n {
				break
			}
		}
		minComputed = n
	}

	return new(big.Int).Set(memo[n])
}
```

