#include <iostream>
#include <vector>
#include <utility>

void bubbleSort(std::vector<double>& numbers) {
    for (std::size_t n = numbers.size(); n > 1; --n) {
        bool swapped = false;

        for (std::size_t i = 0; i < n - 1; ++i) {
            if (numbers[i] > numbers[i + 1]) {
                std::swap(numbers[i], numbers[i + 1]);
                swapped = true;
            }
        }

        // The list is already sorted if no swaps occurred.
        if (!swapped) {
            break;
        }
    }
}

int main() {
    std::vector<double> numbers = {5, 2, -3, 8.5, 9, 7, 2, -3.5};

    bubbleSort(numbers);

    std::cout << "Sorted list: ";
    for (double number : numbers) {
        std::cout << number << ' ';
    }
    std::cout << '\n';

    return 0;
}
