ground_truth:
```swift
func median<T>(
    _ list: [T],
    cmpFunc: (T, T) -> Int
) -> T where T: Collection & Equatable {
    precondition(!list.isEmpty, "Cannot find the median of an empty array")

    func selectPivot(_ a: T, _ b: T, _ c: T) -> T {
        // Include the original position to preserve ordering when counts are equal.
        let candidates = [a, b, c].enumerated().sorted {
            if $0.element.count == $1.element.count {
                return $0.offset < $1.offset
            }
            return $0.element.count < $1.element.count
        }

        return candidates[1].element
    }

    func partition(_ values: inout [T], low: Int, high: Int) -> Int {
        let pivot = selectPivot(
            values[low],
            values[(low + high) / 2],
            values[high]
        )

        let pivotIndex = values.firstIndex(of: pivot)!
        values.swapAt(low, pivotIndex)

        var i = low + 1
        var j = high

        while true {
            while i < high && cmpFunc(values[i], pivot) <= 0 {
                i += 1
            }

            while j > low && cmpFunc(values[j], pivot) >= 0 {
                j -= 1
            }

            if i >= j {
                break
            }

            values.swapAt(i, j)
        }

        values.swapAt(low, j)
        return j
    }

    func selectMedian(_ input: [T], position: Int) -> T {
        if input.count == 1 {
            return input[0]
        }

        var values = input
        let pivotIndex = partition(
            &values,
            low: 0,
            high: values.count - 1
        )

        if position < pivotIndex {
            return selectMedian(
                Array(values[..<pivotIndex]),
                position: position
            )
        } else if position > pivotIndex {
            return selectMedian(
                Array(values[(pivotIndex + 1)...]),
                position: position - pivotIndex - 1
            )
        } else {
            return values[pivotIndex]
        }
    }

    return selectMedian(list, position: list.count / 2)
}
```

