        {
            throw new ArgumentException(
                $"Items of type '{item.GetType().FullName}' cannot be added. " +
                $"This collection currently stores items of type '{_itemType.FullName}'.",
                nameof(item));
        }

        _data.Add(item);
    }

    public void Remove(object item)
    {
        ValidateNotNullAndComparable(item);

        if (_itemType != null && item.GetType() != _itemType)
        {
            throw new ArgumentException(
                $"An item of type '{item.GetType().FullName}' cannot be removed from " +
                $"a collection containing '{_itemType.FullName}' values.",
                nameof(item));
        }

        if (!_data.Remove(item))
        {
            throw new KeyNotFoundException("The specified item was not found.");
        }

        // Allow the collection to be reused with another comparable type once empty.
        if (_data.Count == 0)
        {
            _itemType = null;
        }
    }

    public List<object> GetData()
    {
        // Sort a copy so callers cannot modify the class's internal list.
        var sortedData = new List<object>(_data);

        InsertionSort(sortedData);

        return sortedData;
    }

    /// <summary>
    /// Custom stable insertion-sort implementation.
    /// </summary>
    private static void InsertionSort(List<object> items)
    {
        for (int i = 1; i < items.Count; i++)
        {
            object current = items[i];
            int j = i - 1;

            while (j >= 0 && Compare(items[j], current) > 0)
            {
                items[j + 1] = items[j];
                j--;
            }

            items[j + 1] = current;
        }
    }

    private static int Compare(object left, object right)
    {
        try
        {
            return ((IComparable)left).CompareTo(right);
        }
        catch (Exception ex) when (
            ex is ArgumentException ||
            ex is InvalidCastException ||
            ex is InvalidOperationException)
        {
            throw new InvalidOperationException(
                $"Values of type '{left.GetType().FullName}' could not be compared.",
                ex);
        }
    }

    private static void ValidateNotNullAndComparable(object item)
    {
        if (item == null)
        {
            throw new ArgumentNullException(nameof(item), "Null items are not supported.");
        }

        if (!(item is IComparable))
        {
            throw new ArgumentException(
                $"Items must implement {nameof(IComparable)} in order to be sorted.",
                nameof(item));
        }
    }
}
```

This implementation uses a custom stable insertion sort rather than `List<T>.Sort`. It rejects `null`, non-comparable objects, and mixed runtime types, and `GetData` returns a sorted copy rather than exposing the internal collection.

