```php
<?php

function future_flight(mixed $q, mixed $w): bool|string
{
    // PHP arrays are the equivalent sequence type here.
    if (!is_array($q)) {
        return "Non-sequence input";
    }

    // Ensure every item is an integer or float.
    foreach ($q as $item) {
        if (!is_int($item) && !is_float($item)) {
            return "Non-numeric input";
        }
    }

    // Normalize keys so the array behaves like a Python list.
    $q = array_values($q);

    $ascending = $q;
    sort($ascending, SORT_NUMERIC);

    $descending = $q;
    rsort($descending, SORT_NUMERIC);

    if ($q != $ascending && $q != $descending) {
        return "Unsorted list error";
    }

    // Check whether the sequence is palindromic and within capacity.
    return $q == array_reverse($q) && array_sum($q) <= $w;
}
```

This version requires PHP 8.0 or newer because it uses the `mixed` and union return types.

