```

NOTE: For the purpose of this exercise, disregard the case of the letters (all are considered lowercase) and do not consider spaces or punctuation.

ground_truth:
The result includes:

- `frequencies`: count for each normalized character.
- `mostFrequent`: all characters tied for the highest count.
- `leastFrequent`: all characters tied for the lowest count.
- `null` for most/least when no letters are present.

### `countCharsAndFrequency.js`

```javascript
function countCharsAndFrequency(str) {
  if (typeof str !== "string") {
    throw new TypeError("Expected a string");
  }

  const frequencies = {};

  for (const char of str.toLowerCase()) {
    // Ignore spaces, punctuation, digits, and other non-letter characters.
    if (!/\p{L}/u.test(char)) {
      continue;
    }

    frequencies[char] = (frequencies[char] ?? 0) + 1;
  }

  const entries = Object.entries(frequencies);

  if (entries.length === 0) {
    return {
      frequencies,
      mostFrequent: null,
      leastFrequent: null,
    };
  }

  const counts = entries.map(([, count]) => count);
  const highestCount = Math.max(...counts);
  const lowestCount = Math.min(...counts);

  return {
    frequencies,
    mostFrequent: {
      characters: entries
        .filter(([, count]) => count === highestCount)
        .map(([char]) => char),
      frequency: highestCount,
    },
    leastFrequent: {
      characters: entries
        .filter(([, count]) => count === lowestCount)
        .map(([char]) => char),
      frequency: lowestCount,
    },
  };
}

module.exports = countCharsAndFrequency;
```

