import java.util.Arrays;

public class PrimeNumbers {

    public static int[] primesUpTo(int number) {
        if (number < 2) {
            return new int[0];
        }

        boolean[] isPrime = new boolean[number + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = false;
        isPrime[1] = false;

        // Sieve of Eratosthenes
        for (int candidate = 2; candidate <= number / candidate; candidate++) {
            if (isPrime[candidate]) {
                for (int multiple = candidate * candidate;
                     multiple <= number;
                     multiple += candidate) {
                    isPrime[multiple] = false;
                }
            }
        }

        int primeCount = 0;
        for (boolean prime : isPrime) {
            if (prime) {
                primeCount++;
            }
        }

        int[] primes = new int[primeCount];
        int index = 0;

        for (int value = 2; value <= number; value++) {
            if (isPrime[value]) {
                primes[index++] = value;
            }
        }

        return primes;
    }

    public static void main(String[] args) {
        int number = 10;
        System.out.println(Arrays.toString(primesUpTo(number)));
    }
}
