#include <stdexcept>
#include <string>
#include <unordered_map>
#include <variant>
#include <vector>

using Number = std::variant<int, std::string>;

Number convert_number(Number number, const std::string& conversion_type)
{
    const std::unordered_map<char, int> roman_to_int_mapping = {
        {'i', 1},
        {'v', 5},
        {'x', 10},
        {'l', 50},
        {'c', 100},
        {'d', 500},
        {'m', 1000}
    };

    const std::unordered_map<int, std::string> int_to_roman_mapping = {
        {1, "i"},
        {4, "iv"},
        {5, "v"},
        {9, "ix"},
        {10, "x"},
        {40, "xl"},
        {50, "l"},
        {90, "xc"},
        {100, "c"},
        {400, "cd"},
        {500, "d"},
        {900, "cm"},
        {1000, "m"}
    };

    if (conversion_type == "int_to_roman") {
        if (!std::holds_alternative<int>(number)) {
            throw std::invalid_argument(
                "Invalid value. Should be an integer between 1 and 1000."
            );
        }

        int value = std::get<int>(number);

        if (value < 1 || value > 1000) {
            throw std::invalid_argument(
                "Invalid value. Should be an integer between 1 and 1000."
            );
        }

        const std::vector<int> values = {
            1000, 900, 500, 400, 100, 90, 50,
            40, 10, 9, 5, 4, 1
        };

        std::string result;

        for (int current : values) {
            while (value >= current) {
                result += int_to_roman_mapping.at(current);
                value -= current;
            }
        }

        return result;
    }
    else if (conversion_type == "roman_to_int") {
        if (!std::holds_alternative<std::string>(number)) {
            throw std::invalid_argument(
                "Invalid value. Should be a valid Roman numeral."
            );
        }

        std::string value = std::get<std::string>(number);

        std::transform(
            value.begin(),
            value.end(),
            value.begin(),
            [](unsigned char character) {
                return static_cast<char>(std::tolower(character));
            }
        );

        int result = 0;
        std::size_t i = 0;

        while (i < value.size()) {
            bool valid_pair = false;

            if (i + 1 < value.size()) {
                const std::string pair = value.substr(i, 2);

                for (const auto& [integer, roman] : int_to_roman_mapping) {
                    if (roman == pair) {
                        valid_pair = true;
                        break;
                    }
                }

                if (valid_pair) {
                    result += roman_to_int_mapping.at(value[i + 1])
                            - roman_to_int_mapping.at(value[i]);
                    i += 2;
                    continue;
                }
            }

            const auto entry = roman_to_int_mapping.find(value[i]);

            // Matches Python's mapping.get(number[i], 0).
            if (entry != roman_to_int_mapping.end()) {
                result += entry->second;
            }

            ++i;
        }

        return result;
    }

    throw std::invalid_argument(
        "Invalid conversion type. Should be \"int_to_roman\" or "
        "\"roman_to_int\"."
    );
}
