ground_truth:
A failed transaction should not be deducted. Compute the prospective balance first and return immediately if it would be negative. The index is zero-based.

```javascript
function calculateBalance(balance, transactions) {
  let remainingBalance = balance;

  for (let i = 0; i < transactions.length; i++) {
    const nextBalance = remainingBalance - transactions[i];

    if (nextBalance < 0) {
      return {
        remainingBalance,
        failedTransactionIndex: i
      };
    }

    remainingBalance = nextBalance;
  }

  return {
    remainingBalance,
    failedTransactionIndex: null
  };
}
