"""Maze representation and rendering for the CLI Pacman game."""

from typing import List


class Maze:
    """Represent a rectangular, navigable Pacman maze."""

    def __init__(self, width: int = 40, height: int = 20) -> None:
        """Initialize a maze with outer walls and internal corridors."""
        self._validate_dimensions(width, height)

        self.width: int = width
        self.height: int = height
        self.maze: List[List[str]] = self._create_maze()

    @staticmethod
    def _validate_dimensions(width: int, height: int) -> None:
        """Validate that the dimensions can contain a playable area."""
        if (
            isinstance(width, bool)
            or isinstance(height, bool)
            or not isinstance(width, int)
            or not isinstance(height, int)
        ):
            raise TypeError("Maze width and height must be integers.")

        if width < 3 or height < 3:
            raise ValueError(
                "Maze width and height must each be at least 3."
            )

    def _create_maze(self) -> List[List[str]]:
        """Create a connected maze with a solid outer boundary."""
        maze: List[List[str]] = [
            [" " for _ in range(self.width)]
            for _ in range(self.height)
        ]

        for x in range(self.width):
            maze[0][x] = "#"
            maze[self.height - 1][x] = "#"

        for y in range(self.height):
            maze[y][0] = "#"
            maze[y][self.width - 1] = "#"

        if self.width < 5 or self.height < 5:
            return maze

        wall_number: int = 0
        for y in range(2, self.height - 1, 2):
            opening_x: int = (
                self.width - 2 if wall_number % 2 == 0 else 1
            )
            for x in range(1, self.width - 1):
                if x != opening_x:
                    maze[y][x] = "#"
            wall_number += 1

        return maze

    def draw(self) -> None:
        """Draw the maze to standard output."""
        for row in self.maze:
            print("".join(row))

