#!/usr/bin/env python3

import argparse
import sys
from pathlib import Path


def list_txt_files(directory: str) -> list[Path]:
    """Return all .txt files directly contained in the specified directory."""
    directory_path = Path(directory).expanduser()

    # Tier 1: Verify that the directory exists and is a directory.
    if not directory_path.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory_path}")
    if not directory_path.is_dir():
        raise NotADirectoryError(f"Path is not a directory: {directory_path}")

    # Tier 2: Retain only regular files with a .txt extension.
    return sorted(
        path
        for path in directory_path.iterdir()
        if path.is_file() and path.suffix.lower() == ".txt"
    )


def main() -> int:
    parser = argparse.ArgumentParser(
        description="List all .txt files in a specified directory."
    )
    parser.add_argument("directory", help="Directory to search")
    args = parser.parse_args()

    try:
        txt_files = list_txt_files(args.directory)
    except (FileNotFoundError, NotADirectoryError, PermissionError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1

    if not txt_files:
        print("No .txt files found.")
    else:
        for file_path in txt_files:
            print(file_path)

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
