Help me port this code over to Perl:
def max_value(md_array: list) -> int:
    """Return maximum value of elements in the multidimensional array md_array without reordering it.
    Handles arrays with a mix of positive and negative integers.
    """
    # Base case: If the array is empty, return negative infinity
    if not md_array:
        return float('-inf')

    if isinstance(md_array, list):
        return max(max_value(e) for e in md_array)
    else:
        return md_array

print(max_value([[3, -1, 2, 4, 5], [6, -2, 7]]))  # Output: 7
print(max_value([[-10, 4, 6, -1000], [10, 20, -5]]))  # Output: 20

ground_truth:
```perl
use strict;
use warnings;
use POSIX qw(HUGE_VAL);

sub max_value {
    my ($value) = @_;

    # Recursively process array references.
    if (ref($value) eq 'ARRAY') {
        # An empty array has no maximum.
        return -HUGE_VAL if !@$value;

        my $maximum = -HUGE_VAL;

        for my $element (@$value) {
            my $candidate = max_value($element);
            $maximum = $candidate if $candidate > $maximum;
        }

        return $maximum;
    }

    # Base case: the value is an integer.
    return $value;
}

print max_value([[3, -1, 2, 4, 5], [6, -2, 7]]), "\n";          # 7
print max_value([[-10, 4, 6, -1000], [10, 20, -5]]), "\n";      # 20
```

