Rust enforces string types at compile time, so `Option<&str>` is used to represent either a string or a null value (`None`).

```rust
fn normalize(input: &str) -> String {
    input
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(char::to_lowercase)
        .collect()
}

fn is_palindrome_chars(chars: &[char]) -> bool {
    chars.iter().eq(chars.iter().rev())
}

fn safe_is_palindrome(input: Option<&str>) -> bool {
    let input = match input {
        Some(value) => value,
        None => {
            println!("Input can not be null.");
            return false;
        }
    };

    let normalized = normalize(input);
    let chars: Vec<char> = normalized.chars().collect();

    is_palindrome_chars(&chars)
}

fn safe_make_palindrome(input: Option<&str>) -> Option<String> {
    let input = match input {
        Some(value) => value,
        None => {
            println!("Input can not be null.");
            return None;
        }
    };

    let normalized = normalize(input);
    let chars: Vec<char> = normalized.chars().collect();

    for i in 0..chars.len() {
        if is_palindrome_chars(&chars[i..]) {
            let ending: String = chars[..i].iter().rev().collect();
            return Some(format!("{normalized}{ending}"));
        }
    }

    None
}

fn main() {
    // Test safe_is_palindrome
    println!(
        "{}",
        safe_is_palindrome(Some("A man, a plan, a canal: Panama"))
    );

    // Test safe_make_palindrome
    match safe_make_palindrome(Some("apple")) {
        Some(result) => println!("{result}"),
        None => println!("None"),
    }
}
```

