ground_truth:
```go
package main

import (
	"fmt"
	"strings"
)

// removeVowels returns str with all uppercase and lowercase ASCII vowels removed.
func removeVowels(str string) string {
	const vowels = "aeiouAEIOU"

	var result strings.Builder
	result.Grow(len(str))

	for _, char := range str {
		if !strings.ContainsRune(vowels, char) {
			result.WriteRune(char)
		}
	}

	return result.String()
}

func main() {
	// Testing an empty string
	fmt.Printf("Output of removing vowels from empty string: %s\n",
		removeVowels(""))

	// Testing a combination of alphabets with "\n" as a delimiter
	fmt.Printf("Output of removing vowels from 'a\nb\nc\nd\ne': %s\n",
		removeVowels("a\nb\nc\nd\ne"))

	// Testing a vowel-packed string
	fmt.Printf("Output of removing vowels from 'aeiou': %s\n",
		removeVowels("aeiou"))

	// Testing a solo non-vowel character surrounded by vowels
	fmt.Printf("Output of removing vowels from 'iahi': %s\n",
		removeVowels("iahi"))

	// Testing a string devoid of vowels
	fmt.Printf("Output of removing vowels from 'bcd': %s\n",
		removeVowels("bcd"))
}
```

### Explanation

- Go strings are immutable, so characters cannot be erased in place as they are in the C++ version.
- `strings.Builder` efficiently constructs a new string.
- The loop processes each character in the input.
- `strings.ContainsRune(vowels, char)` checks whether the character is one of the uppercase or lowercase ASCII vowels.
- Non-vowel characters—including newline delimiters—are written to the result.
- `result.Grow(len(str))` preallocates enough space for the largest possible result, avoiding unnecessary allocations.
- `fmt.Printf` with `%s` corresponds to the C++ `printf` calls. Because the test strings contain `\n`, portions of their labels and results will appear on separate output lines.

