Below is a direct C# equivalent using the `Npgsql` PostgreSQL provider. Dictionary arguments replace Python’s `**kwargs`, and all values are parameterized to prevent SQL injection.

Install the PostgreSQL provider:

```bash
dotnet add package Npgsql
```

```csharp
#nullable enable

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using Npgsql;

public sealed class Database : IDisposable
{
    // Equivalent to:
    // postgresql+psycopg2://user:password@localhost:5432/mydatabase
    private const string ConnectionString =
        "Host=localhost;Port=5432;Database=mydatabase;Username=user;Password=password";

    private readonly NpgsqlConnection _connection;
    private bool _disposed;

    public Database()
    {
        _connection = new NpgsqlConnection(ConnectionString);
        _connection.Open();
    }

    public void Create(
        string tableName,
        IReadOnlyDictionary<string, object?> values)
    {
        ArgumentNullException.ThrowIfNull(values);

        ExecuteInTransaction(command =>
        {
            string quotedTable = QuoteTableName(tableName);

            if (values.Count == 0)
            {
                command.CommandText = $"INSERT INTO {quotedTable} DEFAULT VALUES;";
                command.ExecuteNonQuery();
                return;
            }

            var columns = new List<string>();
            var valueExpressions = new List<string>();
            int parameterIndex = 0;

            foreach (var item in values)
            {
                columns.Add(QuoteIdentifier(item.Key));

                if (IsDatabaseNull(item.Value))
                {
                    valueExpressions.Add("NULL");
                }
                else
                {
                    string parameterName = $"c{parameterIndex++}";
                    valueExpressions.Add($"@{parameterName}");
                    command.Parameters.AddWithValue(parameterName, item.Value!);
                }
            }

            command.CommandText =
                $"INSERT INTO {quotedTable} " +
                $"({string.Join(", ", columns)}) " +
                $"VALUES ({string.Join(", ", valueExpressions)});";

            command.ExecuteNonQuery();
        });
    }

    public void Read(
        string tableName,
        IReadOnlyDictionary<string, object?>? filters = null)
    {
        ThrowIfDisposed();

        using var command = _connection.CreateCommand();

        int parameterIndex = 0;
        string whereClause = BuildWhereClause(
            command,
            filters,
            "r",
            ref parameterIndex);

        command.CommandText =
            $"SELECT * FROM {QuoteTableName(tableName)}{whereClause};";

        using NpgsqlDataReader reader = command.ExecuteReader();

        while (reader.Read())
        {
            var values = new string[reader.FieldCount];

            for (int i = 0; i < reader.FieldCount; i++)
            {
                values[i] = reader.IsDBNull(i)
                    ? "NULL"
                    : Convert.ToString(
                        reader.GetValue(i),
                        CultureInfo.InvariantCulture) ?? string.Empty;
            }

            Console.WriteLine($"({string.Join(", ", values)})");
        }
    }

    public void Update(
        string tableName,
        IReadOnlyDictionary<string, object?> filters,
        IReadOnlyDictionary<string, object?> values)
    {
        ArgumentNullException.ThrowIfNull(filters);
        ArgumentNullException.ThrowIfNull(values);

        if (values.Count == 0)
        {
            throw new ArgumentException(
                "At least one value must be supplied for an update.",
                nameof(values));
        }

        ExecuteInTransaction(command =>
        {
            var assignments = new List<string>();
            int parameterIndex = 0;

            foreach (var item in values)
            {
                string column = QuoteIdentifier(item.Key);

                if (IsDatabaseNull(item.Value))
                {
                    assignments.Add($"{column} = NULL");
                }
                else
                {
                    string parameterName = $"u{parameterIndex++}";
                    assignments.Add($"{column} = @{parameterName}");
                    command.Parameters.AddWithValue(parameterName, item.Value!);
                }
            }

            string whereClause = BuildWhereClause(
                command,
                filters,
                "f",
                ref parameterIndex);

            command.CommandText =
                $"UPDATE {QuoteTableName(tableName)} " +
                $"SET {string.Join(", ", assignments)}" +
                $"{whereClause};";

            command.ExecuteNonQuery();
        });
    }

    public void Delete(
        string tableName,
        IReadOnlyDictionary<string, object?>? filters = null)
    {
        ExecuteInTransaction(command =>
        {
            int parameterIndex = 0;

            string whereClause = BuildWhereClause(
                command,
                filters,
                "d",
                ref parameterIndex);

            command.CommandText =
                $"DELETE FROM {QuoteTableName(tableName)}{whereClause};";

            command.ExecuteNonQuery();
        });
    }

    public void Close()
    {
        Dispose();
    }

    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _connection.Dispose();
        _disposed = true;
    }

    private void ExecuteInTransaction(Action<NpgsqlCommand> operation)
    {
        ThrowIfDisposed();

        using NpgsqlTransaction transaction = _connection.BeginTransaction();

        try
        {
            using var command = new NpgsqlCommand
            {
                Connection = _connection,
                Transaction = transaction
            };

            operation(command);
            transaction.Commit();
        }
        catch (NpgsqlException exception)
        {
            Console.WriteLine(exception.Message);

            try
            {
                transaction.Rollback();
            }
            catch (NpgsqlException rollbackException)
            {
                Console.WriteLine(
                    $"Rollback failed: {rollbackException.Message}");
            }
        }
    }

    private static string BuildWhereClause(
        NpgsqlCommand command,
        IReadOnlyDictionary<string, object?>? filters,
        string parameterPrefix,
        ref int parameterIndex)
    {
        if (filters is null || filters.Count == 0)
        {
            return string.Empty;
        }

        var predicates = new List<string>();

        foreach (var filter in filters)
        {
            string column = QuoteIdentifier(filter.Key);

            if (IsDatabaseNull(filter.Value))
            {
                predicates.Add($"{column} IS NULL");
            }
            else
            {
                string parameterName =
                    $"{parameterPrefix}{parameterIndex++}";

                predicates.Add($"{column} = @{parameterName}");
                command.Parameters.AddWithValue(
                    parameterName,
                    filter.Value!);
            }
        }

        return $" WHERE {string.Join(" AND ", predicates)}";
    }

    private static bool IsDatabaseNull(object? value)
    {
        return value is null || value == DBNull.Value;
    }

    private static string QuoteTableName(string tableName)
    {
        if (string.IsNullOrWhiteSpace(tableName))
        {
            throw new ArgumentException(
                "A table name is required.",
                nameof(tableName));
        }

        // Supports both "users" and schema-qualified names such as
        // "public.users".
        string[] parts = tableName.Split('.');

        if (parts.Any(string.IsNullOrWhiteSpace))
        {
            throw new ArgumentException(
                "The table name is invalid.",
                nameof(tableName));
        }

        return string.Join(".", parts.Select(QuoteIdentifier));
    }

    private static string QuoteIdentifier(string identifier)
    {
        if (string.IsNullOrWhiteSpace(identifier))
        {
            throw new ArgumentException(
                "A database identifier cannot be empty.",
                nameof(identifier));
        }

        return $"\"{identifier.Replace("\"", "\"\"")}\"";
    }
}
```

