Below is a C++ implementation. The list remains sorted after every insertion, provided it is initially empty or already sorted. The node is first linked at the beginning and then moved to its correct ascending position in \(O(n)\) time.

```cpp
#include <iostream>

struct Node {
    int value;
    Node* prev;
    Node* next;

    explicit Node(int v) : value(v), prev(nullptr), next(nullptr) {}
};

void insertAtBeginningAndSort(Node*& head, int value) {
    Node* inserted = new Node(value);

    // Insert at the beginning.
    inserted->next = head;
    if (head != nullptr) {
        head->prev = inserted;
    }
    head = inserted;

    // Move the new node right until it reaches its sorted position.
    while (inserted->next != nullptr &&
           inserted->value > inserted->next->value) {
        Node* before = inserted->prev;
        Node* right  = inserted->next;
        Node* after  = right->next;

        // Swap inserted and right.
        if (before != nullptr) {
            before->next = right;
        } else {
            head = right;
        }

        right->prev = before;
        right->next = inserted;

        inserted->prev = right;
        inserted->next = after;

        if (after != nullptr) {
            after->prev = inserted;
        }
    }
}

void printList(const Node* head) {
    while (head != nullptr) {
        std::cout << head->value;
        if (head->next != nullptr) {
            std::cout << ' ';
        }
        head = head->next;
    }
    std::cout << '\n';
}

void deleteList(Node*& head) {
    while (head != nullptr) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

int main() {
    Node* head = nullptr;

    insertAtBeginningAndSort(head, 5);
    insertAtBeginningAndSort(head, -3);
    insertAtBeginningAndSort(head, 0);
    insertAtBeginningAndSort(head, 8);
    insertAtBeginningAndSort(head, -10);
    insertAtBeginningAndSort(head, 5);

    printList(head);  // -10 -3 0 5 5 8

    deleteList(head);
    return 0;
}
```

Final answer: The function prepends each node and repositions it in ascending order while correctly maintaining both `prev` and `next` links.

