A common birthdate-validation mistake is combining type and range checks with `and`:

```python
from datetime import date

class IncorrectUser:
    def __init__(self, username, birthdate, email):
        # Incorrect:
        if not isinstance(birthdate, date) and birthdate > date.today():
            raise ValueError("Birthdate must be a date and cannot be in the future.")

        self.username = username
        self.birthdate = birthdate
        self.email = email
```

This condition is wrong because:

- A valid `date` in the future is not rejected: the first condition is `False`, so the whole `and` expression is `False`.
- An invalid non-date value may be compared with a `date`, causing `TypeError`.
- The type check and future-date check should be performed separately—or joined with `or` only after ensuring the comparison is safe.

Here is a corrected, complete implementation:

```python
import re
from datetime import date, datetime
from typing import Optional, Union


class User:
    """A validated user with a read-only username, birthdate, and email."""

    _EMAIL_PATTERN = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

    def __init__(
        self,
        username: str,
        birthdate: Union[date, datetime, str],
        email: str,
    ) -> None:
        self._username = self._validate_username(username)
        self._birthdate = self._validate_birthdate(birthdate)
        self._email = self._validate_email(email)

    @staticmethod
    def _validate_username(username: str) -> str:
        if not isinstance(username, str):
            raise TypeError("Username must be a string.")

        username = username.strip()

        if not username:
            raise ValueError("Username cannot be empty.")

        return username

    @staticmethod
    def _validate_birthdate(
        birthdate: Union[date, datetime, str],
    ) -> date:
        # Convert a datetime to a date.
        if isinstance(birthdate, datetime):
            birthdate = birthdate.date()

        # Accept an ISO-format string such as "1995-08-21".
        elif isinstance(birthdate, str):
            try:
                birthdate = date.fromisoformat(birthdate.strip())
            except ValueError as exc:
                raise ValueError(
                    "Birthdate must use YYYY-MM-DD format."
                ) from exc

        if not isinstance(birthdate, date):
            raise TypeError(
                "Birthdate must be a date, datetime, or YYYY-MM-DD string."
            )

        # This check is done only after confirming that birthdate is a date.
        if birthdate > date.today():
            raise ValueError("Birthdate cannot be in the future.")

        return birthdate

    @classmethod
    def _validate_email(cls, email: str) -> str:
        if not isinstance(email, str):
            raise TypeError("Email must be a string.")

        email = email.strip().lower()

        if not cls._EMAIL_PATTERN.fullmatch(email):
            raise ValueError("Invalid email address.")

        return email

    @property
    def username(self) -> str:
        return self._username

    @property
    def birthdate(self) -> date:
        return self._birthdate

    @property
    def email(self) -> str:
        return self._email

    def age(self, on_date: Optional[date] = None) -> int:
        """
        Return the user's age on the supplied date.

        If on_date is omitted, the current date is used.
        """
        if on_date is None:
            on_date = date.today()
        elif isinstance(on_date, datetime):
            on_date = on_date.date()
        elif not isinstance(on_date, date):
            raise TypeError("on_date must be a date or datetime.")

        if on_date < self.birthdate:
            raise ValueError("The age calculation date precedes the birthdate.")

        years = on_date.year - self.birthdate.year

        # Subtract one if the birthday has not occurred yet that year.
        birthday_has_not_occurred = (
            on_date.month,
            on_date.day,
        ) < (
            self.birthdate.month,
            self.birthdate.day,
        )

        return years - int(birthday_has_not_occurred)

    def to_dict(self) -> dict:
        """Return a serializable representation of the user."""
        return {
            "username": self.username,
            "birthdate": self.birthdate.isoformat(),
            "email": self.email,
            "age": self.age(),
        }

    def __repr__(self) -> str:
        return (
            f"User(username={self.username!r}, "
            f"birthdate={self.birthdate.isoformat()!r}, "
            f"email={self.email!r})"
        )


class Database:
    """
    An in-memory collection of users.

    Usernames and email addresses are treated as case-insensitive and must
    both be unique.
    """

    def __init__(self) -> None:
        self._users_by_username: dict[str, User] = {}
        self._users_by_email: dict[str, User] = {}

    @staticmethod
    def _username_key(username: str) -> str:
        if not isinstance(username, str):
            raise TypeError("Username must be a string.")
        return username.strip().casefold()

    @staticmethod
    def _email_key(email: str) -> str:
        if not isinstance(email, str):
            raise TypeError("Email must be a string.")
        return email.strip().casefold()

    def add_user(self, user: User) -> None:
        """Add a User, rejecting duplicate usernames or email addresses."""
        if not isinstance(user, User):
            raise TypeError("Only User objects can be added.")

        username_key = self._username_key(user.username)
        email_key = self._email_key(user.email)

        if username_key in self._users_by_username:
            raise ValueError(f"Username {user.username!r} already exists.")

        if email_key in self._users_by_email:
            raise ValueError(f"Email {user.email!r} already exists.")

        self._users_by_username[username_key] = user
        self._users_by_email[email_key] = user

    def remove_user(self, user_or_username: Union[User, str]) -> User:
        """
        Remove and return a user.

        The user can be specified using either a User object or a username.
        Raises KeyError if the user is not in the database.
        """
        if isinstance(user_or_username, User):
            username_key = self._username_key(user_or_username.username)
            user = self._users_by_username.get(username_key)

            # Avoid removing a different object with the same username.
            if user is not user_or_username:
                raise KeyError("User is not in the database.")
        elif isinstance(user_or_username, str):
            username_key = self._username_key(user_or_username)
            user = self._users_by_username.get(username_key)

            if user is None:
                raise KeyError(
                    f"No user with username {user_or_username!r}."
                )
        else:
            raise TypeError("Expected a User object or username string.")

        del self._users_by_username[self._username_key(user.username)]
        del self._users_by_email[self._email_key(user.email)]
        return user

    def find_by_username(self, username: str) -> Optional[User]:
        """Return the matching user, or None if no user is found."""
        return self._users_by_username.get(self._username_key(username))

    def find_by_email(self, email: str) -> Optional[User]:
        """Return the matching user, or None if no user is found."""
        return self._users_by_email.get(self._email_key(email))

    def get_user_info(self, username: str) -> Optional[dict]:
        """Return one user's information, or None if not found."""
        user = self.find_by_username(username)
        return user.to_dict() if user is not None else None

    def get_all_users_info(self) -> list[dict]:
        """Return information for every user in username order."""
        users = sorted(
            self._users_by_username.values(),
            key=lambda user: user.username.casefold(),
        )
        return [user.to_dict() for user in users]

    def __len__(self) -> int:
        return len(self._users_by_username)

    def __iter__(self):
        return iter(self._users_by_username.values())
```

Example usage:

```python
database = Database()

alice = User("Alice", "1990-05-17", "alice@example.com")
bob = User("Bob", date(1985, 12, 3), "bob@example.com")

database.add_user(alice)
database.add_user(bob)

print(alice.age())
print(database.find_by_username("alice"))
