Python’s standard `xml.etree.ElementTree` can parse the XML, while a recursive function converts repeated sibling tags into lists:

```python
import xml.etree.ElementTree as ET


def element_to_value(element):
    children = list(element)

    # Leaf element
    if not children:
        return (element.text or "").strip()

    result = {}

    for child in children:
        value = element_to_value(child)

        if child.tag in result:
            # Convert the first occurrence into a list when a duplicate appears.
            if not isinstance(result[child.tag], list):
                result[child.tag] = [result[child.tag]]
            result[child.tag].append(value)
        else:
            result[child.tag] = value

    return result


def xml_to_dict(xml_string):
    root = ET.fromstring(xml_string)
    return {root.tag: element_to_value(root)}


xml_string = """
<students>
  <student>
    <name>John</name>
    <age>30</age>
    <city>New York</city>
  </student>
  <student>
    <name>Jane</name>
    <age>25</age>
    <city>Chicago</city>
  </student>
</students>
"""

data = xml_to_dict(xml_string)
print(data)
```

