```js
// server.js
const express = require("express");

const app = express();
const PORT = process.env.PORT || 3000;

const WINDOW_MS = 60 * 1000;
const MAX_REQUESTS = 10;
const clients = new Map();

/**
 * Fixed-window rate limiter: at most 10 requests per minute per IP.
 *
 * Configure Express's `trust proxy` setting if the application runs behind
 * a trusted reverse proxy so that req.ip contains the actual client address.
 */
// app.set("trust proxy", 1);

function rateLimiter(req, res, next) {
  const ip = req.ip;
  const now = Date.now();

  let client = clients.get(ip);

  if (!client || now >= client.resetAt) {
    client = {
      count: 0,
      resetAt: now + WINDOW_MS,
    };
    clients.set(ip, client);
  }

  const resetInSeconds = Math.max(
    1,
    Math.ceil((client.resetAt - now) / 1000)
  );

  res.set({
    "RateLimit-Limit": String(MAX_REQUESTS),
    "RateLimit-Remaining": String(
      Math.max(0, MAX_REQUESTS - client.count)
    ),
    "RateLimit-Reset": String(resetInSeconds),
  });

  if (client.count >= MAX_REQUESTS) {
    res.set("Retry-After", String(resetInSeconds));

    return res.status(429).json({
      error: "Too many requests",
      message: "A maximum of 10 requests per minute is allowed.",
      retryAfterSeconds: resetInSeconds,
    });
  }

  client.count += 1;
  res.set(
    "RateLimit-Remaining",
    String(Math.max(0, MAX_REQUESTS - client.count))
  );

  next();
}

function requireJsonContentType(req, res, next) {
  if (!req.is("application/json")) {
    return res.status(415).json({
      error: "Content-Type must be application/json",
    });
  }

  next();
}

app.post(
  "/api/log",
  rateLimiter,
  requireJsonContentType,
  express.json({ limit: "100kb" }),
  (req, res) => {
    // Ensure that the parsed JSON value is an object rather than null,
    // an array, string, number, or boolean.
    if (
      req.body === null ||
      typeof req.body !== "object" ||
      Array.isArray(req.body)
    ) {
      return res.status(400).json({
        error: "The request body must be a JSON object.",
      });
    }

    console.log("Request path:", req.path);
    console.log("Request body:", req.body);

    return res.status(200).json({
      message: "Request logged successfully.",
    });
  }
);

// Express error-handling middleware must have all four parameters.
app.use((err, req, res, next) => {
  if (err.type === "entity.parse.failed") {
    return res.status(400).json({
      error: "Invalid JSON in request body.",
    });
  }

  if (err.type === "entity.too.large") {
    return res.status(413).json({
      error: "Request body is too large.",
    });
  }

  console.error(err);

  return res.status(500).json({
    error: "Internal server error.",
  });
});

// Periodically remove expired IP entries to prevent unbounded map growth.
const cleanupTimer = setInterval(() => {
  const now = Date.now();

  for (const [ip, client] of clients.entries()) {
    if (now >= client.resetAt) {
      clients.delete(ip);
    }
  }
}, WINDOW_MS);

cleanupTimer.unref();

app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
```

