ground_truth:
```go
package main

import (
	"fmt"
	"strings"
)

// validateNestedParens checks whether the parentheses in lst are balanced
// and correctly ordered.
func validateNestedParens(lst []string) string {
	// Equivalent to Python's: s = ''.join(lst)
	s := strings.Join(lst, "")

	count := 0

	// range iterates over each character in the string.
	for _, c := range s {
		if c == '(' {
			count++
		} else if c == ')' {
			// A closing parenthesis cannot appear before a matching
			// opening parenthesis.
			if count == 0 {
				return "Negative"
			}
			count--
		}
	}

	// Any unmatched opening parentheses make the result invalid.
	if count == 0 {
		return "Affirmative"
	}
	return "Negative"
}

func main() {
	fmt.Println(validateNestedParens([]string{"(", "(", ")", ")"})) // Affirmative
	fmt.Println(validateNestedParens([]string{"(", ")", ")"}))      // Negative
	fmt.Println(validateNestedParens([]string{"(", "("}))           // Negative
}
```

Key Go translation notes:

- Python’s `list` becomes a Go slice: `[]string`.
- `strings.Join(lst, "")` is equivalent to `''.join(lst)`.
- `for _, c := range s` iterates over the characters; `_` discards each character’s index.
- Go uses `count++` and `count--` instead of `count += 1` and `count -= 1`.
- Go does not have Python’s inline conditional expression, so the final result uses an `if` statement.

