declare(strict_types=1);

function requiredEnv(string $name): string
{
    $value = getenv($name);

    if ($value === false || trim($value) === '') {
        throw new RuntimeException("Required environment variable {$name} is missing.");
    }

    return $value;
}

function connectToDatabase(): PDO
{
    $host   = requiredEnv('DB_HOST');
    $port   = getenv('DB_PORT') ?: '3306';
    $name   = requiredEnv('DB_NAME');
    $user   = requiredEnv('DB_USER');
    $pass   = requiredEnv('DB_PASSWORD');
    $caFile = requiredEnv('DB_SSL_CA');

    if (!ctype_digit($port)) {
        throw new RuntimeException('DB_PORT must be numeric.');
    }

    if (!is_file($caFile) || !is_readable($caFile)) {
        throw new RuntimeException('The MySQL CA certificate is not readable.');
    }

    $dsn = sprintf(
        'mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',
        $host,
        (int) $port,
        $name
    );

    return new PDO($dsn, $user, $pass, [
        PDO::ATTR_ERRMODE                  => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE       => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES         => false,
        PDO::ATTR_PERSISTENT               => false,
        PDO::ATTR_TIMEOUT                  => 5,
        PDO::MYSQL_ATTR_SSL_CA             => $caFile,
        PDO::MYSQL_ATTR_SSL_VERIFY_SERVER_CERT => true,
    ]);
}

try {
