Use the multibyte string functions so UTF-8 characters are handled correctly, then cut back to the last whitespace boundary:

```php
function truncateWords(
    string $text,
    int $limit,
    string $ellipsis = '…'
): string {
    if ($limit < 0) {
        throw new InvalidArgumentException('Limit cannot be negative.');
    }

    if (mb_strlen($text, 'UTF-8') <= $limit) {
        return $text;
    }

    $prefix = mb_substr($text, 0, $limit, 'UTF-8');
    $nextCharacter = mb_substr($text, $limit, 1, 'UTF-8');

    // If the cut occurred inside a word, remove that partial word.
    if ($nextCharacter !== '' && !preg_match('/^\s$/u', $nextCharacter)) {
        $prefix = preg_replace('/(?:^|\s)\S*$/uD', '', $prefix);
    }

    $prefix = preg_replace('/\s+$/u', '', $prefix);

    return $prefix . $ellipsis;
}

echo truncateWords(
    'This is a long sentence that should be shortened.',
    25
);
// This is a long sentence…
```

Here, `$limit` is the maximum number of characters considered from the original text; the ellipsis is appended afterward. If the first word alone exceeds the limit, the result is just the ellipsis rather than a cut word.

Final answer: Truncate with `mb_substr()`, remove any partial final word at the last whitespace boundary, and append the ellipsis only when truncation occurs.

### `cuboid.py`

```python
import math
from numbers import Real


class Cuboid:
    """Represent a cuboid with non-negative length, width, and height."""

    def __init__(self, length: Real, width: Real, height: Real) -> None:
        self.length = length
        self.width = width
        self.height = height

    @staticmethod
    def _validate_dimension(name: str, value: Real) -> float:
        # bool is a subclass of int, but it is not a meaningful dimension.
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError(f"{name} must be a numeric value")

        try:
            numeric_value = float(value)
        except (OverflowError, ValueError) as exc:
            raise ValueError(f"{name} must be a finite numeric value") from exc

        if not math.isfinite(numeric_value):
            raise ValueError(f"{name} must be finite")

        if numeric_value < 0:
            raise ValueError(f"{name} cannot be negative")

        return numeric_value

    @property
    def length(self) -> float:
        return self._length

    @length.setter
    def length(self, value: Real) -> None:
        self._length = self._validate_dimension("length", value)

    @property
    def width(self) -> float:
        return self._width

    @width.setter
    def width(self, value: Real) -> None:
        self._width = self._validate_dimension("width", value)

    @property
    def height(self) -> float:
        return self._height

    @height.setter
    def height(self, value: Real) -> None:
        self._height = self._validate_dimension("height", value)

    def surface_area(self) -> float:
        """Return the total surface area of the cuboid."""
        return 2 * (
            self.length * self.width
            + self.length * self.height
            + self.width * self.height
        )

    def volume(self) -> float:
        """Return the volume of the cuboid."""
        return self.length * self.width * self.height

    def describe(self) -> str:
        """Return a string containing the dimensions, area, and volume."""
        return (
            f"Cuboid(length={self.length:g}, width={self.width:g}, "
            f"height={self.height:g}, surface_area={self.surface_area():g}, "
            f"volume={self.volume():g})"
        )

    def __str__(self) -> str:
        return self.describe()

    def __repr__(self) -> str:
        return self.describe()
```

