        self.assertEqual(cuboid.length, 2.0)
        self.assertEqual(cuboid.width, 3.0)
        self.assertEqual(cuboid.height, 4.0)

    def test_surface_area(self):
        cuboid = Cuboid(2, 3, 4)

        # 2 * (2*3 + 2*4 + 3*4) = 52
        self.assertEqual(cuboid.surface_area(), 52.0)

    def test_volume(self):
        cuboid = Cuboid(2, 3, 4)

        self.assertEqual(cuboid.volume(), 24.0)

    def test_decimal_dimensions(self):
        cuboid = Cuboid(1.5, 2.0, 3.5)

        self.assertAlmostEqual(cuboid.surface_area(), 24.5)
        self.assertAlmostEqual(cuboid.volume(), 10.5)

    def test_string_representation(self):
        cuboid = Cuboid(2, 3, 4)

        expected = (
            "Cuboid(length=2, width=3, height=4, "
            "surface_area=52, volume=24)"
        )
        self.assertEqual(str(cuboid), expected)
        self.assertEqual(cuboid.describe(), expected)
        self.assertEqual(repr(cuboid), expected)

    def test_zero_dimension(self):
