        self.assertEqual(cuboid.surface_area(), 24.0)
        self.assertEqual(cuboid.volume(), 0.0)

    def test_negative_dimensions_raise_value_error(self):
        for dimensions in [(-1, 2, 3), (1, -2, 3), (1, 2, -3)]:
            with self.subTest(dimensions=dimensions):
                with self.assertRaises(ValueError):
                    Cuboid(*dimensions)

    def test_non_numeric_dimensions_raise_type_error(self):
        invalid_dimensions = [
