            (2, None, 4),
            (2, 3, [4]),
            (True, 3, 4),
        ]

        for dimensions in invalid_dimensions:
            with self.subTest(dimensions=dimensions):
                with self.assertRaises(TypeError):
                    Cuboid(*dimensions)

