    "use strict";

    const form = document.getElementById("address-form");
    const addressInput = document.getElementById("address");
    const browserFrame = document.getElementById("browser-frame");
    const statusMessage = document.getElementById("status");

    let requestedUrl = "";

    /**
     * Parses user input and permits only normal web URLs.
     *
     * The input uses type="url", so a complete URL is normally expected.
     * The fallback prefix also makes the function usable if the input is
     * later changed to type="text".
     */
    function parseWebUrl(value) {
      let candidate = value.trim();

      if (candidate === "") {
        throw new Error("Enter a URL.");
      }

      const detectedScheme = candidate.match(
        /^([a-z][a-z0-9+.-]*):/i
      );

      // Reject explicit non-web schemes such as javascript:, data:, and file:.
      if (
        detectedScheme &&
        !/^https?:\/\//i.test(candidate)
      ) {
        throw new Error("Only HTTP and HTTPS URLs are allowed.");
      }

      if (!/^https?:\/\//i.test(candidate)) {
        candidate = "https://" + candidate;
      }

      let parsedUrl;

      try {
        parsedUrl = new URL(candidate);
      } catch {
        throw new Error("The entered URL is not valid.");
      }

      if (
        parsedUrl.protocol !== "http:" &&
        parsedUrl.protocol !== "https:"
      ) {
        throw new Error("Only HTTP and HTTPS URLs are allowed.");
      }

      return parsedUrl;
    }

    form.addEventListener("submit", function (event) {
      // Prevent the form's normal navigation and full-page refresh.
      event.preventDefault();

      statusMessage.classList.remove("error");

      try {
        const parsedUrl = parseWebUrl(addressInput.value);

        requestedUrl = parsedUrl.href;
        addressInput.value = parsedUrl.href;

        statusMessage.textContent = "Loading " + parsedUrl.href + " …";

        // Assigning src initiates a new iframe navigation without reloading
        // the containing page.
        browserFrame.src = parsedUrl.href;
      } catch (error) {
        requestedUrl = "";
        statusMessage.textContent = error.message;
        statusMessage.classList.add("error");
        addressInput.focus();
      }
    });

    browserFrame.addEventListener("load", function () {
      if (requestedUrl !== "") {
        statusMessage.textContent =
          "The frame finished navigating to " + requestedUrl + ".";
        statusMessage.classList.remove("error");
      }
    });
  </script>
