VSTO already provides an in-process mechanism for this: expose an **automation object** from the add-in by overriding `RequestComAddInAutomationService`. VBA can retrieve that object through `Application.COMAddIns(...).Object`.

```csharp
using System;
using System.Runtime.InteropServices;

[ComVisible(true)]
[Guid("D7090A39-45D8-4F22-932A-18D72CE8B42E")]
[InterfaceType(ComInterfaceType.InterfaceIsDual)]
public interface IExcelAddInApi
{
    string DoSomething(string value);
}

[ComVisible(true)]
[ClassInterface(ClassInterfaceType.None)]
public sealed class ExcelAddInApi : IExcelAddInApi
{
    public string DoSomething(string value)
    {
        return "Result: " + value;
    }
