What would this look like in PHP?
from typing import List

def intersperse(numbers: List[int], delimiter: int) -> List[int]:
    if delimiter < 0:
        skip_position = -delimiter - 1
        new_list = numbers[:]
        for idx, num in enumerate(numbers[:-1]):
