Develop a JavaScript function that accepts a string input, applies the binary search algorithm along with the bubble sort algorithm on its characters, and returns the rearranged string in alphabetical order. The function should also have error handling to identify any non-character inputs. Include a series of unit tests to verify the function's accuracy.

Here is a piece of erroneous code as a reference:

```javascript
function sortString(str) {
    return str.split('').sort().join('');
}
```

string = "hello world"

ground_truth:
The binary-search steps are used to locate each character’s range after bubble sort. Spaces are retained, so `"hello world"` becomes `" dehllloorw"`. Non-string values cause a `TypeError`.

```javascript
"use strict";

const assert = require("node:assert/strict");

/**
 * Compares two characters using JavaScript's deterministic
 * lexicographical ordering.
 */
function compareCharacters(a, b) {
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

/**
 * Sorts an array in place using bubble sort.
 */
function bubbleSort(characters) {
    for (let end = characters.length - 1; end > 0; end--) {
        let swapped = false;

        for (let i = 0; i < end; i++) {
            if (compareCharacters(characters[i], characters[i + 1]) > 0) {
                [characters[i], characters[i + 1]] =
                    [characters[i + 1], characters[i]];
                swapped = true;
            }
        }

        // The array is already sorted.
        if (!swapped) break;
    }

    return characters;
}

/**
 * Binary search for the first index at which target may occur.
 */
function lowerBound(characters, target) {
    let low = 0;
    let high = characters.length;

    while (low < high) {
        const middle = Math.floor((low + high) / 2);

        if (compareCharacters(characters[middle], target) < 0) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }

    return low;
}

/**
 * Binary search for the index immediately after the last target.
 */
function upperBound(characters, target) {
    let low = 0;
    let high = characters.length;

    while (low < high) {
        const middle = Math.floor((low + high) / 2);

        if (compareCharacters(characters[middle], target) <= 0) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }

    return low;
}

/**
 * Rearranges all characters in a string into lexicographical order.
 *
 * @param {string} str
 * @returns {string}
 * @throws {TypeError} If str is not a primitive string.
 */
function sortString(str) {
    if (typeof str !== "string") {
        throw new TypeError(
            `sortString expected a string, but received ${typeof str}`
        );
    }

    // Array.from handles Unicode code points better than split("").
    const sortedCharacters = bubbleSort(Array.from(str));
    const result = [];

    // Use binary searches to locate the complete range of each
    // distinct character in the bubble-sorted array.
    let index = 0;

    while (index < sortedCharacters.length) {
        const character = sortedCharacters[index];
        const first = lowerBound(sortedCharacters, character);
        const afterLast = upperBound(sortedCharacters, character);

        for (let i = first; i < afterLast; i++) {
            result.push(character);
        }

        index = afterLast;
    }

    return result.join("");
}

/* -------------------------- Unit tests -------------------------- */

assert.equal(
    sortString("hello world"),
    " dehllloorw",
    "Should sort the supplied example and retain its space"
);

assert.equal(
    sortString("dcba"),
    "abcd",
    "Should sort characters alphabetically"
);

assert.equal(
    sortString("banana"),
    "aaabnn",
    "Should retain duplicate characters"
);

assert.equal(
    sortString("already"),
    "aadelry",
    "Should sort an ordinary word"
);

assert.equal(
    sortString(""),
    "",
    "Should handle an empty string"
);

assert.equal(
    sortString("   "),
    "   ",
    "Should retain whitespace"
);

assert.equal(
    sortString("bAaB"),
    "ABab",
    "Should use case-sensitive lexicographical ordering"
);

assert.equal(
    sortString("321abc"),
    "123abc",
    "Digits inside a string are characters and should be sorted"
);

assert.throws(
    () => sortString(123),
    TypeError,
    "Should reject numbers"
);

assert.throws(
    () => sortString(null),
    TypeError,
    "Should reject null"
);

assert.throws(
    () => sortString(["a", "b"]),
    TypeError,
    "Should reject arrays"
);

assert.throws(
    () => sortString({ value: "abc" }),
    TypeError,
    "Should reject objects"
);

console.log("All unit tests passed.");

module.exports = {
    sortString,
    bubbleSort,
    lowerBound,
    upperBound
};
```

