        if self.health <= 0:
            self.health = 0
            return f"{self.name} has died"

        return f"{self.name}'s health has decreased to {self.health}"


class Dog(Animal):
    def __init__(self, name, age, habitat, breed):
        super().__init__(name, age, habitat)
        self.breed = breed

    def bark(self, times):
