            raise ValueError("times cannot be negative")
        return " ".join("Woof!" for _ in range(times))

    def __str__(self):
        return (
            f"Dog(name={self.name}, age={self.age}, "
            f"habitat={self.habitat}, breed={self.breed})"
        )


class Cat(Animal):
