        super().__init__(name, age, habitat)
        self.color = color

    def meow(self, times):
        if times < 0:
            raise ValueError("times cannot be negative")
        return " ".join("Meow!" for _ in range(times))

    def __str__(self):
        return (
            f"Cat(name={self.name}, age={self.age}, "
            f"habitat={self.habitat}, color={self.color})"
        )


