        print(f"{dog.name} attacks for {damage} damage. {dog_attack_result}")

        if cat.health <= 0:
            return dog

        # The cat then attacks.
        damage = random.randint(5, 20)
        cat_attack_result = dog.decrease_health(damage)
        print(f"{cat.name} attacks for {damage} damage. {cat_attack_result}")

        if dog.health <= 0:
            return cat


# Example:
