public class BigQueryExample {

    public static void main(String[] args) {
        // Replace these with the actual values and appropriate Java types.
        double conditionValue1 = 10.0;
        double conditionValue2 = 100.0;

        // Uses Application Default Credentials.
        BigQuery client = BigQueryOptions.getDefaultInstance().getService();

        String query =
                "SELECT column1, column2, column3\n" +
                "FROM `project_id.dataset_id.table_id`\n" +
                "WHERE condition1 > @conditionValue1\n" +
                "  AND condition2 < @conditionValue2\n" +
