                        .build();

        try {
            // Java equivalent of client.query(query).to_dataframe().
            TableResult result = client.query(queryConfig);

            // Example: iterate over the returned rows.
            for (FieldValueList row : result.iterateAll()) {
                for (Field field : result.getSchema().getFields()) {
                    String columnName = field.getName();
                    Object value = row.get(columnName).isNull()
                            ? null
                            : row.get(columnName).getValue();

