Here is the cleaned-up version, preserving the apparent original logic:

```python
import sys

# All eight possible neighboring directions.
dx = [-1, -1, -1, 0, 0, 1, 1, 1]
dy = [-1,  0,  1, -1, 1, -1, 0, 1]


def is_valid_move(x, y, n):
    return 0 <= x < n and 0 <= y < n


def find_min_sum(grid, x, y, k, n):
    if k == 0:
        return grid[x][y]

    min_sum = sys.maxsize

    for i in range(8):
        new_x = x + dx[i]
        new_y = y + dy[i]

        if is_valid_move(new_x, new_y, n):
            current_sum = (
                grid[x][y]
                + find_min_sum(grid, new_x, new_y, k - 1, n)
            )
            min_sum = min(min_sum, current_sum)

    return min_sum


def path_finder(grid, k):
    if not grid or k < 1:
        raise ValueError("grid must be nonempty and k must be at least 1")

    n = len(grid)

    if any(len(row) != n for row in grid):
        raise ValueError("grid must be square")

    min_sum = sys.maxsize

    for x in range(n):
        for y in range(n):
            current_sum = find_min_sum(grid, x, y, k - 1, n)
            min_sum = min(min_sum, current_sum)

    return min_sum
```

This finds the minimum sum of a path containing `k` cells, moving in any of the eight neighboring directions. As written, a path may revisit cells.

