ground_truth:
A `vector<vector<string>>` cannot store names as strings and scores as integers because every element must have the same type. Use a structure or `pair<string, int>` instead.

```cpp
#include <algorithm>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

using namespace std;

using Student = pair<string, int>;  // name, score

void add_and_sort(vector<Student>& students,
                  const string& new_name,
                  int new_score) {
    students.emplace_back(new_name, new_score);

    sort(students.begin(), students.end(),
         [](const Student& a, const Student& b) {
             if (a.second != b.second) {
                 return a.second > b.second;  // Higher score first
             }
             return a.first < b.first;        // Names alphabetically
         });
}

int main() {
    vector<Student> students = {
        {"Sam", 70},
        {"Tom", 85},
        {"Jess", 80}
    };

    add_and_sort(students, "Jen", 92);

    for (const auto& [name, score] : students) {
        cout << name << ": " << score << '\n';
    }

    return 0;
}
```

