def rgb_to_hsv(rgb_tuple):
    if isinstance(rgb_tuple, tuple) and len(rgb_tuple) == 3:
        r, g, b = [x / 255 for x in rgb_tuple]

        max_val = max(r, g, b)
        min_val = min(r, g, b)
        diff = max_val - min_val

        if max_val == min_val:
            h = 0
        elif max_val == r:
            h = (60 * ((g - b) / diff) + 360) % 360
        elif max_val == g:
            h = (60 * ((b - r) / diff) + 120) % 360
        else:  # max_val == b
            h = (60 * ((r - g) / diff) + 240) % 360

        if max_val == 0:
            s = 0
        else:
            s = diff / max_val

        v = max_val

        return h, s, v

    raise ValueError("Invalid RGB tuple")


def hsv_to_rgb(hsv_tuple):
    if isinstance(hsv_tuple, tuple) and len(hsv_tuple) == 3:
        h, s, v = hsv_tuple

        c = v * s
        x = c * (1 - abs((h / 60) % 2 - 1))
        m = v - c

        if h < 60:
            r, g, b = c, x, 0
        elif h < 120:
            r, g, b = x, c, 0
        elif h < 180:
            r, g, b = 0, c, x
        elif h < 240:
            r, g, b = 0, x, c
        elif h < 300:
            r, g, b = x, 0, c
        else:
            r, g, b = c, 0, x

        r, g, b = (
            (r + m) * 255,
            (g + m) * 255,
            (b + m) * 255,
        )

        return r, g, b

    raise ValueError("Invalid HSV tuple")
