    }

    public static double modulus(double dividend, double divisor) {
        if (divisor == 0.0) {
            throw new ArithmeticException("Modulus by zero is not allowed.");
        }

        return requireFiniteResult(dividend % divisor);
    }

    public static double exponentiation(double base, double exponent) {
        double result = Math.pow(base, exponent);

        if (!Double.isFinite(result)) {
            throw new ArithmeticException(
                    "Exponentiation did not produce a finite real result."
            );
        }

        return result;
    }

    public static double squareRoot(double number) {
        if (number < 0.0) {
            throw new ArithmeticException(
                    "The square root of a negative number is not a real number."
            );
        }

        return Math.sqrt(number);
    }

    public static BigInteger factorial(int number) {
        if (number < 0) {
            throw new IllegalArgumentException(
                    "Factorial is only defined for non-negative integers."
            );
        }

        if (number > MAX_FACTORIAL_INPUT) {
            throw new IllegalArgumentException(
                    "Factorial input must not exceed "
                            + MAX_FACTORIAL_INPUT + "."
            );
        }

        BigInteger result = BigInteger.ONE;

        for (int i = 2; i <= number; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }

        return result;
    }

    private static double readDouble(Scanner scanner, String prompt) {
        System.out.print(prompt);
        String input = scanner.nextLine().trim();

        try {
            double value = Double.parseDouble(input);

            if (!Double.isFinite(value)) {
                throw new IllegalArgumentException(
                        "The number must be finite."
                );
            }

            return value;
        } catch (NumberFormatException exception) {
            throw new IllegalArgumentException(
                    "'" + input + "' is not a valid number."
            );
        }
    }

    private static int readInteger(Scanner scanner, String prompt) {
        System.out.print(prompt);
        String input = scanner.nextLine().trim();

        try {
            return Integer.parseInt(input);
        } catch (NumberFormatException exception) {
            throw new IllegalArgumentException(
                    "'" + input + "' is not a valid integer."
            );
        }
    }

    private static double requireFiniteResult(double result) {
        if (!Double.isFinite(result)) {
            throw new ArithmeticException(
                    "The calculation did not produce a finite result."
            );
        }

        return result;
    }

    private static void displayAndRecord(
            List<String> history,
            String calculation
    ) {
        history.add(calculation);
        System.out.println("Result: " + calculation);
    }

    private static void displayHistory(List<String> history) {
        System.out.println("Session history:");

        if (history.isEmpty()) {
            System.out.println("No calculations have been performed.");
            return;
        }

        for (int i = 0; i < history.size(); i++) {
            System.out.println((i + 1) + ". " + history.get(i));
        }
    }

    private static String format(double value) {
        // Avoid displaying negative zero.
        if (value == 0.0) {
            return "0";
        }

        // Display small whole-number results without a trailing ".0".
        if (value == Math.rint(value)
                && Math.abs(value) <= Long.MAX_VALUE) {
            return Long.toString((long) value);
        }

        return Double.toString(value);
    }
}
```

Successful calculations are stored in an `ArrayList` and can be viewed by entering `history`. The history is also displayed when the calculator exits. Invalid operations and invalid numeric inputs do not terminate the program or get added to the history.

