prompt:
Engineer a Python-coded solution to enumerate and manipulate the constituent entries found within a predetermined Python dictionary and a list of dictionaries. We are interested in performing CRUD operations (Create, Read, Update, Delete) on the dictionary and list of dictionaries.

The specific dictionary is as follows:
dictionary = {
    "name": "John",
    "age": 20,
    "location": "London"
}

And the specific list of dictionaries is as follows:
list_of_dictionaries = [
    {
        "name": "Alex",
        "age": 32,
        "location": "New York"
    },
    {
        "name": "Liz",
        "age": 28,
        "location": "Paris"
    }
]

Make sure to include functions for adding new entries, updating existing ones, retrieving one or more entries and deleting specific entries. Examine the error handling structures established to prevent tampering with nonexistent data.

ground_truth:
The following runnable implementation supports CRUD operations on both the individual dictionary and the list of dictionaries. Missing keys or records raise `KeyError`; duplicate additions raise `ValueError`; and malformed records raise `TypeError` or `ValueError`. Read operations return deep copies so callers cannot accidentally modify the original data.

```python
from copy import deepcopy
from typing import Any, Iterable, Mapping


dictionary = {
    "name": "John",
    "age": 20,
    "location": "London"
}

list_of_dictionaries = [
    {
        "name": "Alex",
        "age": 32,
        "location": "New York"
    },
    {
        "name": "Liz",
        "age": 28,
        "location": "Paris"
    }
]


# ---------------------------------------------------------------------------
# CRUD operations for a single dictionary
# ---------------------------------------------------------------------------

def add_entry(data: dict[str, Any], key: str, value: Any) -> None:
    """Create a key/value entry, rejecting a key that already exists."""
    if key in data:
        raise ValueError(
            f"Cannot add {key!r}: the key already exists. "
            "Use update_entry() instead."
        )

    data[key] = value


def get_entry(data: dict[str, Any], key: str) -> Any:
    """Read one dictionary entry."""
    if key not in data:
        raise KeyError(f"Cannot retrieve {key!r}: the key does not exist.")

    return deepcopy(data[key])


def get_entries(
    data: dict[str, Any],
    keys: Iterable[str] | None = None
) -> dict[str, Any]:
    """
    Read multiple entries.

    If keys is None, a copy of the entire dictionary is returned.
    """
    if keys is None:
        return deepcopy(data)

    requested_keys = list(keys)
    missing_keys = [key for key in requested_keys if key not in data]

    if missing_keys:
        raise KeyError(f"Keys do not exist: {missing_keys}")

    return {key: deepcopy(data[key]) for key in requested_keys}


def update_entry(data: dict[str, Any], key: str, new_value: Any) -> None:
    """Update an existing dictionary entry."""
    if key not in data:
        raise KeyError(
            f"Cannot update {key!r}: the key does not exist. "
            "Use add_entry() instead."
        )

    data[key] = new_value


def delete_entry(data: dict[str, Any], key: str) -> Any:
    """Delete an existing entry and return its former value."""
    if key not in data:
        raise KeyError(f"Cannot delete {key!r}: the key does not exist.")

    return data.pop(key)


def enumerate_dictionary(data: dict[str, Any]) -> None:
    """Display every key/value entry."""
    for key, value in data.items():
        print(f"{key}: {value}")


# ---------------------------------------------------------------------------
# Validation and lookup helpers for the list of dictionaries
# ---------------------------------------------------------------------------

def validate_record(record: Mapping[str, Any]) -> None:
    """
    Validate a person record.

    The name field serves as the unique identifier in the list.
    """
    if not isinstance(record, Mapping):
        raise TypeError("A record must be a dictionary or other mapping.")

    required_fields = {"name", "age", "location"}
    missing_fields = required_fields - record.keys()

    if missing_fields:
        raise ValueError(
            f"Record is missing required fields: {sorted(missing_fields)}"
        )

    if not isinstance(record["name"], str) or not record["name"].strip():
        raise ValueError("'name' must be a nonempty string.")

    if (
        not isinstance(record["age"], int)
        or isinstance(record["age"], bool)
        or record["age"] < 0
    ):
        raise ValueError("'age' must be a nonnegative integer.")

    if not isinstance(record["location"], str):
        raise ValueError("'location' must be a string.")


def _find_record_index(
    records: list[dict[str, Any]],
    name: str
) -> int:
    """Find a record's index or raise KeyError if it does not exist."""
    for index, record in enumerate(records):
        if record.get("name") == name:
            return index

    raise KeyError(f"No record exists for name {name!r}.")


# ---------------------------------------------------------------------------
# CRUD operations for the list of dictionaries
# ---------------------------------------------------------------------------

def add_record(
    records: list[dict[str, Any]],
    new_record: Mapping[str, Any]
) -> None:
    """Create a new record, rejecting duplicate names."""
    validate_record(new_record)
    name = new_record["name"]

    if any(record.get("name") == name for record in records):
        raise ValueError(
            f"Cannot add record: a record named {name!r} already exists."
        )

    # Copy the record so later changes to new_record do not alter stored data.
    records.append(deepcopy(dict(new_record)))


def get_record(
    records: list[dict[str, Any]],
    name: str
) -> dict[str, Any]:
    """Read one record by its unique name."""
    index = _find_record_index(records, name)
    return deepcopy(records[index])


def get_all_records(
    records: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Read all records without exposing the original mutable objects."""
    return deepcopy(records)


def find_records(
    records: list[dict[str, Any]],
    **criteria: Any
) -> list[dict[str, Any]]:
    """
    Read all records matching the supplied fields.

    Example:
        find_records(records, location="Paris")
        find_records(records, age=28, location="Paris")
    """
    if not criteria:
        return get_all_records(records)

    known_fields = {
        key
        for record in records
        for key in record
    }
    unknown_fields = set(criteria) - known_fields

    if unknown_fields:
        raise KeyError(
            f"Cannot search nonexistent fields: {sorted(unknown_fields)}"
        )

    matches = [
        deepcopy(record)
        for record in records
        if all(record.get(key) == value for key, value in criteria.items())
    ]

    return matches


def update_record(
    records: list[dict[str, Any]],
    name: str,
    changes: Mapping[str, Any]
) -> None:
    """Update selected fields of an existing record."""
    if not isinstance(changes, Mapping):
        raise TypeError("Record changes must be supplied as a mapping.")

    if not changes:
        raise ValueError("At least one change must be supplied.")

    index = _find_record_index(records, name)
    current_record = records[index]

    nonexistent_fields = set(changes) - set(current_record)
    if nonexistent_fields:
        raise KeyError(
            f"Cannot update nonexistent fields: "
            f"{sorted(nonexistent_fields)}"
        )

    updated_record = deepcopy(current_record)
    updated_record.update(changes)
    validate_record(updated_record)

    # If the name is changed, make sure the new name remains unique.
    new_name = updated_record["name"]
    if new_name != name and any(
        record.get("name") == new_name
        for record_index, record in enumerate(records)
        if record_index != index
    ):
        raise ValueError(
            f"Cannot rename record: {new_name!r} already exists."
        )

    # Assignment occurs only after all checks succeed.
    records[index] = updated_record


def delete_record(
    records: list[dict[str, Any]],
    name: str
) -> dict[str, Any]:
    """Delete one record by name and return the deleted record."""
    index = _find_record_index(records, name)
    return records.pop(index)


def enumerate_records(records: list[dict[str, Any]]) -> None:
    """Display every record and each of its constituent entries."""
    for index, record in enumerate(records):
        print(f"Record {index}:")
        for key, value in record.items():
            print(f"  {key}: {value}")


# ---------------------------------------------------------------------------
# Example usage
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    # Single dictionary CRUD
    print("Original dictionary:")
    enumerate_dictionary(dictionary)

    add_entry(dictionary, "occupation", "Engineer")
    print("\nAdded occupation:", get_entry(dictionary, "occupation"))

    update_entry(dictionary, "age", 21)
    print("Selected entries:", get_entries(dictionary, ["name", "age"]))

    removed_value = delete_entry(dictionary, "occupation")
    print("Deleted value:", removed_value)

    # List-of-dictionaries CRUD
    add_record(
        list_of_dictionaries,
        {
            "name": "Sam",
            "age": 24,
            "location": "Berlin"
        }
    )

    print("\nAlex's record:", get_record(list_of_dictionaries, "Alex"))
    print(
        "Records in Paris:",
        find_records(list_of_dictionaries, location="Paris")
    )

    update_record(
        list_of_dictionaries,
        "Liz",
        {"age": 29, "location": "Lyon"}
    )

    deleted_record = delete_record(list_of_dictionaries, "Sam")
    print("Deleted record:", deleted_record)

    print("\nFinal records:")
    enumerate_records(list_of_dictionaries)

    # Error-handling examples
    try:
        update_entry(dictionary, "salary", 50_000)
    except KeyError as error:
        print("\nHandled error:", error)

    try:
        get_record(list_of_dictionaries, "Nobody")
    except KeyError as error:
        print("Handled error:", error)

    try:
        add_record(
            list_of_dictionaries,
            {"name": "Alex", "age": 40, "location": "Boston"}
        )
    except ValueError as error:
        print("Handled error:", error)
```

The important safeguards are:

- `add_entry` and `add_record` reject duplicates.
- Read, update, and delete functions raise `KeyError` for nonexistent data.
- Record updates are validated before the stored record is changed.
- Names remain unique even when a record is renamed.
- Read functions return deep copies, preventing indirect mutation of stored data.
- Record validation rejects missing or invalid required fields.

Final answer: The supplied Python implementation provides validated Create, Read, Update, Delete, search, and enumeration operations for both the dictionary and the list of dictionaries.

### Java solution

```java
import java.util.ArrayList;
import java.util.List;

public class Solution {

    public static class ListNode {
        int val;
        ListNode next;

        public ListNode(int val) {
            this.val = val;
        }

        public ListNode(int val, ListNode next) {
            this.val = val;
            this.next = next;
        }
    }

    public List<ListNode> splitAndReverse(ListNode root, int k) {
        List<ListNode> parts = new ArrayList<>(k);

        // Determine the total number of nodes.
        int length = 0;
        for (ListNode node = root; node != null; node = node.next) {
            length++;
        }

        int minimumPartSize = length / k;
        int largerParts = length % k;

        ListNode current = root;

        for (int i = 0; i < k; i++) {
            // The first 'largerParts' parts receive one additional node.
            int partSize = minimumPartSize + (i < largerParts ? 1 : 0);

            ListNode reversedHead = null;

            // Reverse exactly partSize nodes.
            for (int j = 0; j < partSize; j++) {
                ListNode next = current.next;
                current.next = reversedHead;
                reversedHead = current;
                current = next;
            }

            // reversedHead is null when partSize is zero.
            parts.add(reversedHead);
        }

        return parts;
    }
}
```

### How it works

If the list has `n` nodes:

- Every part initially receives `n / k` nodes.
- The first `n % k` parts receive one additional node.
- Each part is reversed in place while being extracted.
- If `k > n`, the remaining parts have size zero and are represented by `null`.

For `n = 10` and `k = 3`, the part sizes are `4, 3, 3`, producing:

```text
[4 -> 3 -> 2 -> 1, 7 -> 6 -> 5, 10 -> 9 -> 8]
```

### Complexity

- Time: `O(n + k)`
- Auxiliary space: `O(k)` for the returned list; node reversal itself uses `O(1)` extra space.

### Erroneous code

```java
for (int j = 0; j < partSize; j++) {
    current.next = reversedHead;
    reversedHead = current;
    current = current.next; // Error
}
```

The error is that `current.next` is overwritten before the original next node is saved. Therefore, `current = current.next` follows the newly reversed pointer rather than advancing through the original list. On the first iteration it usually sets `current` to `null`, losing access to the remaining nodes.

The original next node must be saved first:

```java
ListNode next = current.next;
current.next = reversedHead;
reversedHead = current;
current = next;
```

Final answer: Compute balanced part sizes using division and remainder, then reverse exactly the assigned number of nodes for each of the `k` parts.

