Below is a complete C++17 program. The array size, thread count, and benchmark repetition count are supplied at runtime.

```cpp
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <limits>
#include <random>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

// Used to make each search result observable so an optimizing compiler cannot
// discard the benchmarked calls.
volatile std::size_t benchmarkSink = 0;

/*
 * Performs a conventional single-threaded linear search.
 *
 * Returning data.size() means that the target was not found.
 */
std::size_t singleThreadedSearch(const std::vector<int>& data, int target)
{
    for (std::size_t i = 0; i < data.size(); ++i) {
        if (data[i] == target) {
            return i;
        }
    }

    return data.size();
}

/*
 * Searches the array using several threads.
 *
 * The array is divided into contiguous, non-overlapping sections. Each thread
 * scans one section. "bestIndex" contains the smallest matching index found by
 * any thread.
 *
 * An atomic minimum operation is used instead of simply storing a result,
 * because a thread searching a later section may finish before a thread
 * searching an earlier section.
 *
 * Returning data.size() means that the target was not found.
 */
std::size_t multiThreadedSearch(const std::vector<int>& data,
                                int target,
                                std::size_t requestedThreadCount)
{
    const std::size_t n = data.size();

    if (n == 0) {
        return n;
    }

    // There is no benefit in creating more workers than array elements.
    const std::size_t workerCount =
        std::max<std::size_t>(1, std::min(requestedThreadCount, n));

    // Initially, no match has been found.
    std::atomic<std::size_t> bestIndex{n};

    std::vector<std::thread> workers;
    workers.reserve(workerCount);

    /*
     * Divide n elements as evenly as possible among workerCount threads.
     * The first remainder threads receive one additional element.
     *
     * This formulation avoids calculating n * threadIndex, which could
     * theoretically overflow for extremely large arrays.
     */
    const std::size_t elementsPerWorker = n / workerCount;
    const std::size_t remainder = n % workerCount;

    for (std::size_t threadIndex = 0;
         threadIndex < workerCount;
         ++threadIndex) {

        const std::size_t begin =
            threadIndex * elementsPerWorker +
            std::min(threadIndex, remainder);

        const std::size_t end =
            begin + elementsPerWorker +
            (threadIndex < remainder ? 1 : 0);

        workers.emplace_back([&, begin, end]() {
            for (std::size_t i = begin; i < end; ++i) {
                /*
                 * If another thread has already found a match at an index no
                 * greater than i, this thread cannot improve the answer.
                 */
                if (i >= bestIndex.load(std::memory_order_relaxed)) {
                    break;
                }

                if (data[i] == target) {
                    // Atomically replace bestIndex only when i is smaller.
                    std::size_t current =
                        bestIndex.load(std::memory_order_relaxed);

                    while (i < current &&
                           !bestIndex.compare_exchange_weak(
                               current,
                               i,
                               std::memory_order_relaxed,
                               std::memory_order_relaxed)) {
                        // On failure, compare_exchange_weak updates current
                        // with the latest value, so the condition is retried.
                    }

                    /*
                     * This is the first target in this thread's section,
                     * because the section is scanned from left to right.
                     */
                    break;
                }
            }
        });
    }

    // Joining ensures all workers finish before the result is returned.
    for (std::thread& worker : workers) {
        worker.join();
    }

    return bestIndex.load(std::memory_order_relaxed);
}

/*
 * Parses a non-negative command-line integer and verifies that it fits in
 * std::size_t.
 */
std::size_t parseSize(const char* text)
{
    const std::string input(text);
    std::size_t parsedCharacters = 0;
    const unsigned long long value =
        std::stoull(input, &parsedCharacters, 10);

    if (parsedCharacters != input.size()) {
        throw std::invalid_argument("not a valid non-negative integer");
    }

    if (value > std::numeric_limits<std::size_t>::max()) {
        throw std::out_of_range("value does not fit in size_t");
    }

    return static_cast<std::size_t>(value);
}

int main(int argc, char* argv[])
{
    if (argc < 2 || argc > 4) {
        std::cerr
            << "Usage: " << argv[0]
            << " <array-size> [thread-count] [repetitions]\n\n"
            << "Example:\n"
            << "  " << argv[0] << " 50000000 8 5\n";
        return 1;
    }

    try {
        // The array size is determined only at runtime.
        const std::size_t arraySize = parseSize(argv[1]);

        std::size_t threadCount = 0;
        if (argc >= 3) {
            threadCount = parseSize(argv[2]);
        }

        // A thread count of zero means "use the hardware recommendation."
        if (threadCount == 0) {
            threadCount = std::thread::hardware_concurrency();

            // hardware_concurrency() is permitted to return zero.
            if (threadCount == 0) {
                threadCount = 2;
            }
        }

        std::size_t repetitions = 5;
        if (argc >= 4) {
            repetitions = parseSize(argv[3]);
            if (repetitions == 0) {
                throw std::invalid_argument(
                    "repetitions must be greater than zero");
            }
        }

        std::cout << "Allocating " << arraySize << " integers...\n";
        std::vector<int> data(arraySize);

        /*
         * Generate values that cannot equal target. This guarantees that the
         * explicitly inserted target is its first and only occurrence.
         *
         * Array generation is intentionally outside the timed region.
         */
        constexpr int target = std::numeric_limits<int>::max();
        std::mt19937 generator(123456789);
        std::uniform_int_distribution<int> distribution(0, 1'000'000);

        for (int& value : data) {
            value = distribution(generator);
        }

        /*
         * Put the target near the end so both implementations have substantial
         * work to perform. For an empty array, the target remains absent.
         */
        if (!data.empty()) {
            data[(data.size() * 9) / 10] = target;
        }

        const std::size_t expectedIndex =
            singleThreadedSearch(data, target);

        // Warm up both implementations before collecting measurements.
        benchmarkSink = singleThreadedSearch(data, target);
        benchmarkSink =
            multiThreadedSearch(data, target, threadCount);

        using Clock = std::chrono::steady_clock;
        using Nanoseconds = std::chrono::nanoseconds;

        Nanoseconds singleTotal{0};
        Nanoseconds multiTotal{0};

        auto measureSingle = [&]() {
            const auto start = Clock::now();
            const std::size_t result =
                singleThreadedSearch(data, target);
            const auto finish = Clock::now();

            if (result != expectedIndex) {
                throw std::runtime_error(
                    "single-threaded search returned an incorrect result");
            }

            benchmarkSink = result;
            singleTotal +=
                std::chrono::duration_cast<Nanoseconds>(finish - start);
        };

        auto measureMulti = [&]() {
            const auto start = Clock::now();
            const std::size_t result =
                multiThreadedSearch(data, target, threadCount);
            const auto finish = Clock::now();

            if (result != expectedIndex) {
                throw std::runtime_error(
                    "multi-threaded search returned an incorrect result");
            }

            benchmarkSink = result;
            multiTotal +=
                std::chrono::duration_cast<Nanoseconds>(finish - start);
        };

        /*
         * Alternate measurement order to reduce bias caused by always running
         * one implementation first.
         *
         * Multi-threaded timing includes thread creation and joining, which
         * reflects the complete cost of making one search request.
         */
        for (std::size_t run = 0; run < repetitions; ++run) {
            if (run % 2 == 0) {
                measureSingle();
                measureMulti();
            } else {
                measureMulti();
                measureSingle();
            }
        }

        const double singleMilliseconds =
            static_cast<double>(singleTotal.count()) /
            static_cast<double>(repetitions) / 1'000'000.0;

        const double multiMilliseconds =
            static_cast<double>(multiTotal.count()) /
            static_cast<double>(repetitions) / 1'000'000.0;

        std::cout << "\nSearch result: ";
        if (expectedIndex == data.size()) {
            std::cout << "target not found\n";
        } else {
            std::cout << "target found at index "
                      << expectedIndex << '\n';
        }

        std::cout << "Array size:        " << data.size() << '\n'
                  << "Worker threads:    "
                  << std::min(threadCount,
                              std::max<std::size_t>(data.size(), 1))
                  << '\n'
                  << "Repetitions:       " << repetitions << '\n'
                  << std::fixed << std::setprecision(3)
                  << "Single-thread avg: " << singleMilliseconds
                  << " ms\n"
                  << "Multi-thread avg:  " << multiMilliseconds
                  << " ms\n";

        if (multiMilliseconds > 0.0) {
            std::cout << "Speedup:           "
                      << singleMilliseconds / multiMilliseconds
                      << "x\n";
        }

        std::cout
            << "\nNote: For small arrays, thread creation and synchronization "
               "overhead may make\n"
            << "the multi-threaded version slower than the single-threaded "
               "version.\n";
    } catch (const std::exception& exception) {
        std::cerr << "Error: " << exception.what() << '\n';
        return 1;
    }

    return 0;
}
