`RT_RCDATA` is a Win32 resource type (numeric value `10`), not a PE section. You can extract it using the resource APIs: `LoadLibraryEx`, `FindResource`, `LoadResource`, `SizeofResource`, and `LockResource`.

```csharp
using System;
using System.ComponentModel;
using System.IO;
using System.Runtime.InteropServices;

public static class Win32Resources
{
    private const int RT_RCDATA = 10;

    // Loads the file without executing its initialization code.
    private const uint LOAD_LIBRARY_AS_DATAFILE = 0x00000002;

    public static byte[] ExtractRcData(string executablePath, int resourceId)
    {
        if (executablePath == null)
            throw new ArgumentNullException(nameof(executablePath));

        if (resourceId < 0 || resourceId > ushort.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(resourceId));

        string fullPath = Path.GetFullPath(executablePath);

        IntPtr module = LoadLibraryEx(
            fullPath,
            IntPtr.Zero,
            LOAD_LIBRARY_AS_DATAFILE);

        if (module == IntPtr.Zero)
            throw new Win32Exception(Marshal.GetLastWin32Error());

        try
        {
            // MAKEINTRESOURCE(resourceId) is represented by an IntPtr whose
            // low 16 bits contain the resource ID.
            IntPtr resourceInfo = FindResource(
                module,
                new IntPtr(resourceId),
                new IntPtr(RT_RCDATA));

            if (resourceInfo == IntPtr.Zero)
                throw new Win32Exception(Marshal.GetLastWin32Error());

            uint size = SizeofResource(module, resourceInfo);
            if (size == 0)
                throw new Win32Exception(Marshal.GetLastWin32Error());

            IntPtr resourceData = LoadResource(module, resourceInfo);
            if (resourceData == IntPtr.Zero)
                throw new Win32Exception(Marshal.GetLastWin32Error());

            IntPtr resourcePointer = LockResource(resourceData);
            if (resourcePointer == IntPtr.Zero)
                throw new Win32Exception(Marshal.GetLastWin32Error());

            int length = checked((int)size);
            byte[] bytes = new byte[length];
            Marshal.Copy(resourcePointer, bytes, 0, length);
            return bytes;
        }
        finally
        {
            FreeLibrary(module);
        }
    }

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr LoadLibraryEx(
        string lpFileName,
        IntPtr hFile,
        uint dwFlags);

    [DllImport("kernel32.dll", EntryPoint = "FindResourceW",
        SetLastError = true)]
    private static extern IntPtr FindResource(
        IntPtr hModule,
        IntPtr lpName,
        IntPtr lpType);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr LoadResource(
        IntPtr hModule,
        IntPtr hResInfo);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint SizeofResource(
        IntPtr hModule,
        IntPtr hResInfo);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr LockResource(IntPtr hResData);

    [DllImport("kernel32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool FreeLibrary(IntPtr hModule);
}
```

Usage:

```csharp
byte[] data = Win32Resources.ExtractRcData(
    @"C:\Path\Application.exe",
    resourceId: 101);

File.WriteAllBytes(@"C:\Path\resource.bin", data);
```

If the resource has a textual name rather than a numeric ID, declare another `FindResourceW` overload whose `lpName` parameter is a Unicode `string`:

```csharp
