    const API_URL = "https://jsonplaceholder.typicode.com/comments";

    const commentsElement = document.getElementById("comments");
    const statusElement = document.getElementById("status");
    const searchInput = document.getElementById("searchInput");
    const reloadButton = document.getElementById("reloadButton");

    let comments = [];

    function createCommentCard(comment) {
      const article = document.createElement("article");
      article.className = "comment";

      const title = document.createElement("h2");
      title.textContent = comment.name;

      const email = document.createElement("a");
      email.href = `mailto:${comment.email}`;
      email.textContent = comment.email;

      const body = document.createElement("p");
      body.textContent = comment.body;

      article.append(title, email, body);
      return article;
    }

    function renderComments(items) {
      commentsElement.replaceChildren();

      if (items.length === 0) {
        statusElement.textContent = "No comments found.";
        return;
      }

      statusElement.textContent =
        `Showing ${items.length} of ${comments.length} comments.`;

      const fragment = document.createDocumentFragment();

      for (const comment of items) {
        fragment.appendChild(createCommentCard(comment));
      }

      commentsElement.appendChild(fragment);
    }

    function filterComments() {
      const query = searchInput.value.trim().toLowerCase();

      if (!query) {
        renderComments(comments);
        return;
      }

      const filteredComments = comments.filter((comment) => {
        return (
          comment.name.toLowerCase().includes(query) ||
          comment.email.toLowerCase().includes(query) ||
          comment.body.toLowerCase().includes(query)
        );
      });

      renderComments(filteredComments);
    }

    async function fetchComments() {
      reloadButton.disabled = true;
      searchInput.disabled = true;
      statusElement.className = "";
      statusElement.textContent = "Loading comments...";
      commentsElement.replaceChildren();

      try {
        const response = await fetch(API_URL);

        if (!response.ok) {
          throw new Error(
            `Request failed with status ${response.status}`
          );
        }

        const data = await response.json();

        if (!Array.isArray(data)) {
          throw new Error("The API returned an unexpected response.");
        }

        comments = data;
        filterComments();
      } catch (error) {
        comments = [];
        statusElement.className = "error";
        statusElement.textContent =
          `Unable to load comments: ${error.message}`;
      } finally {
        reloadButton.disabled = false;
        searchInput.disabled = false;
      }
    }

    searchInput.addEventListener("input", filterComments);
    reloadButton.addEventListener("click", fetchComments);

    fetchComments();
  </script>
</body>
</html>
```

Outlook’s Import/Export wizard is not exposed through the Outlook Object Model, but the equivalent operation can be automated: open each shared default Calendar with `GetSharedDefaultFolder`, then copy it into a PST.

Add a COM reference to **Microsoft Outlook xx.x Object Library**, then use code similar to this:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using Outlook = Microsoft.Office.Interop.Outlook;

public static class SharedCalendarExporter
{
    public static void ExportToPst(
        string pstFile,
        IEnumerable<string> mailboxNamesOrAddresses)
    {
        pstFile = Path.GetFullPath(pstFile);

        var outlook = new Outlook.Application();
        Outlook.NameSpace session = outlook.Session;

        // Attach/create a Unicode PST.
        session.AddStoreEx(
            pstFile,
            Outlook.OlStoreType.olStoreUnicode);

        Outlook.Store pstStore = FindStore(session, pstFile);
        if (pstStore == null)
            throw new InvalidOperationException("The export PST could not be opened.");

        Outlook.Folder pstRoot =
            (Outlook.Folder)pstStore.GetRootFolder();

        // A separate parent avoids the "Calendar" name collision when
        // several default calendar folders are copied.
        Outlook.Folder exportRoot =
            (Outlook.Folder)pstRoot.Folders.Add("Shared Calendar Exports");

        foreach (string mailbox in mailboxNamesOrAddresses)
        {
            Outlook.Recipient recipient = session.CreateRecipient(mailbox);

            if (!recipient.Resolve())
            {
                Console.WriteLine("Could not resolve: " + mailbox);
                continue;
            }

            try
            {
                Outlook.MAPIFolder sourceCalendar =
                    session.GetSharedDefaultFolder(
                        recipient,
                        Outlook.OlDefaultFolders.olFolderCalendar);

                string parentName = MakeFolderName(
                    recipient.AddressEntry?.Name ?? mailbox);

                Outlook.MAPIFolder mailboxParent =
                    exportRoot.Folders.Add(parentName);

                // Copies the folder and its calendar items, including
                // recurring appointment masters, into the PST.
                Outlook.MAPIFolder copiedCalendar =
                    sourceCalendar.CopyTo(mailboxParent);

                Console.WriteLine("Exported: " + mailbox);
            }
            catch (Exception ex)
            {
                Console.WriteLine(
                    $"Could not export {mailbox}: {ex.Message}");
            }
        }

        // Flush changes and detach the PST.
        session.RemoveStore(pstRoot);
    }

    private static Outlook.Store FindStore(
        Outlook.NameSpace session,
        string pstFile)
    {
        for (int i = 1; i <= session.Stores.Count; i++)
        {
            Outlook.Store store = session.Stores[i];

            try
            {
                if (!string.IsNullOrEmpty(store.FilePath) &&
                    string.Equals(
                        Path.GetFullPath(store.FilePath),
                        pstFile,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return store;
                }
            }
            catch
            {
                // Some store types do not provide a usable FilePath.
            }
        }

        return null;
    }

    private static string MakeFolderName(string value)
    {
        foreach (char c in new[] { '\\', '/', ':', '*', '?', '"', '<', '>', '|' })
            value = value.Replace(c, '_');

        return value;
    }
}
```

Example:

```csharp
SharedCalendarExporter.ExportToPst(
    @"C:\Exports\SharedCalendars.pst",
    new[]
    {
        "user1@example.com",
        "user2@example.com",
        "Meeting Room 101"
    });
```

Important limitations:

- The logged-in Outlook profile must have permission to read every calendar.
- `GetSharedDefaultFolder` accesses the mailbox’s **default** Calendar. Additional calendar subfolders require separate folder traversal or Exchange Web Services.
- Outlook Interop must run in an interactive Windows user session. Microsoft does not support Outlook automation from an ASP.NET application, Windows service, or other unattended server process.
- For an unattended/server-side exporter, use Exchange Web Services for supported on-premises Exchange versions, or Microsoft Graph for Exchange Online. Those APIs can enumerate calendar items, but producing a PST requires a separate PST/MAPI library.
- If the desired format is individual `.ics` files rather than a PST, each `AppointmentItem` can be written with `SaveAs(path, Outlook.OlSaveAsType.olICal)`, although that creates one file per appointment rather than a complete PST-style calendar export.

Final answer: Automate Outlook with `GetSharedDefaultFolder` and `MAPIFolder.CopyTo` to copy each shared calendar into a Unicode PST; use EWS or Microsoft Graph instead if the process must run unattended.

The following pseudocode assumes IEEE-754 floating-point components and accepts values represented as a complex type with finite real and imaginary parts.

```text
function complexProduct(values):
    if values is not an array:
        return Error("Invalid input: expected an array of complex numbers")

    # Validate the complete array before using a zero shortcut.
    for z in values:
        if z is not a complex number:
            return Error("Invalid input: every element must be a complex number")
        if not isFinite(z.real) or not isFinite(z.imag):
            return Error("Precision error: a component is not finite")

    # The product of an empty array is the multiplicative identity.
    if length(values) == 0:
        return Success(1 + 0i)

    # Any complex number with both components zero is zero.
    for z in values:
        if z.real == 0 and z.imag == 0:
            return Success(0 + 0i)

    result = 1 + 0i
    MAX = largestFiniteFloatingPointNumber()

    for z in values:
        a = result.real
        b = result.imag
        c = z.real
        d = z.imag

        # (a + bi)(c + di) = (ac - bd) + (ad + bc)i.
        # Check every intermediate multiplication conservatively.
        if multiplicationWouldOverflow(a, c, MAX) or
           multiplicationWouldOverflow(b, d, MAX) or
           multiplicationWouldOverflow(a, d, MAX) or
           multiplicationWouldOverflow(b, c, MAX):
            return Error("Precision error: complex product overflow")

        ac = a * c
        bd = b * d
        ad = a * d
        bc = b * c

        realPart = ac - bd
        imagPart = ad + bc

        # This detects overflow during addition or subtraction.
        if not isFinite(realPart) or not isFinite(imagPart):
            return Error("Precision error: complex product overflow")

        result = realPart + imagPart * i

    return Success(result)


function multiplicationWouldOverflow(x, y, MAX):
    if x == 0 or y == 0:
        return false
    return abs(x) > MAX / abs(y)
```

Negative real or imaginary components require no special handling because the standard complex multiplication formula handles their signs naturally. The algorithm uses \(O(n)\) time and \(O(1)\) auxiliary space.

Final answer: Validate all finite complex elements, return \(0+0i\) if any element is zero, otherwise multiply sequentially with checked intermediate operations and return a precision-error message whenever an operation could overflow.

## 1. Java exception hierarchy

All Java exceptions and errors derive from `Throwable`:

```text
Throwable
├── Error
└── Exception
    ├── RuntimeException
    └── other checked exceptions
```

### Checked exceptions

Checked exceptions are verified by the compiler. A method must either:

1. Catch the exception, or
2. Declare it using `throws`.

Examples include `IOException`, `SQLException`, and `ClassNotFoundException`.

```java
public String readFile(Path path) throws IOException {
    return Files.readString(path);
}
```

Checked exceptions are generally appropriate when the caller can reasonably recover, retry, choose another resource, or report a meaningful failure.

### Unchecked exceptions

`RuntimeException` and its subclasses are unchecked. They do not have to be caught or declared.

Examples include:

- `IllegalArgumentException`
- `IllegalStateException`
- `NullPointerException`
- `IndexOutOfBoundsException`

Unchecked exceptions commonly represent programming errors, invalid API arguments, or violated object invariants.

### Errors

`Error` represents serious JVM or environment problems, such as `OutOfMemoryError`. Applications generally should not catch `Error` or `Throwable`, because they usually cannot recover safely.

---

## 2. Basic `try-catch-finally` processing

The general form is:

```java
try {
    // Code that may throw an exception
} catch (SpecificException e) {
    // Handle that exception
} catch (AnotherException e) {
    // Handle another exception
} finally {
    // Cleanup that should happen whether or not an exception occurred
}
```

The execution process is:

1. Java executes the `try` block.
2. If no exception is thrown, all `catch` blocks are skipped.
3. If an exception is thrown, Java looks for the first compatible `catch` block.
4. The remainder of the `try` block is skipped.
5. The matching `catch` block executes.
6. The `finally` block executes after the `try` or `catch` block.
7. If there is no matching `catch`, the exception propagates after `finally` executes.

Example:

```java
try {
    int value = Integer.parseInt(input);
    System.out.println(100 / value);
} catch (NumberFormatException e) {
    System.err.println("The input is not a valid integer.");
} catch (ArithmeticException e) {
    System.err.println("Zero cannot be used as the divisor.");
} finally {
    System.out.println("Processing finished.");
}
```

---

## 3. Handling multiple exceptions

### Separate `catch` blocks

Use separate blocks when each exception requires different handling.

```java
try {
    String text = Files.readString(path);
    int value = Integer.parseInt(text.trim());
    process(value);
} catch (NoSuchFileException e) {
    System.err.println("The requested file does not exist: " + e.getFile());
} catch (IOException e) {
    System.err.println("The file could not be read: " + e.getMessage());
} catch (NumberFormatException e) {
    System.err.println("The file does not contain a valid integer.");
}
```

Catch blocks must be ordered from the most specific exception to the most general exception. This is valid:

```java
catch (NoSuchFileException e) {
    // NoSuchFileException is a subclass of IOException
} catch (IOException e) {
    // Other I/O exceptions
}
```

This is invalid because the second block is unreachable:

```java
catch (IOException e) {
    // Catches NoSuchFileException too
} catch (NoSuchFileException e) {
    // Compile-time error: unreachable
}
```

### Multi-catch

When several exceptions require identical handling, use the `|` operator:

```java
try {
    loadAndParseConfiguration();
} catch (IOException | NumberFormatException e) {
    System.err.println("Configuration could not be loaded: " + e.getMessage());
}
```

The alternatives in a multi-catch cannot have a subclass relationship. For example, this is illegal:

```java
catch (IOException | NoSuchFileException e) {
    // Illegal because NoSuchFileException extends IOException
}
```

A multi-catch variable is effectively final and cannot be reassigned.

### Catching a common superclass

Exceptions can also be caught through a common superclass:

```java
try {
    performOperation();
} catch (Exception e) {
    handleFailure(e);
}
```

However, catching `Exception` broadly should normally be limited to application boundaries such as request handlers, job runners, or top-level threads. Within business logic, specific catches make error handling clearer and avoid hiding unrelated defects.

---

## 4. Using `finally` correctly

A `finally` block is intended for cleanup:

```java
Lock lock = obtainLock();
lock.lock();

try {
    updateSharedState();
} finally {
    lock.unlock();
}
```

`finally` normally executes when:

- The `try` block completes normally
- A `catch` block completes normally
- An exception is thrown
- The method executes `return`, `break`, or `continue`

It may not execute if the JVM terminates abruptly—for example, because of `System.exit`, a JVM crash, or forced process termination.

Do not return from `finally`:

```java
try {
    return calculate();
} finally {
    return 0; // Bad: overrides the original return value
}
```

Do not deliberately throw from `finally` unless unavoidable. A new exception thrown by `finally` can replace and hide the original exception:

```java
try {
    riskyOperation();
} finally {
    cleanupThatThrows(); // May obscure the original failure
}
```

---

## 5. Prefer try-with-resources for closeable resources

Objects implementing `AutoCloseable`, including files, streams, JDBC connections, statements, and result sets, should normally be managed with try-with-resources:

```java
public List<String> readLines(Path path) throws IOException {
    try (BufferedReader reader = Files.newBufferedReader(path)) {
        return reader.lines().toList();
    }
}
```

Resources are closed automatically in reverse declaration order:

```java
try (
    InputStream input = Files.newInputStream(source);
    OutputStream output = Files.newOutputStream(target)
) {
    input.transferTo(output);
}
```

If the main operation and `close()` both throw exceptions, try-with-resources preserves the main exception and attaches closing failures as suppressed exceptions:

```java
catch (IOException e) {
    for (Throwable suppressed : e.getSuppressed()) {
        System.err.println("Cleanup failure: " + suppressed);
    }
    throw e;
}
```

This is safer than manually calling `close()` in `finally`.

---

## 6. Propagating exceptions

An exception propagates when the current method does not catch it or catches and rethrows it. During propagation, Java unwinds the call stack until it finds a matching handler. Relevant `finally` blocks and resource-closing operations run during stack unwinding.

### Declaring checked exceptions

```java
public String load(Path path) throws IOException {
    return Files.readString(path);
}
```

The caller must catch or further declare the exception:

```java
public void start(Path path) {
    try {
        String data = load(path);
        System.out.println(data);
    } catch (IOException e) {
        System.err.println("Startup data could not be loaded.");
    }
}
```

Alternatively:

```java
public void start(Path path) throws IOException {
    String data = load(path);
    System.out.println(data);
}
```

Unchecked exceptions can propagate without a `throws` declaration, although documenting significant unchecked exceptions may still be useful.

### Rethrowing the same exception

A method may perform limited handling and then rethrow:

```java
public void importData(Path path) throws IOException {
    try {
        performImport(path);
    } catch (IOException e) {
        recordImportFailure(path, e);
        throw e;
    }
}
```

Avoid logging the same exception at every layer. Usually, either add useful context and propagate it or log it at the layer that finally handles it. Repeated “log and throw” behavior creates duplicate logs.

### Wrapping and exception chaining

A lower-level exception can be translated into an exception meaningful to the current abstraction:

```java
public Customer loadCustomer(long id) {
    try {
        return repository.findById(id);
    } catch (SQLException e) {
        throw new CustomerAccessException(
            "Could not load customer " + id, e
        );
    }
}
```

Passing `e` as the cause preserves the original stack trace and diagnostic information.

Do not discard the cause:

```java
throw new CustomerAccessException("Load failed"); // Loses original cause
```

Use:

```java
throw new CustomerAccessException("Load failed", e);
```

When overriding a method, an overriding method cannot add broader checked exceptions than the overridden method declares. It may declare narrower checked exceptions or unchecked exceptions.

---

## 7. Creating custom exceptions

A custom checked exception extends `Exception`:

```java
public class InvalidOrderException extends Exception {
    private static final long serialVersionUID = 1L;

    public InvalidOrderException(String message) {
        super(message);
    }

    public InvalidOrderException(String message, Throwable cause) {
        super(message, cause);
    }

    public InvalidOrderException(Throwable cause) {
        super(cause);
    }
}
```

Usage:

```java
public void submit(Order order) throws InvalidOrderException {
    if (order == null) {
        throw new InvalidOrderException("Order must not be null");
    }

    if (order.items().isEmpty()) {
        throw new InvalidOrderException("Order must contain at least one item");
    }
}
```

The caller must catch or declare it:

```java
try {
    orderService.submit(order);
} catch (InvalidOrderException e) {
    showValidationMessage(e.getMessage());
}
```

A custom unchecked exception extends `RuntimeException`:

```java
public class CustomerAccessException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public CustomerAccessException(String message) {
        super(message);
    }

    public CustomerAccessException(String message, Throwable cause) {
        super(message, cause);
    }
}
```

Use a checked custom exception when callers are expected to handle the condition explicitly. Use an unchecked custom exception when the failure represents an invalid call, an illegal state, an invariant violation, or a condition callers usually cannot recover from locally.

Custom exceptions may contain structured data:

```java
public class InsufficientFundsException extends Exception {
    private static final long serialVersionUID = 1L;

    private final BigDecimal available;
    private final BigDecimal requested;

    public InsufficientFundsException(
            BigDecimal available,
            BigDecimal requested) {
        super("Insufficient funds: available=" + available
                + ", requested=" + requested);
        this.available = available;
        this.requested = requested;
    }

    public BigDecimal getAvailable() {
        return available;
    }

    public BigDecimal getRequested() {
        return requested;
    }
}
```

Keep custom exceptions focused. They should communicate a meaningful domain or API failure, not merely rename every standard Java exception.

---

## 8. Complete handling and propagation example

```java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;

class ConfigurationException extends Exception {
    private static final long serialVersionUID = 1L;

    ConfigurationException(String message, Throwable cause) {
        super(message, cause);
    }
}

public class ConfigurationService {

    public int loadPort(Path path) throws ConfigurationException {
        try {
            String text = Files.readString(path);
            int port = Integer.parseInt(text.trim());

            if (port < 1 || port > 65535) {
                throw new ConfigurationException(
                    "Port must be between 1 and 65535", null
                );
            }

            return port;
        } catch (NoSuchFileException e) {
            throw new ConfigurationException(
                "Configuration file does not exist: " + path, e
            );
        } catch (IOException e) {
            throw new ConfigurationException(
                "Could not read configuration file: " + path, e
            );
        } catch (NumberFormatException e) {
            throw new ConfigurationException(
                "Configuration does not contain a valid port number", e
            );
        }
    }

    public static void main(String[] args) {
        ConfigurationService service = new ConfigurationService();

        try {
            int port = service.loadPort(Path.of("port.txt"));
            System.out.println("Using port " + port);
        } catch (ConfigurationException e) {
            System.err.println(e.getMessage());

            if (e.getCause() != null) {
                System.err.println("Cause: " + e.getCause());
            }
        } finally {
            System.out.println("Configuration attempt completed.");
        }
    }
}
```

This example:

- Catches specific low-level exceptions
- Orders subclass catches before superclass catches
- Translates implementation details into a domain-level exception
- Preserves original causes
- Propagates the custom checked exception
- Handles it at the application boundary
- Uses `finally` for unconditional completion behavior

---

## 9. Practical exception-handling guidelines

1. **Catch only exceptions you can meaningfully handle.** Otherwise, let them propagate.
2. **Catch the most specific exception possible.**
3. **Do not use empty catch blocks.**
4. **Do not use exceptions for normal control flow.**
5. **Use meaningful messages with relevant context**, such as an operation or resource identifier.
6. **Do not include passwords, tokens, personal data, or other sensitive information** in exception messages or logs.
7. **Preserve causes when translating exceptions.**
8. **Prefer try-with-resources** over manual resource cleanup.
9. **Avoid `return`, `break`, `continue`, or new exceptions in `finally`.**
10. **Avoid catching `Throwable` or `Error`** unless implementing specialized infrastructure with a clear recovery policy.
11. **Avoid indiscriminately catching `RuntimeException`**, because doing so can hide programming defects.
12. **Maintain consistent program state.** Roll back transactions or undo partial updates when an operation fails.
13. **Document exceptions that form part of a public API**, including important unchecked exceptions.
14. **Log at the correct boundary.** Avoid logging and rethrowing at every layer.
15. **Preserve thread interruption.** If `InterruptedException` cannot be propagated, restore the interrupt status:

```java
try {
    Thread.sleep(1000);
} catch (InterruptedException e) {
    Thread.currentThread().interrupt();
    return;
}
```

Well-designed Java exception handling separates recovery from propagation: expected recoverable failures are handled near code that can resolve them, while other failures are translated with their causes preserved and propagated to an appropriate application boundary.

