function createHTMLPage(
  title,
  noOfParagraphs,
  paragraphContents,
  noOfHeaders,
  headerTexts
) {
  if (!Number.isInteger(noOfParagraphs) || noOfParagraphs < 0) {
    throw new TypeError("noOfParagraphs must be a non-negative integer.");
  }

  if (!Number.isInteger(noOfHeaders) || noOfHeaders < 0) {
    throw new TypeError("noOfHeaders must be a non-negative integer.");
  }

  if (!Array.isArray(paragraphContents) ||
      paragraphContents.length < noOfParagraphs) {
    throw new RangeError(
      "paragraphContents must contain at least noOfParagraphs items."
    );
  }

  if (!Array.isArray(headerTexts) || headerTexts.length < noOfHeaders) {
    throw new RangeError(
      "headerTexts must contain at least noOfHeaders items."
    );
  }

  const page = window.open("", "_blank");

  if (!page) {
    throw new Error("The new page could not be opened. Check popup settings.");
  }

  const doc = page.document;

  doc.open();
  doc.write(
    "<!DOCTYPE html>" +
    "<html>" +
    "<head><meta charset='UTF-8'><title></title></head>" +
    "<body></body>" +
    "</html>"
  );
  doc.close();

  // textContent prevents the supplied values from being interpreted as HTML.
  doc.title = String(title);

  for (let i = 0; i < noOfHeaders; i++) {
    const heading = doc.createElement("h2");
    heading.id = `header-${i + 1}`;
    heading.textContent = String(headerTexts[i]);
    doc.body.appendChild(heading);
  }

