    const paragraph = doc.createElement("p");
    paragraph.id = `paragraph-${i + 1}`;
    paragraph.textContent = String(paragraphContents[i]);
    doc.body.appendChild(paragraph);
  }

  // Return the new window so its elements can be referenced later.
  return page;
}

