Assuming you meant **JavaScript**, here is a dependency-free command-line JSON formatter, validator, minifier, and key sorter.

Save as `json-tool.js`:

```javascript
#!/usr/bin/env node

"use strict";

const fs = require("node:fs");

const HELP = `
JSON Tool — format, validate, minify, or sort JSON

Usage:
  node json-tool.js [file] [options]
  cat data.json | node json-tool.js [options]

Arguments:
  file                 JSON file to process. Use "-" or omit it for stdin.

Options:
  -m, --minify         Remove unnecessary whitespace.
  -s, --sort           Sort object keys recursively.
  -c, --check          Only validate; produce no output.
  -i, --indent <0-10>  Number of spaces used for formatting (default: 2).
  -h, --help           Show this help message.

Examples:
  node json-tool.js data.json
  node json-tool.js data.json --sort --indent 4
  node json-tool.js data.json --minify
  node json-tool.js data.json --check
  cat data.json | node json-tool.js --sort
`.trim();

function parseArguments(args) {
  const options = {
    filename: null,
    indent: 2,
    sort: false,
    check: false,
  };

  let stopParsingOptions = false;

  for (let i = 0; i < args.length; i++) {
    const argument = args[i];

    if (!stopParsingOptions && argument === "--") {
      stopParsingOptions = true;
      continue;
    }

    if (!stopParsingOptions && (argument === "-h" || argument === "--help")) {
      options.help = true;
      continue;
    }

    if (!stopParsingOptions && (argument === "-m" || argument === "--minify")) {
      options.indent = 0;
      continue;
    }

    if (!stopParsingOptions && (argument === "-s" || argument === "--sort")) {
      options.sort = true;
      continue;
    }

    if (!stopParsingOptions && (argument === "-c" || argument === "--check")) {
      options.check = true;
      continue;
    }

    if (!stopParsingOptions && (argument === "-i" || argument === "--indent")) {
      if (i + 1 >= args.length) {
        throw new Error(`${argument} requires a number.`);
      }

      options.indent = parseIndent(args[++i]);
      continue;
    }

    if (!stopParsingOptions && argument.startsWith("--indent=")) {
      options.indent = parseIndent(argument.slice("--indent=".length));
      continue;
    }

    if (
      !stopParsingOptions &&
      argument.startsWith("-") &&
      argument !== "-"
    ) {
      throw new Error(`Unknown option: ${argument}`);
    }

    if (options.filename !== null) {
      throw new Error("Only one input file may be specified.");
    }

    options.filename = argument;
  }

  return options;
}

function parseIndent(value) {
  const indent = Number(value);

  if (!Number.isInteger(indent) || indent < 0 || indent > 10) {
    throw new Error("Indent must be an integer from 0 through 10.");
  }

  return indent;
}

function sortKeys(value) {
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }

  if (value !== null && typeof value === "object") {
    const sortedObject = Object.create(null);

    for (const key of Object.keys(value).sort()) {
      sortedObject[key] = sortKeys(value[key]);
    }

    return sortedObject;
  }

  return value;
}

function describeJsonError(error, source) {
  const message = error instanceof Error ? error.message : String(error);
  const positionMatch = message.match(/position\s+(\d+)/i);

  if (!positionMatch) {
    return message;
  }

  const position = Number(positionMatch[1]);
  const precedingText = source.slice(0, position);
  const lines = precedingText.split(/\r\n|\r|\n/);
  const line = lines.length;
  const column = lines[lines.length - 1].length + 1;

  return `${message} (line ${line}, column ${column})`;
}

function readInput(filename) {
  if (filename === null || filename === "-") {
    if (process.stdin.isTTY) {
      throw new Error("No input supplied. Provide a file or pipe JSON to stdin.");
    }

    return fs.readFileSync(0, "utf8");
  }

  return fs.readFileSync(filename, "utf8");
}

function main() {
  const options = parseArguments(process.argv.slice(2));

  if (options.help) {
    console.log(HELP);
    return;
  }

  let source;

  try {
    source = readInput(options.filename).replace(/^\uFEFF/, "");
  } catch (error) {
    throw new Error(`Could not read input: ${error.message}`);
  }

  let data;

  try {
    data = JSON.parse(source);
  } catch (error) {
    throw new Error(`Invalid JSON: ${describeJsonError(error, source)}`);
  }

  if (options.check) {
    return;
  }

  if (options.sort) {
    data = sortKeys(data);
  }

  const output = JSON.stringify(data, null, options.indent);
  process.stdout.write(`${output}\n`);
}

try {
  main();
} catch (error) {
  console.error(`Error: ${error.message}`);
  process.exitCode = 1;
}
```

Run it with:

```bash
node json-tool.js input.json --sort --indent 4
```

Or make it executable on macOS/Linux:

```bash
chmod +x json-tool.js
./json-tool.js input.json --minify
```

You can integrate PayPal without a WordPress plugin in two ways.

## Option 1: Embed a PayPal-hosted button

This is the easiest and safest approach for fixed-price products, donations, or simple payments.

1. Sign in to your PayPal Business account.
2. Open **Pay Links and Buttons** or the PayPal button builder.
3. Create a payment button and configure its:
   - Product or donation type
   - Price
   - Currency
   - Shipping and tax settings
   - Return URL
4. Copy the HTML/JavaScript generated by PayPal.
5. In WordPress, edit the relevant page and add a **Custom HTML** block.
6. Paste the generated code and publish the page.

A modern hosted-button embed generally resembles this, but use the exact code PayPal provides:

```html
<script
  src="https://www.paypal.com/sdk/js?client-id=YOUR_PUBLIC_CLIENT_ID&components=hosted-buttons&currency=USD">
</script>

<div id="paypal-button-container"></div>

<script>
  paypal.HostedButtons({
    hostedButtonId: "YOUR_HOSTED_BUTTON_ID"
  }).render("#paypal-button-container");
</script>
```

Do not replace PayPal’s generated values unless you know the corresponding settings in your PayPal account.

If WordPress removes the `<script>` tags, add the code to a child-theme template instead, or load the script through the child theme’s `functions.php`.

## Option 2: Build a custom PayPal Checkout integration

Use this for dynamic prices, shopping carts, subscriptions, or when payments must be connected to WordPress users or orders.

### 1. Create a PayPal REST application

Go to the [PayPal Developer Dashboard](https://developer.paypal.com/dashboard/applications/) and create an application. You will receive:

- A public **Client ID**
- A private **Client Secret**
- Separate credentials for Sandbox and Live environments

The Client ID may be placed in browser code. The Client Secret must remain on the server.

### 2. Store credentials outside public page code

For example, add them to `wp-config.php`, preferably obtaining the actual values from environment variables:

```php
define('PAYPAL_ENVIRONMENT', 'sandbox');
define('PAYPAL_CLIENT_ID', getenv('PAYPAL_CLIENT_ID'));
define('PAYPAL_CLIENT_SECRET', getenv('PAYPAL_CLIENT_SECRET'));
```

Change `sandbox` to `live` only after testing.

### 3. Add the PayPal JavaScript SDK

In a child theme’s `functions.php`:

```php
function mysite_enqueue_paypal_sdk() {
    $url = add_query_arg(
        array(
            'client-id' => PAYPAL_CLIENT_ID,
            'currency'  => 'USD',
            'components' => 'buttons',
        ),
        'https://www.paypal.com/sdk/js'
    );

    wp_enqueue_script(
        'paypal-sdk',
        $url,
        array(),
        null,
        true
    );
}
add_action('wp_enqueue_scripts', 'mysite_enqueue_paypal_sdk');
```

Then place a container in the relevant child-theme template:

```html
<div id="paypal-button-container"></div>
<div id="paypal-payment-message" aria-live="polite"></div>
```

### 4. Create and capture orders on the server

The browser should call WordPress REST endpoints that:

1. Obtain an OAuth access token from PayPal.
2. Create an order using PayPal’s `/v2/checkout/orders` endpoint.
3. Return the PayPal order ID to the browser.
4. Capture the approved order on the server.
5. Verify that the capture is completed before fulfilling the purchase.

The browser-side button logic will look similar to:

```html
<script>
paypal.Buttons({
    createOrder: async function () {
        const response = await fetch('/wp-json/mysite-paypal/v1/order', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        const order = await response.json();

        if (!response.ok || !order.id) {
            throw new Error(order.message || 'Unable to create PayPal order.');
        }

        return order.id;
    },

    onApprove: async function (data) {
        const response = await fetch(
            '/wp-json/mysite-paypal/v1/order/' +
            encodeURIComponent(data.orderID) +
            '/capture',
            {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                }
            }
        );

        const capture = await response.json();

        if (!response.ok || capture.status !== 'COMPLETED') {
            throw new Error(capture.message || 'Payment could not be captured.');
        }

        document.getElementById('paypal-payment-message').textContent =
            'Payment completed successfully.';
    },

    onError: function () {
        document.getElementById('paypal-payment-message').textContent =
            'The payment could not be completed.';
    }
}).render('#paypal-button-container');
</script>
```

Do not calculate or trust the payment amount in this JavaScript. A user can modify browser code. The server must determine the product, amount, currency, taxes, and shipping independently.

## Production requirements

For a custom integration:

- Use HTTPS.
- Never expose the Client Secret.
- Use the PayPal Sandbox before switching to Live.
- Record PayPal order and capture IDs.
- Use unique idempotency values with the `PayPal-Request-Id` header.
- Validate product prices on the server.
- Do not fulfill an order merely because the browser runs `onApprove`.
- Configure and verify PayPal webhooks such as `PAYMENT.CAPTURE.COMPLETED`.
- Add rate limiting and logging to public order-creation endpoints.
- Place custom code in a child theme so theme updates do not overwrite it.

For one-off or fixed-price payments, the PayPal-hosted button is normally preferable because PayPal handles most of the checkout logic. A full REST API integration is appropriate only when WordPress must manage dynamic order data.

Final answer: Create a PayPal-hosted button and paste its generated code into a WordPress Custom HTML block; for dynamic checkout, load the PayPal JavaScript SDK and implement server-side WordPress REST endpoints to securely create, capture, and verify PayPal orders.

